--

CREATE FUNCTION "public"."app_s6_criar_prestador"("p_nome_completo" "text", "p_cpf_cnpj" "text" DEFAULT NULL::"text", "p_data_nascimento" "text" DEFAULT NULL::"text", "p_telefone" "text" DEFAULT NULL::"text", "p_email" "text" DEFAULT NULL::"text", "p_auth_email" "text" DEFAULT NULL::"text", "p_senha" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT 'em_analise'::"text", "p_origem" "text" DEFAULT 'app_prestador'::"text", "p_liberado_app" boolean DEFAULT false, "p_metadata" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_auth_uid UUID;
