  v_perfil JSONB;
  v_disponibilidade JSONB;
  v_avaliacoes JSONB;
  v_modalidades TEXT[];
  v_distancia INTEGER;
  v_aceita_viagens BOOLEAN;
  v_restricoes JSONB;
  v_tem_talento BOOLEAN := FALSE;
BEGIN
  v_auth_uid := auth.uid();
  IF v_auth_uid IS NULL THEN
    RAISE EXCEPTION 'Acesso negado: usuário não autenticado'
      USING ERRCODE = 'P0001';
  END IF;

  v_meta := COALESCE(p_metadata, '{}'::jsonb);

  -- Perfil pode vir em metadata.perfil_talento ou direto na raiz do metadata.
  v_perfil := CASE
    WHEN jsonb_typeof(v_meta -> 'perfil_talento') = 'object' THEN v_meta -> 'perfil_talento'
    ELSE v_meta
  END;
  v_disponibilidade := CASE
    WHEN jsonb_typeof(v_meta -> 'disponibilidade') = 'array' THEN v_meta -> 'disponibilidade'
    ELSE NULL
  END;
  v_avaliacoes := CASE
    WHEN jsonb_typeof(v_meta -> 'avaliacoes') = 'array' THEN v_meta -> 'avaliacoes'
    ELSE NULL
  END;

  v_modalidades := CASE
    WHEN jsonb_typeof(v_perfil -> 'modalidade_preferencial') = 'array'
      THEN ARRAY(SELECT jsonb_array_elements_text(v_perfil -> 'modalidade_preferencial'))
    ELSE NULL
  END;

  v_distancia := CASE
    WHEN NULLIF(v_perfil ->> 'distancia_max_coleta_km', '') IS NOT NULL
      THEN (v_perfil ->> 'distancia_max_coleta_km')::integer
    ELSE NULL
  END;

  v_aceita_viagens := CASE
    WHEN NULLIF(v_perfil ->> 'aceita_viagens', '') IS NOT NULL
      THEN (v_perfil ->> 'aceita_viagens')::boolean
    ELSE NULL
  END;

  v_restricoes := CASE
    WHEN jsonb_typeof(v_perfil -> 'restricoes_operacionais') = 'object'
      THEN v_perfil -> 'restricoes_operacionais'
    ELSE NULL
  END;

  v_tem_talento := (v_meta ? 'perfil_talento')
    OR (v_meta ? 'modalidade_preferencial')
    OR (v_meta ? 'distancia_max_coleta_km')
    OR (v_meta ? 'aceita_viagens')
    OR (v_meta ? 'restricoes_operacionais')
    OR v_disponibilidade IS NOT NULL
    OR v_avaliacoes IS NOT NULL;

  -- Idempotência: reusa o prestador do auth.uid() quando já existir.
  SELECT id INTO v_existing_id
  FROM public.prestadores
  WHERE auth_user_id = v_auth_uid
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    v_new_id := v_existing_id;
  ELSE
    v_nome := trim(COALESCE(p_nome_completo, ''));
    IF v_nome = '' THEN
      RAISE EXCEPTION 'Nome completo é obrigatório'
        USING ERRCODE = 'P0002';
    END IF;

    v_cpf := CASE WHEN trim(COALESCE(p_cpf_cnpj, '')) = '' THEN NULL
                  ELSE trim(p_cpf_cnpj) END;
    v_telefone := CASE WHEN trim(COALESCE(p_telefone, '')) = '' THEN NULL
                       ELSE trim(p_telefone) END;
    v_email := CASE WHEN trim(COALESCE(p_email, '')) = '' THEN NULL
                    ELSE trim(p_email) END;

    INSERT INTO public.prestadores (
      nome_completo, cpf_cnpj, data_nascimento, telefone, email,
      auth_user_id, status, liberado_app, origem, origem_cadastro,
      metadata, created_at, updated_at
    ) VALUES (
      v_nome,
      v_cpf,
      CASE WHEN p_data_nascimento IS NOT NULL AND trim(p_data_nascimento) != ''
           THEN p_data_nascimento::date ELSE NULL END,
      v_telefone,
      v_email,
      v_auth_uid,
      'em_analise',
      false,
      COALESCE(p_origem, 'app_prestador'),
      'app_motorista',
      v_meta,
      now(),
      now()
    )
    RETURNING id INTO v_new_id;
  END IF;

  IF v_tem_talento THEN
    PERFORM public.app_s6_salvar_perfil_talento(
      v_modalidades,
      v_distancia,
      v_aceita_viagens,
      v_restricoes,
      v_disponibilidade,
      v_avaliacoes
    );
  END IF;

  RETURN jsonb_build_object('prestador_id', v_new_id);
END;
$$;


--
-- Name: app_s6_resolver_identidade_legada("text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."app_s6_resolver_identidade_legada"("p_cpf_cnpj" "text", "p_senha" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_digits  TEXT;
  v_auth_id UUID;
  v_email   TEXT;
  v_hash    TEXT;
BEGIN
  -- Entradas obrigatórias (fail-closed, sem detalhe).
  IF p_cpf_cnpj IS NULL OR p_senha IS NULL
     OR btrim(p_cpf_cnpj) = '' OR p_senha = '' THEN
    RETURN NULL;
  END IF;

  -- Normaliza CPF/CNPJ (apenas dígitos).
  v_digits := regexp_replace(btrim(p_cpf_cnpj), '[^0-9]', '', 'g');
  IF length(v_digits) < 11 THEN
    RETURN NULL;
  END IF;

  -- Identidade vinculada (no máximo uma).
  SELECT p.auth_user_id
    INTO v_auth_id
  FROM public.prestadores p
  WHERE p.auth_user_id IS NOT NULL
    AND regexp_replace(coalesce(p.cpf_cnpj, ''), '[^0-9]', '', 'g') = v_digits
  LIMIT 1;

  IF v_auth_id IS NULL THEN
    RETURN NULL;
  END IF;

  -- auth.users SOMENTE pelo vínculo objetivo auth_user_id.
  SELECT u.email, u.encrypted_password
    INTO v_email, v_hash
  FROM auth.users u
  WHERE u.id = v_auth_id
  LIMIT 1;

  IF v_email IS NULL OR v_hash IS NULL THEN
    RETURN NULL;
  END IF;

  -- Verifica a senha (bcrypt) SEM persistir/logar. Divergência → NULL.
  IF extensions.crypt(p_senha, v_hash) <> v_hash THEN
    RETURN NULL;
  END IF;

  RETURN v_email;
EXCEPTION
  WHEN OTHERS THEN
    -- Nunca vaza detalhe/exceção (indistinguível).
    RETURN NULL;
END;
$$;


--
-- Name: FUNCTION "app_s6_resolver_identidade_legada"("p_cpf_cnpj" "text", "p_senha" "text"); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."app_s6_resolver_identidade_legada"("p_cpf_cnpj" "text", "p_senha" "text") IS 'E2E-05E: resolve o e-mail de auth de prestador LEGADO (CPF+senha). Indistinguível em falha; senha nunca persistida/logada.';


--
-- Name: app_s6_salvar_perfil_talento("text"[], integer, boolean, "jsonb", "jsonb", "jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."app_s6_salvar_perfil_talento"("p_modalidade_preferencial" "text"[] DEFAULT NULL::"text"[], "p_distancia_max_coleta_km" integer DEFAULT NULL::integer, "p_aceita_viagens" boolean DEFAULT NULL::boolean, "p_restricoes_operacionais" "jsonb" DEFAULT NULL::"jsonb", "p_disponibilidade" "jsonb" DEFAULT NULL::"jsonb", "p_avaliacoes" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_auth_uid uuid;
  v_prestador_id uuid;
  v_tenant_id uuid;
  v_perfil_id uuid;
  v_item jsonb;
  v_cenario_id uuid;
  v_total_disp integer := 0;
  v_total_aval integer := 0;
BEGIN
  v_auth_uid := auth.uid();
  IF v_auth_uid IS NULL THEN
    RAISE EXCEPTION 'Acesso negado: usuário não autenticado'
      USING ERRCODE = 'P0001';
  END IF;

  SELECT id INTO v_prestador_id
  FROM public.prestadores
  WHERE auth_user_id = v_auth_uid
  ORDER BY created_at
  LIMIT 1;

  IF v_prestador_id IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error_code', 'PRESTADOR_NAO_ENCONTRADO',
      'message', 'Nenhum prestador vinculado a este usuário.'
    );
  END IF;

  v_tenant_id := COALESCE(
    public.current_tenant_id_safe(),
    '00000000-0000-0000-0000-000000000001'::uuid
  );

  INSERT INTO public.prestador_perfil_talento (
    prestador_id, tenant_id, modalidade_preferencial, distancia_max_coleta_km,
    aceita_viagens, restricoes_operacionais, created_at, updated_at
  ) VALUES (
    v_prestador_id,
    v_tenant_id,
    p_modalidade_preferencial,
    p_distancia_max_coleta_km,
    COALESCE(p_aceita_viagens, true),
    COALESCE(p_restricoes_operacionais, '{}'::jsonb),
    now(),
    now()
  )
  ON CONFLICT (prestador_id) DO UPDATE SET
    tenant_id = COALESCE(EXCLUDED.tenant_id, prestador_perfil_talento.tenant_id),
    modalidade_preferencial = COALESCE(
      EXCLUDED.modalidade_preferencial,
      prestador_perfil_talento.modalidade_preferencial
    ),
    distancia_max_coleta_km = COALESCE(
      EXCLUDED.distancia_max_coleta_km,
      prestador_perfil_talento.distancia_max_coleta_km
    ),
    aceita_viagens = CASE
      WHEN p_aceita_viagens IS NULL THEN prestador_perfil_talento.aceita_viagens
      ELSE EXCLUDED.aceita_viagens
    END,
    restricoes_operacionais = CASE
      WHEN p_restricoes_operacionais IS NULL THEN prestador_perfil_talento.restricoes_operacionais
      ELSE EXCLUDED.restricoes_operacionais
    END,
    updated_at = now()
  RETURNING id INTO v_perfil_id;

  -- Janelas de horário: substitui as janelas anteriores quando enviadas.
  IF p_disponibilidade IS NOT NULL AND jsonb_typeof(p_disponibilidade) = 'array' THEN
    DELETE FROM public.prestador_disponibilidade WHERE prestador_id = v_prestador_id;

    FOR v_item IN SELECT * FROM jsonb_array_elements(p_disponibilidade) LOOP
      IF NULLIF(v_item ->> 'dia_semana', '') IS NOT NULL THEN
        INSERT INTO public.prestador_disponibilidade (
          prestador_id, dia_semana, hora_inicio, hora_fim, disponivel, updated_at
        ) VALUES (
          v_prestador_id,
          (v_item ->> 'dia_semana')::integer,
          NULLIF(v_item ->> 'hora_inicio', '')::time,
          NULLIF(v_item ->> 'hora_fim', '')::time,
          COALESCE((v_item ->> 'disponivel')::boolean, true),
          now()
        );
        v_total_disp := v_total_disp + 1;
      END IF;
    END LOOP;
  END IF;

  -- Avaliações situacionais: upsert por (prestador, cenário).
  IF p_avaliacoes IS NOT NULL AND jsonb_typeof(p_avaliacoes) = 'array' THEN
    FOR v_item IN SELECT * FROM jsonb_array_elements(p_avaliacoes) LOOP
      v_cenario_id := NULLIF(v_item ->> 'cenario_id', '')::uuid;

      IF v_cenario_id IS NOT NULL
         AND EXISTS (SELECT 1 FROM public.recrutamento_cenarios WHERE id = v_cenario_id) THEN
        INSERT INTO public.recrutamento_avaliacoes (
          prestador_id, cenario_id, resposta_candidato, pontuacao,
          analise_ia_jsonb, created_at, updated_at
        ) VALUES (
          v_prestador_id,
          v_cenario_id,
          NULLIF(v_item ->> 'resposta_candidato', ''),
          NULLIF(v_item ->> 'pontuacao', '')::numeric,
          COALESCE(v_item -> 'analise_ia_jsonb', '{}'::jsonb),
          now(),
          now()
        )
        ON CONFLICT (prestador_id, cenario_id) DO UPDATE SET
          resposta_candidato = COALESCE(
            EXCLUDED.resposta_candidato,
            recrutamento_avaliacoes.resposta_candidato
          ),
          pontuacao = COALESCE(EXCLUDED.pontuacao, recrutamento_avaliacoes.pontuacao),
          analise_ia_jsonb = COALESCE(
            EXCLUDED.analise_ia_jsonb,
            recrutamento_avaliacoes.analise_ia_jsonb
          ),
          updated_at = now();

        v_total_aval := v_total_aval + 1;
      END IF;
    END LOOP;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'prestador_id', v_prestador_id,
    'perfil_id', v_perfil_id,
    'disponibilidade_salva', v_total_disp,
    'avaliacoes_salvas', v_total_aval
  );
END;
$$;


--
-- Name: app_s6_sincronizar_cadastro_pipeline("text", "text", "text", "jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."app_s6_sincronizar_cadastro_pipeline"("p_auth_email" "text", "p_senha" "text", "p_etapa" "text" DEFAULT 'cadastro_concluido'::"text", "p_respostas_situacionais" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_result JSONB;
  v_candidato_id UUID;
BEGIN
  IF p_respostas_situacionais IS NOT NULL
     AND jsonb_typeof(p_respostas_situacionais) <> 'object'
  THEN
    RAISE EXCEPTION 'respostas_situacionais_must_be_object';
  END IF;

  v_result := public.app_s6_sincronizar_cadastro_pipeline_base(
    p_auth_email,
    p_senha,
    p_etapa
  );

  IF v_result->>'success' <> 'true'
     OR p_respostas_situacionais IS NULL
  THEN
    RETURN v_result;
  END IF;

  v_candidato_id := NULLIF(v_result->>'candidato_id', '')::UUID;
  IF v_candidato_id IS NULL THEN
    RAISE EXCEPTION 'pipeline_sync_missing_candidate_id';
  END IF;

  UPDATE public.recrutamento_candidatos
     SET respostas_situacionais = p_respostas_situacionais
   WHERE id = v_candidato_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'pipeline_sync_candidate_not_found';
  END IF;

  RETURN v_result;
END;
$$;


--
-- Name: FUNCTION "app_s6_sincronizar_cadastro_pipeline"("p_auth_email" "text", "p_senha" "text", "p_etapa" "text", "p_respostas_situacionais" "jsonb"); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."app_s6_sincronizar_cadastro_pipeline"("p_auth_email" "text", "p_senha" "text", "p_etapa" "text", "p_respostas_situacionais" "jsonb") IS 'Sincroniza o cadastro concluído e as respostas situacionais do App Prestador ao candidato TMS.';


--
-- Name: app_s6_sincronizar_cadastro_pipeline_base("text", "text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."app_s6_sincronizar_cadastro_pipeline_base"("p_auth_email" "text", "p_senha" "text", "p_etapa" "text" DEFAULT 'cadastro_concluido'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_user auth.users%ROWTYPE;
  v_prestador public.prestadores%ROWTYPE;
  v_rp_id UUID;
  v_candidato_id UUID;
  v_etapa TEXT;
  v_cidade TEXT;
  v_uf TEXT;
  v_tipo_veiculo TEXT;
  v_placa TEXT;
  v_now_text TEXT;
  v_tags JSONB;
  v_historico JSONB;
BEGIN
  -- Prova de posse da identidade criada no signUp do App.
  SELECT *
    INTO v_user
    FROM auth.users
   WHERE lower(email) = lower(btrim(COALESCE(p_auth_email, '')));

  IF v_user.id IS NULL
     OR v_user.encrypted_password IS NULL
     OR v_user.encrypted_password = ''
     OR v_user.encrypted_password <> crypt(COALESCE(p_senha, ''), v_user.encrypted_password)
  THEN
    RAISE EXCEPTION 'invalid_credentials';
  END IF;

  SELECT *
    INTO v_prestador
    FROM public.prestadores
   WHERE auth_user_id = v_user.id
   ORDER BY created_at
   LIMIT 1;

  IF v_prestador.id IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error_code', 'PRESTADOR_NAO_ENCONTRADO',
      'message', 'Nenhum prestador vinculado a esta identidade.'
    );
  END IF;

  -- Somente etapas canônicas do funil de 17 etapas são aceitas.
  v_etapa := btrim(COALESCE(p_etapa, ''));
  IF v_etapa NOT IN (
    'novo_candidato', 'cadastro_iniciado', 'cadastro_concluido',
    'em_triagem', 'em_analise_perfil', 'aguardando_documentacao',
    'em_verificacao_documental', 'em_avaliacao_situacional',
    'em_entrevista', 'em_homologacao', 'aprovado', 'reprovado',
    'cadastro_incompleto', 'banco_de_talentos', 'homologado_disponivel',
    'homologado_indisponivel', 'processo_encerrado'
  ) THEN
    v_etapa := 'cadastro_concluido';
  END IF;

  v_cidade := COALESCE(
    v_prestador.endereco->>'cidade',
    v_prestador.metadata->'endereco'->>'cidade',
    ''
  );
  v_uf := COALESCE(
    v_prestador.endereco->>'uf',
    v_prestador.endereco->>'estado',
    v_prestador.metadata->'endereco'->>'uf',
    ''
  );
  v_tipo_veiculo := COALESCE(
    v_prestador.metadata->'veiculo'->>'tipo',
    v_prestador.metadata->>'tipo_veiculo',
    ''
  );
  v_placa := COALESCE(v_prestador.metadata->'veiculo'->>'placa', '');
  v_now_text := to_char(NOW(), 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"');

  v_tags := jsonb_build_array(
    'app_motorista',
    'bridge_automatico',
    'etapa:' || v_etapa
  );

  v_historico := jsonb_build_array(
    jsonb_build_object(
      'tipo', 'mudou_etapa',
      'descricao', 'Cadastro concluído no App Prestador → Cadastro Concluído (Etapa 3 de 17)',
      'data', v_now_text,
      'stageNovo', v_etapa
    )
  );

  -- Reutiliza a entidade de recrutamento já criada pelo bridge (ou cria uma),
  -- mantendo o vínculo canônico candidato -> recrutamento_prestadores.
  IF COALESCE(v_prestador.cpf_cnpj, '') != '' THEN
    SELECT id INTO v_rp_id
    FROM public.recrutamento_prestadores
    WHERE cpf_cnpj = v_prestador.cpf_cnpj
    LIMIT 1;
  END IF;

  IF v_rp_id IS NULL THEN
    INSERT INTO public.recrutamento_prestadores (
      nome, cpf_cnpj, contatos, endereco, tipo_veiculo, placa_veiculo,
      status, origem_cadastro, data_cadastro, ultima_atividade,
      created_at, updated_at
    ) VALUES (
      COALESCE(v_prestador.nome_completo, 'Sem nome'),
      COALESCE(v_prestador.cpf_cnpj, ''),
      jsonb_build_array(
        jsonb_build_object('tipo', 'telefone', 'valor', COALESCE(v_prestador.telefone, v_prestador.whatsapp, ''), 'principal', true),
        jsonb_build_object('tipo', 'email', 'valor', COALESCE(v_prestador.email, ''), 'principal', false)
      ),
      jsonb_build_object('cidade', v_cidade, 'estado', v_uf),
      v_tipo_veiculo, v_placa,
      'novo', 'app_motorista', v_now_text, v_now_text,
      NOW(), NOW()
    )
    RETURNING id INTO v_rp_id;
  END IF;

  SELECT id
    INTO v_candidato_id
    FROM public.recrutamento_candidatos
   WHERE prestador_id = v_rp_id
   ORDER BY created_at
   LIMIT 1;

  IF v_candidato_id IS NULL THEN
    INSERT INTO public.recrutamento_candidatos (
      nome, telefone, email, cidade, uf, veiculo, placa,
      stage, status_documental, prioridade, validade_cnh, tags,
      observacoes_ia, data_entrada, data_atualizacao, prestador_id, historico
    ) VALUES (
      COALESCE(v_prestador.nome_completo, 'Sem nome'),
      COALESCE(v_prestador.telefone, v_prestador.whatsapp, ''),
      COALESCE(v_prestador.email, ''),
      v_cidade,
      v_uf,
      v_tipo_veiculo,
      v_placa,
      v_etapa,
      'pendente',
      'media',
      'valida',
      v_tags,
      '[APP-S6] Cadastro concluído no App Prestador. Etapa 3 de 17 (cadastro_concluido).',
      v_now_text,
      v_now_text,
      v_rp_id,
      v_historico
    )
    RETURNING id INTO v_candidato_id;
  ELSE
    UPDATE public.recrutamento_candidatos
       SET nome = COALESCE(NULLIF(v_prestador.nome_completo, ''), nome),
           telefone = COALESCE(NULLIF(v_prestador.telefone, ''), NULLIF(v_prestador.whatsapp, ''), telefone),
           email = COALESCE(NULLIF(v_prestador.email, ''), email),
           cidade = COALESCE(NULLIF(v_cidade, ''), cidade),
           uf = COALESCE(NULLIF(v_uf, ''), uf),
           veiculo = COALESCE(NULLIF(v_tipo_veiculo, ''), veiculo),
           placa = COALESCE(NULLIF(v_placa, ''), placa),
           stage = v_etapa,
           tags = COALESCE(tags, '[]'::jsonb) || v_tags,
           observacoes_ia = '[APP-S6] Cadastro concluído no App Prestador. Etapa 3 de 17 (cadastro_concluido).',
           data_atualizacao = v_now_text,
           updated_at = NOW(),
           historico = COALESCE(historico, '[]'::jsonb) || v_historico
     WHERE id = v_candidato_id;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'prestador_id', v_prestador.id,
    'recrutamento_prestador_id', v_rp_id,
    'candidato_id', v_candidato_id,
    'etapa_pipeline', v_etapa,
    'etapa_pipeline_id', 3,
    'etapa_pipeline_total', 17
  );
END;
$$;


--
-- Name: FUNCTION "app_s6_sincronizar_cadastro_pipeline_base"("p_auth_email" "text", "p_senha" "text", "p_etapa" "text"); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."app_s6_sincronizar_cadastro_pipeline_base"("p_auth_email" "text", "p_senha" "text", "p_etapa" "text") IS 'APP-S6: sincroniza o cadastro concluído no App com recrutamento_candidatos (Etapa 3 de 17). Idempotente por recrutamento_prestadores.';


--
-- Name: app_s6_sync_preferencias_operacionais_candidato(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."app_s6_sync_preferencias_operacionais_candidato"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_preferencias JSONB;
BEGIN
  IF NEW.prestador_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT p.metadata->'preferencias_operacionais'
    INTO v_preferencias
    FROM public.recrutamento_prestadores rp
    JOIN public.prestadores p
      ON p.cpf_cnpj = rp.cpf_cnpj
   WHERE rp.id = NEW.prestador_id
     AND p.metadata ? 'preferencias_operacionais'
   ORDER BY p.created_at DESC
   LIMIT 1;

  IF jsonb_typeof(v_preferencias) = 'object' THEN
    NEW.preferencias_operacionais := v_preferencias;
  END IF;

  RETURN NEW;
END;
$$;


