--
-- Name: f_aceitar_oportunidade_rede("uuid", "uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."f_aceitar_oportunidade_rede"("p_oportunidade_id" "uuid", "p_prestador_uuid" "uuid", "p_auth_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_os_id UUID;
  v_status_oportunidade rede_oportunidade_status;
  v_prestador_status TEXT;
  v_os_status TEXT;
  v_os_record RECORD;
  v_alocacao_id UUID;
  v_rota_id UUID;
  v_cliente_id UUID;
  v_veiculo_necessario JSONB;
  v_valor_prestador NUMERIC;
  v_tipo_operacao TEXT;
  v_tipo_reversa TEXT;
  v_operation_mode TEXT;
BEGIN
  IF p_auth_user_id IS NOT NULL THEN
    IF NOT EXISTS (SELECT 1 FROM auth.users WHERE id = p_auth_user_id) THEN
      RETURN jsonb_build_object('sucesso', false, 'erro', 'Usuário de autenticação inválido');
    END IF;
  END IF;
  SELECT r.os_id, r.status, r.valor_prestador, r.veiculo_necessario
  INTO v_os_id, v_status_oportunidade, v_valor_prestador, v_veiculo_necessario
  FROM public.rede_oportunidades r WHERE r.id = p_oportunidade_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('sucesso', false, 'erro', 'Oportunidade não encontrada');
  END IF;
  IF v_status_oportunidade NOT IN ('publicada', 'visualizada', 'interessada') THEN
    RETURN jsonb_build_object('sucesso', false, 'erro', format('Oportunidade no estado %s não pode ser aceita', v_status_oportunidade));
  END IF;
  SELECT status INTO v_prestador_status FROM public.prestadores WHERE id = p_prestador_uuid;
  IF v_prestador_status IS NULL THEN
    RETURN jsonb_build_object('sucesso', false, 'erro', 'Prestador não encontrado');
  END IF;
  IF v_prestador_status != 'ativo' THEN
    RETURN jsonb_build_object('sucesso', false, 'erro', 'Prestador não está ativo');
  END IF;
  SELECT * INTO v_os_record FROM public.ordens_servico WHERE id = v_os_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('sucesso', false, 'erro', 'OS vinculada não encontrada');
  END IF;
  IF v_os_record.status IN ('finalizada', 'cancelada', 'entregue') THEN
    RETURN jsonb_build_object('sucesso', false, 'erro', 'OS não pode mais receber prestador');
  END IF;
  v_os_status := v_os_record.status;
  v_tipo_operacao := COALESCE(v_os_record.tipo_operacao, '');
  v_tipo_reversa := COALESCE(v_os_record.tipo_reversa, 'sem_reversa');
  v_cliente_id := CASE
    WHEN v_os_record.cliente_id ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    THEN v_os_record.cliente_id::uuid
    ELSE NULL
  END;
  IF v_tipo_operacao ILIKE '%multiparada%' OR v_tipo_operacao ILIKE '%e-commerce%' OR v_tipo_operacao ILIKE '%distribuição%' OR v_tipo_operacao ILIKE '%distribuicao%' THEN
    v_operation_mode := 'multi_stop_route';
  ELSIF v_tipo_reversa != 'sem_reversa' THEN
    v_operation_mode := 'reverse_logistics';
  ELSE
    v_operation_mode := 'standard_delivery';
  END IF;
  UPDATE public.rede_oportunidades SET status = 'aceita', prestador_aceite_id = p_prestador_uuid, aceite_em = NOW()
  WHERE id = p_oportunidade_id;
  UPDATE public.ordens_servico SET prestador_id = p_prestador_uuid::TEXT, prestador = p_prestador_uuid,
    status = CASE WHEN v_os_status IN ('pendente', 'rascunho') THEN 'agendada' ELSE v_os_status END
  WHERE id = v_os_id;
  IF EXISTS (SELECT 1 FROM public.alocacoes_escala WHERE ordem_servico_id = v_os_id) THEN
    UPDATE public.alocacoes_escala SET
      prestador_id = p_prestador_uuid,
      status = 'aceita',
      cliente_id = COALESCE(cliente_id, v_cliente_id),
      valor_frete = COALESCE(v_os_record.valor_cliente, 0),
      valor_repasse = COALESCE(v_valor_prestador, v_os_record.custo_prestador, 0),
      aceite_prestador = true,
      data_aceite = NOW(),
      tipo_reversa = CASE WHEN alocacoes_escala.tipo_reversa = 'sem_reversa' THEN v_tipo_reversa ELSE alocacoes_escala.tipo_reversa END,
      metadata = alocacoes_escala.metadata
        || jsonb_build_object('aceite_tipo', 'rede_enterprise', 'operation_mode', v_operation_mode, 'os_numero', v_os_record.numero)
        || jsonb_build_object('app_motorista',
             COALESCE(alocacoes_escala.metadata->'app_motorista', '{}'::jsonb)
             || jsonb_build_object('etapa_atual', 'viagem_aceita', 'ultima_acao', 'viagem_aceita',
                                   'aceite_em', to_jsonb(NOW())))
    WHERE ordem_servico_id = v_os_id
    RETURNING id INTO v_alocacao_id;
  ELSE
    INSERT INTO public.alocacoes_escala (ordem_servico_id, prestador_id, cliente_id, status, data_escala, tipo_veiculo, placa, origem, destino, valor_frete, valor_repasse, km_previstos, aceite_prestador, data_aceite, tipo_reversa, observacoes, metadata)
    VALUES (v_os_id, p_prestador_uuid, v_cliente_id, 'aceita', COALESCE(v_os_record.data_programada, CURRENT_DATE),
      COALESCE(v_veiculo_necessario->>'tipo', v_os_record.veiculo_tipo, ''), v_os_record.placa_alocada,
      CASE WHEN v_os_record.enderecos IS NOT NULL AND jsonb_array_length(v_os_record.enderecos::jsonb) > 0 THEN v_os_record.enderecos::jsonb->0->>'cidade' ELSE v_os_record.origem END,
      CASE WHEN v_os_record.enderecos IS NOT NULL AND jsonb_array_length(v_os_record.enderecos::jsonb) > 1 THEN v_os_record.enderecos::jsonb->jsonb_array_length(v_os_record.enderecos::jsonb)-1->>'cidade' ELSE v_os_record.destino END,
      COALESCE(v_os_record.valor_cliente, 0), COALESCE(v_valor_prestador, v_os_record.custo_prestador, 0),
      v_os_record.distancia_km, true, NOW(), v_tipo_reversa, v_os_record.observacoes_gerais,
      jsonb_build_object('aceite_tipo', 'rede_enterprise', 'oportunidade_id', p_oportunidade_id, 'origem', 'rede_prestadores', 'operation_mode', v_operation_mode, 'tipo_operacao', v_tipo_operacao, 'os_numero', v_os_record.numero,
        'app_motorista', jsonb_build_object('etapa_atual', 'viagem_aceita', 'ultima_acao', 'viagem_aceita', 'aceite_em', NOW())))
    RETURNING id INTO v_alocacao_id;
  END IF;
  IF v_operation_mode = 'multi_stop_route' AND v_os_record.enderecos IS NOT NULL THEN
    IF EXISTS (SELECT 1 FROM public.rotas WHERE os_id = v_os_id) THEN
      UPDATE public.rotas SET prestador_id = p_prestador_uuid, status = 'em_andamento'
      WHERE os_id = v_os_id
      RETURNING id INTO v_rota_id;
    ELSE
      INSERT INTO public.rotas (os_id, cliente_id, data_rota, status, origem, distancia_km, duracao_min, peso_total, volumes_total, prestador_id, tipo_rota, metadata)
      VALUES (v_os_id, v_cliente_id, COALESCE(v_os_record.data_programada, CURRENT_DATE), 'em_andamento',
        CASE WHEN jsonb_array_length(v_os_record.enderecos::jsonb) > 0 THEN v_os_record.enderecos::jsonb->0->>'cidade' ELSE v_os_record.origem END,
        v_os_record.distancia_km, v_os_record.tempo_minutos, v_os_record.peso, v_os_record.volumes, p_prestador_uuid,
        CASE WHEN v_tipo_operacao ILIKE '%refrigerado%' THEN 'refrigerada' ELSE 'seca' END,
        jsonb_build_object('operation_mode', v_operation_mode, 'alocacao_id', v_alocacao_id, 'tipo_operacao', v_tipo_operacao))
      RETURNING id INTO v_rota_id;
    END IF;
    INSERT INTO public.rota_paradas (rota_id, sequencia, cliente_nome, endereco, numero, bairro, cidade, uf, cep, latitude, longitude, peso, volumes, cubagem, temperatura, observacoes, status)
    SELECT v_rota_id, seq,
      COALESCE(e->>'nome_destinatario', e->>'nome', ''), COALESCE(e->>'logradouro', e->>'endereco', ''),
      COALESCE(e->>'numero', ''), COALESCE(e->>'bairro', ''), COALESCE(e->>'cidade', ''), COALESCE(e->>'uf', ''),
      COALESCE(e->>'cep', ''), COALESCE((e->>'latitude')::numeric, NULL), COALESCE((e->>'longitude')::numeric, NULL),
      v_os_record.peso / GREATEST(jsonb_array_length(v_os_record.enderecos::jsonb), 1),
      GREATEST(CEIL(COALESCE(v_os_record.volumes, 0) / GREATEST(jsonb_array_length(v_os_record.enderecos::jsonb), 1)), 1),
      v_os_record.cubagem / GREATEST(jsonb_array_length(v_os_record.enderecos::jsonb), 1),
      CASE WHEN v_os_record.carga_refrigerada THEN 'refrigerada' ELSE 'seca' END,
      COALESCE(e->>'instrucoes', e->>'observacoes', ''), 'pendente'
    FROM jsonb_array_elements(v_os_record.enderecos::jsonb) WITH ORDINALITY AS e(elem, seq)
    ON CONFLICT DO NOTHING;
  END IF;
  INSERT INTO public.portal_notificacoes (prestador_id, titulo, mensagem, tipo, origem_id, origem_tipo, lida, created_at)
  VALUES (p_prestador_uuid, 'Nova operação disponível',
    format('Você aceitou a oportunidade #%s. Operação: %s.', UPPER(SUBSTRING(v_os_id::TEXT, 1, 8)), v_operation_mode),
    'oportunidade_aceita', v_os_id, 'rede_oportunidades', false, NOW());
  INSERT INTO public.os_historico (os_id, acao, status_novo, usuario)
  VALUES (v_os_id, format('Prestador aceitou via Rede [mode=%s]', v_operation_mode), 'agendada',
          CASE WHEN p_auth_user_id IS NOT NULL THEN p_auth_user_id::TEXT ELSE 'Sistema Rede' END);
  DELETE FROM public.rede_visualizacoes WHERE oportunidade_id = p_oportunidade_id AND prestador_id != p_prestador_uuid;
  RETURN jsonb_build_object('sucesso', true, 'os_id', v_os_id, 'alocacao_id', v_alocacao_id, 'rota_id', v_rota_id, 'prestador_id', p_prestador_uuid, 'operation_mode', v_operation_mode,
    'mensagem', format('Oportunidade aceita. Modo: %s. Alocação criada.', v_operation_mode));
END;
$_$;


--
-- Name: f_aprovar_pagamento_prestadores("uuid"[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."f_aprovar_pagamento_prestadores"("p_ids" "uuid"[]) RETURNS TABLE("solicitados" integer, "aprovados" integer, "ja_aprovados" integer, "bloqueados" integer, "detalhes" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant uuid;
  v_papel text;
  v_ids uuid[];
  v_total int;
  v_aprovaveis uuid[];
  v_bloqueados int;
  v_ja int;
  v_detalhes jsonb;
  v_papeis_autorizados text[] := ARRAY['super_admin','admin_tenant','financeiro'];
BEGIN
  v_ids := ARRAY(SELECT DISTINCT x FROM unnest(COALESCE(p_ids, ARRAY[]::uuid[])) AS x WHERE x IS NOT NULL);
  v_total := COALESCE(cardinality(v_ids), 0);

  IF v_uid IS NULL THEN
    RETURN QUERY SELECT v_total, 0, 0, v_total,
      jsonb_build_array(jsonb_build_object('resultado','BLOQUEADO','motivo','USUARIO_NAO_AUTENTICADO'));
    RETURN;
  END IF;

  SELECT tu.tenant_id, tu.papel INTO v_tenant, v_papel
    FROM public.tenant_usuarios tu
   WHERE tu.user_id = v_uid AND tu.status = 'ativo'
   LIMIT 1;

  IF v_tenant IS NULL THEN
    RETURN QUERY SELECT v_total, 0, 0, v_total,
      jsonb_build_array(jsonb_build_object('resultado','BLOQUEADO','motivo','USUARIO_SEM_TENANT_ATIVO'));
    RETURN;
  END IF;

  IF NOT (COALESCE(v_papel,'') = ANY(v_papeis_autorizados)) THEN
    RETURN QUERY SELECT v_total, 0, 0, v_total,
      jsonb_build_array(jsonb_build_object('resultado','BLOQUEADO','motivo','PAPEL_NAO_AUTORIZADO','papel',COALESCE(v_papel,'')));
    RETURN;
  END IF;

  IF v_total = 0 THEN
    RETURN QUERY SELECT 0, 0, 0, 0, '[]'::jsonb;
    RETURN;
  END IF;

  DROP TABLE IF EXISTS tmp_class;
  DROP TABLE IF EXISTS tmp_missing;
  CREATE TEMP TABLE tmp_class ON COMMIT DROP AS
  WITH base AS (
    SELECT p.id,
           p.os_id,
           p.origem_lancamento,
           p.prestador_id,
           COALESCE(p.valor_liquido, 0) AS valor_liquido,
           p.status,
           p.status_pagamento,
           p.status_conferencia,
           p.status_aprovacao,
           p.elegivel_lote,
           p.is_teste,
           public.f_pp_tenant_id(p.os_id) AS row_tenant,
           (SELECT o.status FROM public.ordens_servico o WHERE o.id = p.os_id) AS os_status,
           (SELECT a.status FROM public.alocacoes_escala a WHERE a.id = p.os_id) AS aloc_status,
           EXISTS (SELECT 1 FROM public.entregas_protocolo e
                    WHERE (e.alocacao_id = p.os_id OR e.ordem_servico_id = p.os_id)
                      AND e.status = 'nao_entregue') AS pod_nao_entregue
      FROM public.pagamentos_prestadores p
     WHERE p.id = ANY(v_ids)
  )
  SELECT b.id,
    CASE
      WHEN b.row_tenant IS NULL AND COALESCE(b.origem_lancamento,'') <> 'manual' THEN 'SEM_TENANT'
      WHEN b.row_tenant IS NOT NULL AND b.row_tenant <> v_tenant THEN 'CROSS_TENANT'
      WHEN COALESCE(b.os_status,'') = 'cancelada' OR COALESCE(b.aloc_status,'') = 'cancelada' THEN 'OPERACAO_CANCELADA'
      WHEN COALESCE(b.status_pagamento,'') = 'pago' OR COALESCE(b.status,'') = 'pago' THEN 'PAGO'
      WHEN COALESCE(b.status_pagamento,'') = 'cancelado' OR COALESCE(b.status_conferencia,'') = 'cancelado' OR COALESCE(b.status,'') = 'cancelado' THEN 'CANCELADO'
      WHEN COALESCE(b.status_aprovacao,'') = 'rejeitado' THEN 'REJEITADO'
      WHEN b.prestador_id IS NULL THEN 'SEM_PRESTADOR'
      WHEN b.valor_liquido <= 0 THEN 'VALOR_INVALIDO'
      WHEN b.is_teste IS TRUE THEN 'TESTE'
      WHEN b.pod_nao_entregue THEN 'POD_NAO_ENTREGUE'
      WHEN COALESCE(b.status_aprovacao,'') = 'aprovado' AND b.elegivel_lote IS TRUE THEN 'JA_APROVADO'
      WHEN COALESCE(b.status_aprovacao,'') = 'aprovado' AND b.elegivel_lote IS NOT TRUE THEN 'APROVADO_NAO_ELEGIVEL'
      ELSE 'APROVAVEL'
    END AS resultado
  FROM base b;

  CREATE TEMP TABLE tmp_missing ON COMMIT DROP AS
  SELECT x AS id, 'NAO_ENCONTRADO'::text AS resultado
    FROM unnest(v_ids) x
   WHERE NOT EXISTS (SELECT 1 FROM tmp_class c WHERE c.id = x);

  SELECT count(*)::int INTO v_ja FROM tmp_class WHERE resultado = 'JA_APROVADO';
  SELECT count(*)::int INTO v_bloqueados
    FROM (SELECT resultado FROM tmp_class WHERE resultado NOT IN ('APROVAVEL','JA_APROVADO')
          UNION ALL SELECT resultado FROM tmp_missing) z;
  v_aprovaveis := ARRAY(SELECT id FROM tmp_class WHERE resultado = 'APROVAVEL');

  v_detalhes := COALESCE((
    SELECT jsonb_agg(jsonb_build_object(
      'id', id,
      'resultado', resultado,
      'motivo', CASE resultado
        WHEN 'SEM_TENANT' THEN 'Tenant do vinculo (os_id) nao resolvivel'
        WHEN 'CROSS_TENANT' THEN 'Registro pertence a outro tenant'
        WHEN 'OPERACAO_CANCELADA' THEN 'Operacao/OS vinculada cancelada'
        WHEN 'PAGO' THEN 'Pagamento ja efetuado'
        WHEN 'CANCELADO' THEN 'Pagamento cancelado'
        WHEN 'REJEITADO' THEN 'Aprovacao rejeitada (reaprovacao nao permitida)'
        WHEN 'SEM_PRESTADOR' THEN 'Sem prestador vinculado'
        WHEN 'VALOR_INVALIDO' THEN 'Valor liquido <= 0'
        WHEN 'TESTE' THEN 'Registro de teste/HML'
        WHEN 'POD_NAO_ENTREGUE' THEN 'Entrega registrada como nao entregue'
        WHEN 'APROVADO_NAO_ELEGIVEL' THEN 'Estado inconsistente: aprovado mas nao elegivel'
        WHEN 'JA_APROVADO' THEN 'Ja aprovado (no-op)'
        WHEN 'NAO_ENCONTRADO' THEN 'Registro nao encontrado'
        ELSE 'Erro desconhecido'
      END)) FROM (SELECT id, resultado FROM tmp_class UNION ALL SELECT id, resultado FROM tmp_missing) d
  ), '[]'::jsonb);

  IF v_bloqueados > 0 THEN
    RETURN QUERY SELECT v_total, 0, v_ja, v_bloqueados, v_detalhes;
    RETURN;
  END IF;

  UPDATE public.pagamentos_prestadores p
     SET status_conferencia = 'conferido',
         status_aprovacao   = 'aprovado',
         elegivel_lote      = true,
         data_conferencia   = COALESCE(p.data_conferencia, now()),
         data_aprovacao     = COALESCE(p.data_aprovacao, now())
   WHERE p.id = ANY(v_aprovaveis)
     AND COALESCE(p.status_pagamento,'') NOT IN ('pago','cancelado')
     AND COALESCE(p.status_conferencia,'') <> 'cancelado'
     AND COALESCE(p.status_aprovacao,'') <> 'rejeitado';

  RETURN QUERY SELECT v_total, cardinality(v_aprovaveis), v_ja, 0, v_detalhes;
END;
$$;


--
-- Name: FUNCTION "f_aprovar_pagamento_prestadores"("p_ids" "uuid"[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."f_aprovar_pagamento_prestadores"("p_ids" "uuid"[]) IS 'TMS-FIN-PROG-05D.6B.1: aprova pagamentos_prestadores (provisao->conferido/aprovado/elegivel) do proprio tenant e de papel admin/financeiro (super_admin/admin_tenant/financeiro). Bloqueia estado inconsisten-te aprovado+nao_elegivel. Atomica e idempotente.';


--
-- Name: f_atualizar_etapa_app("uuid", "text", "jsonb", "text", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."f_atualizar_etapa_app"("p_alocacao_id" "uuid", "p_etapa" "text", "p_payload" "jsonb" DEFAULT '{}'::"jsonb", "p_idempotency_key" "text" DEFAULT ''::"text", "p_auth_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_authenticated_uid UUID;
    v_prestador_id UUID;
    v_alocacao RECORD;
    v_etapa_atual TEXT;
    v_ultima_idempotency TEXT;
    v_updated_meta JSONB;
    v_app_meta JSONB;
    v_status_update TEXT;
    v_allowed BOOLEAN;
    v_event_id UUID;
    v_tenant_id UUID;
    v_os_id TEXT;
BEGIN
    v_authenticated_uid := auth.uid();
    IF v_authenticated_uid IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'USUARIO_NAO_AUTENTICADO');
    END IF;

    IF p_auth_user_id IS NOT NULL AND p_auth_user_id <> v_authenticated_uid THEN
        RETURN jsonb_build_object('success', false, 'error', 'AUTH_USER_ID_INVALIDO');
    END IF;

    SELECT id INTO v_prestador_id
    FROM public.prestadores
    WHERE auth_user_id = v_authenticated_uid;

    IF v_prestador_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'PRESTADOR_NAO_ENCONTRADO');
    END IF;

    SELECT ae.*,
           ae.metadata->'app_motorista'->>'etapa_atual' AS etapa_atual,
           ae.metadata->'app_motorista'->>'ultima_idempotency' AS ultima_idempotency
    INTO v_alocacao
    FROM public.alocacoes_escala ae
    WHERE ae.id = p_alocacao_id;

    IF v_alocacao.id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'ALOCACAO_NAO_ENCONTRADA');
    END IF;

    IF v_alocacao.prestador_id IS DISTINCT FROM v_prestador_id THEN
        RETURN jsonb_build_object('success', false, 'error', 'ALOCACAO_OUTRO_PRESTADOR');
    END IF;

    v_tenant_id := v_alocacao.tenant_id;
    v_os_id := v_alocacao.ordem_servico_id;

    IF v_alocacao.status IN ('cancelada', 'recusada') THEN
        RETURN jsonb_build_object('success', false, 'error', 'OPERACAO_CANCELADA');
    END IF;

    IF v_alocacao.status = 'concluida' OR (v_alocacao.metadata->'app_motorista'->>'servico_finalizado')::BOOLEAN = true THEN
        RETURN jsonb_build_object('success', false, 'error', 'OPERACAO_FINALIZADA');
    END IF;

    v_etapa_atual := COALESCE(v_alocacao.etapa_atual, '');
    v_ultima_idempotency := COALESCE(v_alocacao.ultima_idempotency, '');

    IF p_idempotency_key IS NOT NULL AND p_idempotency_key <> '' AND p_idempotency_key = v_ultima_idempotency THEN
        RETURN jsonb_build_object(
            'success', true,
            'message', 'Etapa já registrada (idempotente).',
            'etapa', p_etapa,
            'idempotent', true
        );
    END IF;

    v_allowed := false;

    IF v_etapa_atual = '' AND p_etapa = 'viagem_aceita' THEN v_allowed := true; END IF;
    IF v_etapa_atual = 'viagem_aceita' AND p_etapa = 'cheguei_coleta' THEN v_allowed := true; END IF;
    IF v_etapa_atual = 'cheguei_coleta' AND p_etapa = 'carregamento_iniciado' THEN v_allowed := true; END IF;
    IF v_etapa_atual = 'carregamento_iniciado' AND p_etapa = 'carregamento_finalizado' THEN v_allowed := true; END IF;
    IF v_etapa_atual = 'carregamento_finalizado' AND p_etapa IN ('romaneio_informado', 'foto_romaneio', 'km_inicial_informado', 'saiu_em_rota') THEN v_allowed := true; END IF;
    IF v_etapa_atual = 'romaneio_informado' AND p_etapa IN ('foto_romaneio', 'km_inicial_informado') THEN v_allowed := true; END IF;
    IF v_etapa_atual = 'foto_romaneio' AND p_etapa = 'km_inicial_informado' THEN v_allowed := true; END IF;
    IF v_etapa_atual = 'km_inicial_informado' AND p_etapa = 'saiu_em_rota' THEN v_allowed := true; END IF;
    IF v_etapa_atual = 'saiu_em_rota' AND p_etapa = 'chegou_entrega' THEN v_allowed := true; END IF;
    IF v_etapa_atual = 'chegou_entrega' AND p_etapa = 'descarregamento_iniciado' THEN v_allowed := true; END IF;
    IF v_etapa_atual = 'descarregamento_iniciado' AND p_etapa = 'descarga_finalizada' THEN v_allowed := true; END IF;
    IF v_etapa_atual = 'descarga_finalizada' AND p_etapa = 'km_final_informado' THEN v_allowed := true; END IF;
    IF v_etapa_atual = 'km_final_informado' AND p_etapa = 'assinatura_capturada' THEN v_allowed := true; END IF;
    IF v_etapa_atual = 'assinatura_capturada' AND p_etapa = 'pod_registrado' THEN v_allowed := true; END IF;
    IF v_etapa_atual = 'pod_registrado' AND p_etapa = 'servico_finalizado' THEN v_allowed := true; END IF;

    IF NOT v_allowed THEN
        RETURN jsonb_build_object(
            'success', false, 'error', 'TRANSICAO_INVALIDA',
            'message', format('de "%s" para "%s"', v_etapa_atual, p_etapa),
            'etapa_atual', v_etapa_atual,
            'etapa_solicitada', p_etapa
        );
    END IF;

    IF p_etapa = 'servico_finalizado' THEN
        IF NOT (v_alocacao.metadata->'app_motorista'->>'pod_registrado')::BOOLEAN = true THEN
            RETURN jsonb_build_object(
                'success', false, 'error', 'FINALIZACAO_SEM_POD',
                'message', 'Operação não pode ser finalizada sem POD registrado.'
            );
        END IF;
    END IF;

    IF p_etapa = 'pod_registrado' AND NOT public.f_validar_pod_operacao(p_alocacao_id, v_authenticated_uid, v_prestador_id) THEN
  RETURN jsonb_build_object('success', false, 'error', 'POD_EVIDENCIA_OBRIGATORIA', 'message', 'POD exige evidencia valida (fotos/assinatura/recebedor) para esta operacao.');
END IF;
IF p_etapa = 'servico_finalizado' AND NOT public.f_validar_pod_operacao(p_alocacao_id, v_authenticated_uid, v_prestador_id) THEN
  RETURN jsonb_build_object('success', false, 'error', 'POD_EVIDENCIA_OBRIGATORIA', 'message', 'Finalizacao exige POD valido.');
END IF;
    v_app_meta := COALESCE(v_alocacao.metadata->'app_motorista', '{}'::JSONB);

    v_app_meta := jsonb_set(v_app_meta, '{etapa_atual}', to_jsonb(p_etapa));
    v_app_meta := jsonb_set(v_app_meta, '{ultima_acao}', to_jsonb(p_etapa));
    v_app_meta := jsonb_set(v_app_meta, '{atualizado_por_app}', 'true'::JSONB);

    IF p_idempotency_key IS NOT NULL AND p_idempotency_key <> '' THEN
        v_app_meta := jsonb_set(v_app_meta, '{ultima_idempotency}', to_jsonb(p_idempotency_key));
    END IF;

    IF p_payload IS NOT NULL AND p_payload <> '{}'::JSONB THEN
        v_app_meta := v_app_meta || p_payload;
    END IF;

    v_updated_meta := COALESCE(v_alocacao.metadata, '{}'::JSONB);
    v_updated_meta := jsonb_set(v_updated_meta, '{app_motorista}', v_app_meta);

    v_status_update := NULL;

    IF p_etapa = 'viagem_aceita' THEN
        v_status_update := 'aceita';
    ELSIF p_etapa = 'cheguei_coleta' THEN
        v_status_update := 'em_rota';
    ELSIF p_etapa = 'servico_finalizado' THEN
        v_status_update := 'concluida';
    END IF;

    UPDATE public.alocacoes_escala SET
        metadata = v_updated_meta,
        status = COALESCE(v_status_update, status),
        aceite_prestador = CASE WHEN p_etapa = 'viagem_aceita' THEN true ELSE aceite_prestador END,
        data_aceite = CASE WHEN p_etapa = 'viagem_aceita' THEN NOW() ELSE data_aceite END,
        horario_inicio_real = CASE WHEN p_etapa = 'cheguei_coleta' THEN NOW() ELSE horario_inicio_real END,
        horario_fim_real = CASE WHEN p_etapa = 'servico_finalizado' THEN NOW() ELSE horario_fim_real END,
        finalizada = CASE WHEN p_etapa = 'servico_finalizado' THEN true ELSE finalizada END,
        data_finalizacao = CASE WHEN p_etapa = 'servico_finalizado' THEN NOW() ELSE data_finalizacao END,
        updated_at = NOW()
    WHERE id = p_alocacao_id
      AND prestador_id = v_prestador_id;

    v_event_id := gen_random_uuid();

    INSERT INTO public.eventos_oficiais (
        id, tenant_id, event_type, entity_type, entity_id, entity_number,
        status, source, created_by, visibility, payload, metadata,
        created_at, processed_at, version, retry_count
    ) VALUES (
        v_event_id,
        v_tenant_id,
        CASE
            WHEN p_etapa = 'viagem_aceita' THEN 'operation_accepted'
            WHEN p_etapa = 'cheguei_coleta' THEN 'arrived_pickup'
            WHEN p_etapa = 'carregamento_iniciado' THEN 'loading_started'
            WHEN p_etapa = 'carregamento_finalizado' THEN 'loading_finished'
            WHEN p_etapa = 'romaneio_informado' THEN 'romaneio_informado'
            WHEN p_etapa = 'foto_romaneio' THEN 'romaneio_foto'
            WHEN p_etapa = 'km_inicial_informado' THEN 'km_registered'
            WHEN p_etapa = 'saiu_em_rota' THEN 'route_started'
            WHEN p_etapa = 'chegou_entrega' THEN 'arrived_delivery'
            WHEN p_etapa = 'descarregamento_iniciado' THEN 'unloading_started'
            WHEN p_etapa = 'descarga_finalizada' THEN 'unloading_finished'
            WHEN p_etapa = 'km_final_informado' THEN 'km_final'
            WHEN p_etapa = 'assinatura_capturada' THEN 'signature_captured'
            WHEN p_etapa = 'pod_registrado' THEN 'pod_sent'
            WHEN p_etapa = 'servico_finalizado' THEN 'operation_finished'
            ELSE p_etapa
        END,
        'alocacao',
        p_alocacao_id,
        v_os_id,
        COALESCE(v_status_update, 'em_andamento'),
        'app_motorista',
        v_prestador_id,
        'internal',
        jsonb_build_object(
            'etapa', p_etapa,
            'etapa_anterior', v_etapa_atual,
            'payload', p_payload,
            'idempotency_key', p_idempotency_key
        ),
        jsonb_build_object(
            'app_motorista', v_app_meta,
            'prestador_id', v_prestador_id
        ),
        NOW(),
        NULL,
        '1.0',
        0
    );

    INSERT INTO public.operation_timeline_events (
        id, operation_id, driver_id, type, title, metadata, event_time, created_at
    ) VALUES (
        v_event_id,
        p_alocacao_id::TEXT,
        v_prestador_id::TEXT,
        CASE
            WHEN p_etapa = 'viagem_aceita' THEN 'operation_accepted'
            WHEN p_etapa = 'cheguei_coleta' THEN 'arrived_pickup'
            WHEN p_etapa = 'carregamento_iniciado' THEN 'loading_started'
            WHEN p_etapa = 'carregamento_finalizado' THEN 'loading_finished'
            WHEN p_etapa = 'saiu_em_rota' THEN 'route_started'
            WHEN p_etapa = 'chegou_entrega' THEN 'arrived_delivery'
            WHEN p_etapa = 'descarregamento_iniciado' THEN 'unloading_started'
            WHEN p_etapa = 'descarga_finalizada' THEN 'unloading_finished'
            WHEN p_etapa = 'assinatura_capturada' THEN 'signature_captured'
            WHEN p_etapa = 'pod_registrado' THEN 'pod_sent'
            WHEN p_etapa = 'servico_finalizado' THEN 'operation_finished'
            ELSE p_etapa
        END,
        p_etapa,
        jsonb_build_object('etapa', p_etapa, 'payload', p_payload),
        NOW(),
        NOW()
    );

    RETURN jsonb_build_object(
        'success', true,
        'message', 'Etapa avançada com sucesso.',
        'etapa', p_etapa,
        'etapa_anterior', v_etapa_atual,
        'status', COALESCE(v_status_update, v_alocacao.status),
        'event_id', v_event_id,
        'idempotent', false
    );
END;
$$;


--
-- Name: f_atualizar_reversa_app("uuid", "text", integer, "text", "text", "text", timestamp with time zone, "text"[], "text", numeric, numeric, "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."f_atualizar_reversa_app"("p_alocacao_id" "uuid", "p_reversa_status" "text" DEFAULT 'coletada'::"text", "p_reversa_qtd_coletada" integer DEFAULT 0, "p_reversa_motivo_divergencia" "text" DEFAULT ''::"text", "p_reversa_responsavel" "text" DEFAULT ''::"text", "p_reversa_telefone" "text" DEFAULT ''::"text", "p_reversa_data_realizada" timestamp with time zone DEFAULT "now"(), "p_reversa_fotos" "text"[] DEFAULT '{}'::"text"[], "p_reversa_assinatura_url" "text" DEFAULT ''::"text", "p_reversa_latitude" numeric DEFAULT 0, "p_reversa_longitude" numeric DEFAULT 0, "p_auth_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_authenticated_uid UUID;
    v_prestador_id UUID;
    v_alocacao_prestador_id UUID;
    v_prev_qtd INT;
BEGIN
    v_authenticated_uid := auth.uid();
    IF v_authenticated_uid IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'USUARIO_NAO_AUTENTICADO');
    END IF;

    IF p_auth_user_id IS NOT NULL AND p_auth_user_id <> v_authenticated_uid THEN
        RETURN jsonb_build_object('success', false, 'error', 'AUTH_USER_ID_INVALIDO');
    END IF;

    SELECT id INTO v_prestador_id
    FROM public.prestadores
    WHERE auth_user_id = v_authenticated_uid;

    IF v_prestador_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'PRESTADOR_NAO_ENCONTRADO');
    END IF;

    SELECT ae.prestador_id, ae.reversa_qtd_volumes
    INTO v_alocacao_prestador_id, v_prev_qtd
    FROM public.alocacoes_escala ae
    WHERE ae.id = p_alocacao_id;

    IF v_alocacao_prestador_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'ALOCACAO_NAO_ENCONTRADA');
    END IF;

    IF v_alocacao_prestador_id IS DISTINCT FROM v_prestador_id THEN
        RETURN jsonb_build_object('success', false, 'error', 'ALOCACAO_OUTRO_PRESTADOR');
    END IF;

    IF p_reversa_qtd_coletada < 0 THEN
        RETURN jsonb_build_object('success', false, 'error', 'QUANTIDADE_INVALIDA');
    END IF;

    IF v_prev_qtd IS NOT NULL AND v_prev_qtd <> p_reversa_qtd_coletada
       AND (p_reversa_motivo_divergencia IS NULL OR p_reversa_motivo_divergencia = '') THEN
        RETURN jsonb_build_object('success', false, 'error', 'DIVERGENCIA_SEM_JUSTIFICATIVA');
    END IF;

    UPDATE public.alocacoes_escala SET
        coleta_reversa = true,
        reversa_qtd_coletada = p_reversa_qtd_coletada,
        reversa_motivo_divergencia = p_reversa_motivo_divergencia,
        reversa_responsavel = p_reversa_responsavel,
        reversa_telefone = p_reversa_telefone,
        reversa_assinatura_url = p_reversa_assinatura_url,
        reversa_latitude = p_reversa_latitude,
        reversa_longitude = p_reversa_longitude,
        reversa_data_realizada = p_reversa_data_realizada,
        reversa_status = p_reversa_status,
        reversa_fotos = p_reversa_fotos,
        updated_at = NOW()
    WHERE id = p_alocacao_id;

    RETURN jsonb_build_object(
        'success', true,
        'message', 'Reversa atualizada com sucesso.',
        'alocacao_id', p_alocacao_id,
        'reversa_status', p_reversa_status,
        'reversa_qtd_coletada', p_reversa_qtd_coletada
    );
END;
$$;


--
-- Name: f_atualizar_status_parada("uuid", "text", "text", "text", "text", "jsonb", "text", numeric, numeric, integer, "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."f_atualizar_status_parada"("p_parada_id" "uuid", "p_status" "text", "p_recebedor" "text" DEFAULT NULL::"text", "p_assinatura_url" "text" DEFAULT NULL::"text", "p_pod_url" "text" DEFAULT NULL::"text", "p_fotos" "jsonb" DEFAULT '[]'::"jsonb", "p_ocorrencia" "text" DEFAULT NULL::"text", "p_latitude_fim" numeric DEFAULT NULL::numeric, "p_longitude_fim" numeric DEFAULT NULL::numeric, "p_volumes_entregues" integer DEFAULT NULL::integer, "p_observacoes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_authenticated_uid    uuid;
    v_prestador_id         uuid;
    v_parada_id            uuid;
    v_parada_rota_id       uuid;
    v_parada_alocacao_id   uuid;
    v_parada_os_id         uuid;
    v_status_anterior      text;
    v_alocacao_prestador   uuid;
    v_os_id                uuid;
    v_total_paradas        integer;
    v_paradas_terminal     integer;
    v_rota_total           integer;
    v_rota_terminal        integer;
BEGIN
    -- ============================================================
    -- 1. Autenticação
    -- ============================================================
    v_authenticated_uid := auth.uid();
    IF v_authenticated_uid IS NULL THEN
        RETURN jsonb_build_object('sucesso', false, 'success', false, 'erro', 'USUARIO_NAO_AUTENTICADO');
    END IF;

    -- ============================================================
    -- 2. Vínculo do prestador autenticado
    -- ============================================================
    SELECT id INTO v_prestador_id
    FROM public.prestadores
    WHERE auth_user_id = v_authenticated_uid;

    IF v_prestador_id IS NULL THEN
        RETURN jsonb_build_object('sucesso', false, 'success', false, 'erro', 'PRESTADOR_NAO_ENCONTRADO');
    END IF;

    -- ============================================================
    -- 3. Validação do status aceito (mesmos valores da função atual)
    -- ============================================================
    IF p_status IS NULL OR p_status NOT IN (
        'pendente', 'em_deslocamento', 'chegou', 'entregue',
        'nao_entregue', 'ocorrencia', 'reentrega', 'devolucao', 'cancelada'
    ) THEN
        RETURN jsonb_build_object(
            'sucesso', false, 'success', false,
            'erro', 'STATUS_INVALIDO', 'status', p_status
        );
    END IF;

    -- ============================================================
    -- 4. Localizar a parada SEM JOIN com rotas (correção BUG-A21-01)
    --    rota_paradas é a fonte oficial; rota_id pode ser NULL.
    -- ============================================================
    SELECT rp.id, rp.rota_id, rp.alocacao_id, rp.os_id, rp.status
    INTO v_parada_id, v_parada_rota_id, v_parada_alocacao_id, v_parada_os_id, v_status_anterior
    FROM public.rota_paradas rp
    WHERE rp.id = p_parada_id;

    IF v_parada_id IS NULL THEN
        RETURN jsonb_build_object('sucesso', false, 'success', false, 'erro', 'Parada não encontrada');
    END IF;

    -- ============================================================
    -- 5. Contexto por alocação + pertencimento ao prestador
    -- ============================================================
    IF v_parada_alocacao_id IS NULL THEN
        RETURN jsonb_build_object('sucesso', false, 'success', false, 'erro', 'ALOCACAO_NAO_ENCONTRADA');
    END IF;

    SELECT ae.prestador_id, ae.ordem_servico_id
    INTO v_alocacao_prestador, v_os_id
    FROM public.alocacoes_escala ae
    WHERE ae.id = v_parada_alocacao_id;

    IF v_alocacao_prestador IS NULL THEN
        RETURN jsonb_build_object('sucesso', false, 'success', false, 'erro', 'ALOCACAO_NAO_ENCONTRADA');
    END IF;

    IF v_alocacao_prestador IS DISTINCT FROM v_prestador_id THEN
        RETURN jsonb_build_object('sucesso', false, 'success', false, 'erro', 'ALOCACAO_OUTRO_PRESTADOR');
    END IF;

    -- OS real: prioriza rota_paradas.os_id; senão alocacoes_escala.ordem_servico_id.
    -- NUNCA usa alocacao_id como OS.
    v_os_id := COALESCE(v_parada_os_id, v_os_id);

    -- ============================================================
    -- 6. Atualizar a parada (rota_paradas NÃO possui updated_at)
    -- ============================================================
    UPDATE public.rota_paradas SET
        status = p_status,
        recebedor = COALESCE(p_recebedor, recebedor),
        assinatura_url = COALESCE(p_assinatura_url, assinatura_url),
        pod_url = COALESCE(p_pod_url, pod_url),
        ocorrencia = COALESCE(p_ocorrencia, ocorrencia),
        latitude_fim = COALESCE(p_latitude_fim, latitude_fim),
        longitude_fim = COALESCE(p_longitude_fim, longitude_fim),
        volumes_entregues = COALESCE(p_volumes_entregues, volumes_entregues),
        observacoes = COALESCE(p_observacoes, observacoes),
        fotos = CASE
                    WHEN p_fotos IS NOT NULL
                     AND jsonb_typeof(p_fotos) = 'array'
                     AND jsonb_array_length(p_fotos) > 0
                    THEN p_fotos
                    ELSE fotos
                END,
        data_hora = NOW(),
        data_entrega = CASE
                           WHEN p_status IN (
                               'entregue', 'nao_entregue', 'ocorrencia',
                               'reentrega', 'devolucao', 'cancelada'
                           ) THEN NOW()
                           ELSE data_entrega
                       END
    WHERE id = p_parada_id;

    -- ============================================================
    -- 7. Contabilizar paradas da mesma alocacao_id (status terminal)
    -- ============================================================
    SELECT COUNT(*),
           COUNT(*) FILTER (WHERE status IN (
               'entregue', 'nao_entregue', 'ocorrencia',
               'reentrega', 'devolucao', 'cancelada'
           ))
    INTO v_total_paradas, v_paradas_terminal
    FROM public.rota_paradas
    WHERE alocacao_id = v_parada_alocacao_id;

    -- ============================================================
    -- 8. Concluir alocação somente quando TODAS as paradas terminarem
    -- ============================================================
    IF v_total_paradas > 0 AND v_paradas_terminal = v_total_paradas THEN
        UPDATE public.alocacoes_escala SET
            status = 'concluida',
            finalizada = true,
            data_finalizacao = NOW(),
            horario_fim_real = NOW(),
            updated_at = NOW()
        WHERE id = v_parada_alocacao_id
          AND prestador_id = v_prestador_id;
    END IF;

    -- ============================================================
    -- 9. Rota vinculada (rota_id IS NOT NULL) — somente colunas
    --    comprovadas de public.rotas: status e completed_at
    -- ============================================================
    IF v_parada_rota_id IS NOT NULL THEN
        SELECT COUNT(*),
               COUNT(*) FILTER (WHERE status IN (
                   'entregue', 'nao_entregue', 'ocorrencia',
                   'reentrega', 'devolucao', 'cancelada'
               ))
        INTO v_rota_total, v_rota_terminal
        FROM public.rota_paradas
        WHERE rota_id = v_parada_rota_id;

        IF v_rota_total > 0 AND v_rota_terminal = v_rota_total THEN
            UPDATE public.rotas SET
                status = 'concluida',
                completed_at = NOW()
            WHERE id = v_parada_rota_id;
        END IF;
    END IF;

    -- ============================================================
    -- 10. OS real: somente quando existe OS E a alocação concluiu
    -- ============================================================
    IF v_os_id IS NOT NULL
       AND v_total_paradas > 0
       AND v_paradas_terminal = v_total_paradas THEN
        UPDATE public.ordens_servico SET
            status = 'concluida'
        WHERE id = v_os_id
          AND (prestador_id IS NULL OR prestador_id = v_prestador_id);

        INSERT INTO public.os_historico (
            ordem_servico_id, descricao, acao, status_novo, usuario
        ) VALUES (
            v_os_id,
            format('Parada %s finalizada com status %s', p_parada_id, p_status),
            'atualizar_status_parada',
            p_status,
            v_authenticated_uid::text
        );
    END IF;

    -- ============================================================
    -- 11. Retorno: sucesso (legado) + success (App corrigido)
    -- ============================================================
    RETURN jsonb_build_object(
        'sucesso', true,
        'success', true,
        'message', 'Status da parada atualizado com sucesso.',
        'parada_id', p_parada_id,
        'status', p_status,
        'status_anterior', v_status_anterior,
        'alocacao_id', v_parada_alocacao_id,
        'alocacao_concluida', (v_total_paradas > 0 AND v_paradas_terminal = v_total_paradas),
        'os_id', v_os_id
    );
END;
$$;


--
-- Name: FUNCTION "f_atualizar_status_parada"("p_parada_id" "uuid", "p_status" "text", "p_recebedor" "text", "p_assinatura_url" "text", "p_pod_url" "text", "p_fotos" "jsonb", "p_ocorrencia" "text", "p_latitude_fim" numeric, "p_longitude_fim" numeric, "p_volumes_entregues" integer, "p_observacoes" "text"); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."f_atualizar_status_parada"("p_parada_id" "uuid", "p_status" "text", "p_recebedor" "text", "p_assinatura_url" "text", "p_pod_url" "text", "p_fotos" "jsonb", "p_ocorrencia" "text", "p_latitude_fim" numeric, "p_longitude_fim" numeric, "p_volumes_entregues" integer, "p_observacoes" "text") IS 'M111 — Atualiza status de parada individual. Recalcula pendências na rota. Se todas resolvidas, conclui rota + alocação + OS.';


--
-- Name: f_avancar_etapa_app_motorista("uuid", "text", "jsonb", "text", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."f_avancar_etapa_app_motorista"("p_alocacao_id" "uuid", "p_etapa" "text", "p_payload" "jsonb" DEFAULT '{}'::"jsonb", "p_idempotency_key" "text" DEFAULT NULL::"text", "p_auth_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_authenticated_uid UUID;
  v_prestador_id UUID;
  v_alocacao RECORD;
  v_tenant_id UUID;
  v_os_id UUID;
  v_etapa_atual TEXT;
  v_ultima_idempotency TEXT;
  v_allowed BOOLEAN;
  v_app_meta JSONB;
  v_updated_meta JSONB;
  v_status_update TEXT;
  v_event_id UUID;
  v_evento_tipo TEXT;
  v_romaneio_app TEXT;
BEGIN
  v_authenticated_uid := auth.uid();
  IF v_authenticated_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'USUARIO_NAO_AUTENTICADO');
  END IF;

  IF p_auth_user_id IS NOT NULL AND p_auth_user_id <> v_authenticated_uid THEN
    RETURN jsonb_build_object('success', false, 'error', 'AUTH_USER_ID_INVALIDO');
  END IF;

  SELECT id INTO v_prestador_id
  FROM public.prestadores
  WHERE auth_user_id = v_authenticated_uid;

  IF v_prestador_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'PRESTADOR_NAO_ENCONTRADO');
  END IF;

  SELECT ae.*,
    ae.metadata->'app_motorista'->>'etapa_atual' AS etapa_atual,
    ae.metadata->'app_motorista'->>'ultima_idempotency' AS ultima_idempotency
  INTO v_alocacao
  FROM public.alocacoes_escala ae
  WHERE ae.id = p_alocacao_id;

  IF v_alocacao.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'ALOCACAO_NAO_ENCONTRADA');
  END IF;

  IF v_alocacao.prestador_id IS DISTINCT FROM v_prestador_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'ALOCACAO_OUTRO_PRESTADOR');
  END IF;

  v_tenant_id := v_alocacao.tenant_id;
  v_os_id := v_alocacao.ordem_servico_id;

  IF v_alocacao.status IN ('cancelada', 'recusada') THEN
    RETURN jsonb_build_object('success', false, 'error', 'OPERACAO_CANCELADA');
  END IF;

  IF v_alocacao.status = 'concluida' OR (v_alocacao.metadata->'app_motorista'->>'servico_finalizado')::BOOLEAN = true THEN
    RETURN jsonb_build_object('success', false, 'error', 'OPERACAO_FINALIZADA');
  END IF;

  v_etapa_atual := COALESCE(v_alocacao.etapa_atual, '');
  v_ultima_idempotency := COALESCE(v_alocacao.ultima_idempotency, '');

  IF p_idempotency_key IS NOT NULL AND p_idempotency_key <> '' AND p_idempotency_key = v_ultima_idempotency THEN
    RETURN jsonb_build_object(
      'success', true,
      'message', 'Etapa já registrada (idempotente).',
      'etapa', p_etapa,
      'idempotent', true
    );
  END IF;

  v_allowed := false;

  IF v_etapa_atual = '' AND p_etapa = 'viagem_aceita' THEN v_allowed := true; END IF;
  IF v_etapa_atual = 'viagem_aceita' AND p_etapa = 'cheguei_coleta' THEN v_allowed := true; END IF;
  IF v_etapa_atual = 'cheguei_coleta' AND p_etapa = 'carregamento_iniciado' THEN v_allowed := true; END IF;
  IF v_etapa_atual = 'carregamento_iniciado' AND p_etapa = 'carregamento_finalizado' THEN v_allowed := true; END IF;
  IF v_etapa_atual = 'carregamento_finalizado' AND p_etapa IN ('romaneio_informado', 'foto_romaneio', 'km_inicial_informado', 'saiu_em_rota') THEN v_allowed := true; END IF;
  IF v_etapa_atual = 'romaneio_informado' AND p_etapa IN ('foto_romaneio', 'km_inicial_informado') THEN v_allowed := true; END IF;
  IF v_etapa_atual = 'foto_romaneio' AND p_etapa = 'km_inicial_informado' THEN v_allowed := true; END IF;
  IF v_etapa_atual = 'km_inicial_informado' AND p_etapa = 'saiu_em_rota' THEN v_allowed := true; END IF;
  IF v_etapa_atual = 'saiu_em_rota' AND p_etapa = 'chegou_entrega' THEN v_allowed := true; END IF;
  IF v_etapa_atual = 'chegou_entrega' AND p_etapa = 'descarregamento_iniciado' THEN v_allowed := true; END IF;
  IF v_etapa_atual = 'descarregamento_iniciado' AND p_etapa = 'descarga_finalizada' THEN v_allowed := true; END IF;
  IF v_etapa_atual = 'descarga_finalizada' AND p_etapa = 'km_final_informado' THEN v_allowed := true; END IF;
  IF v_etapa_atual = 'km_final_informado' AND p_etapa = 'assinatura_capturada' THEN v_allowed := true; END IF;
  IF v_etapa_atual = 'assinatura_capturada' AND p_etapa = 'pod_registrado' THEN v_allowed := true; END IF;
  IF v_etapa_atual = 'pod_registrado' AND p_etapa = 'servico_finalizado' THEN v_allowed := true; END IF;

  IF NOT v_allowed THEN
    RETURN jsonb_build_object(
      'success', false, 'error', 'TRANSICAO_INVALIDA',
      'message', format('Transição inválida: de "%s" para "%s"', v_etapa_atual, p_etapa),
      'etapa_atual', v_etapa_atual,
      'etapa_solicitada', p_etapa
    );
  END IF;

  IF p_etapa = 'servico_finalizado' THEN
    IF NOT (v_alocacao.metadata->'app_motorista'->>'pod_registrado')::BOOLEAN = true THEN
      RETURN jsonb_build_object(
        'success', false, 'error', 'FINALIZACAO_SEM_POD',
        'message', 'Operação não pode ser finalizada sem POD registrado.'
      );
    END IF;
  END IF;

  IF p_etapa = 'pod_registrado' AND NOT public.f_validar_pod_operacao(p_alocacao_id, v_authenticated_uid, v_prestador_id) THEN
  RETURN jsonb_build_object('success', false, 'error', 'POD_EVIDENCIA_OBRIGATORIA', 'message', 'POD exige evidencia valida (fotos/assinatura/recebedor) para esta operacao.');
END IF;
IF p_etapa = 'servico_finalizado' AND NOT public.f_validar_pod_operacao(p_alocacao_id, v_authenticated_uid, v_prestador_id) THEN
  RETURN jsonb_build_object('success', false, 'error', 'POD_EVIDENCIA_OBRIGATORIA', 'message', 'Finalizacao exige POD valido.');
END IF;
  v_app_meta := COALESCE(v_alocacao.metadata->'app_motorista', '{}'::JSONB);
  v_app_meta := jsonb_set(v_app_meta, '{etapa_atual}', to_jsonb(p_etapa));
  v_app_meta := jsonb_set(v_app_meta, '{ultima_acao}', to_jsonb(p_etapa));
  v_app_meta := jsonb_set(v_app_meta, '{atualizado_por_app}', 'true'::JSONB);

  IF p_idempotency_key IS NOT NULL AND p_idempotency_key <> '' THEN
    v_app_meta := jsonb_set(v_app_meta, '{ultima_idempotency}', to_jsonb(p_idempotency_key));
  END IF;

  IF p_payload IS NOT NULL AND p_payload <> '{}'::JSONB THEN
    v_app_meta := v_app_meta || p_payload;
  END IF;

  v_updated_meta := COALESCE(v_alocacao.metadata, '{}'::JSONB);
  v_updated_meta := jsonb_set(v_updated_meta, '{app_motorista}', v_app_meta);

  v_status_update := NULL;
  IF p_etapa = 'viagem_aceita' THEN v_status_update := 'aceita';
  ELSIF p_etapa = 'cheguei_coleta' THEN v_status_update := 'em_rota';
  ELSIF p_etapa = 'servico_finalizado' THEN v_status_update := 'concluida';
  END IF;

  -- 10.1 A31-C/A31-D — Sincronizar romaneio para ordens_servico.romaneio
  v_romaneio_app := NULLIF(BTRIM(COALESCE(p_payload->>'romaneio', '')), '');
  IF p_etapa = 'romaneio_informado' AND v_os_id IS NOT NULL AND v_romaneio_app IS NOT NULL THEN
    UPDATE public.ordens_servico
    SET romaneio = v_romaneio_app,
        updated_at = NOW()
    WHERE id = v_os_id;
  END IF;

  UPDATE public.alocacoes_escala SET
    metadata = v_updated_meta,
    status = COALESCE(v_status_update, status),
    aceite_prestador = CASE WHEN p_etapa = 'viagem_aceita' THEN true ELSE aceite_prestador END,
    data_aceite = CASE WHEN p_etapa = 'viagem_aceita' THEN NOW() ELSE data_aceite END,
    horario_inicio_real = CASE WHEN p_etapa = 'cheguei_coleta' THEN NOW() ELSE horario_inicio_real END,
    horario_fim_real = CASE WHEN p_etapa = 'servico_finalizado' THEN NOW() ELSE horario_fim_real END,
    finalizada = CASE WHEN p_etapa = 'servico_finalizado' THEN true ELSE finalizada END,
    data_finalizacao = CASE WHEN p_etapa = 'servico_finalizado' THEN NOW() ELSE data_finalizacao END,
    updated_at = NOW()
  WHERE id = p_alocacao_id
    AND prestador_id = v_prestador_id;

  v_evento_tipo := CASE
    WHEN p_etapa = 'viagem_aceita' THEN 'operation_accepted'
    WHEN p_etapa = 'cheguei_coleta' THEN 'arrived_pickup'
    WHEN p_etapa = 'carregamento_iniciado' THEN 'loading_started'
    WHEN p_etapa = 'carregamento_finalizado' THEN 'loading_finished'
    WHEN p_etapa = 'romaneio_informado' THEN 'romaneio_informado'
    WHEN p_etapa = 'foto_romaneio' THEN 'romaneio_foto'
    WHEN p_etapa = 'km_inicial_informado' THEN 'km_registered'
    WHEN p_etapa = 'saiu_em_rota' THEN 'route_started'
    WHEN p_etapa = 'chegou_entrega' THEN 'arrived_delivery'
    WHEN p_etapa = 'descarregamento_iniciado' THEN 'unloading_started'
    WHEN p_etapa = 'descarga_finalizada' THEN 'unloading_finished'
    WHEN p_etapa = 'km_final_informado' THEN 'km_final'
    WHEN p_etapa = 'assinatura_capturada' THEN 'signature_captured'
    WHEN p_etapa = 'pod_registrado' THEN 'pod_sent'
    WHEN p_etapa = 'servico_finalizado' THEN 'operation_finished'
    ELSE p_etapa
  END;

  v_event_id := gen_random_uuid();
  INSERT INTO public.eventos_oficiais (
    id, tenant_id, event_type, entity_type, entity_id, entity_number,
    status, source, created_by, visibility, payload, metadata,
    created_at, processed_at, version, retry_count
  ) VALUES (
    v_event_id,
    v_tenant_id,
    v_evento_tipo,
    'alocacao',
    p_alocacao_id,
    v_os_id::TEXT,
    COALESCE(v_status_update, 'em_andamento'),
    'app_motorista',
    v_prestador_id,
    'internal',
    jsonb_build_object(
      'etapa', p_etapa,
      'etapa_anterior', v_etapa_atual,
      'payload', p_payload,
      'idempotency_key', p_idempotency_key
    ),
    jsonb_build_object(
      'app_motorista', v_app_meta,
      'prestador_id', v_prestador_id
    ),
    NOW(),
    NULL,
    '1.0',
    0
  );

  INSERT INTO public.operation_timeline_events (
    id, operation_id, driver_id, type, title, metadata, event_time, created_at
  ) VALUES (
    v_event_id,
    p_alocacao_id::TEXT,
    v_prestador_id::TEXT,
    v_evento_tipo,
    p_etapa,
    jsonb_build_object('etapa', p_etapa, 'payload', p_payload),
    NOW(),
    NOW()
  );

  RETURN jsonb_build_object(
    'success', true,
    'message', 'Etapa avançada com sucesso.',
    'etapa', p_etapa,
    'etapa_anterior', v_etapa_atual,
    'status', COALESCE(v_status_update, v_alocacao.status),
    'event_id', v_event_id,
    'idempotent', false,
    'romaneio_sync', CASE WHEN p_etapa = 'romaneio_informado' AND v_os_id IS NOT NULL AND v_romaneio_app IS NOT NULL THEN true ELSE false END
  );
END;
$$;


--
-- Name: FUNCTION "f_avancar_etapa_app_motorista"("p_alocacao_id" "uuid", "p_etapa" "text", "p_payload" "jsonb", "p_idempotency_key" "text", "p_auth_user_id" "uuid"); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."f_avancar_etapa_app_motorista"("p_alocacao_id" "uuid", "p_etapa" "text", "p_payload" "jsonb", "p_idempotency_key" "text", "p_auth_user_id" "uuid") IS 'M133-D.4 + A31-D — Máquina de estados do App Motorista. VOLATILE. Romaneio sincronizado para ordens_servico.romaneio quando há OS vinculada.';


--
-- Name: f_bridge_prestador_para_recrutamento(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."f_bridge_prestador_para_recrutamento"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_rp_id UUID;
  v_candidato_id UUID;
  v_nome TEXT;
  v_telefone TEXT;
  v_email TEXT;
  v_cidade TEXT;
  v_uf TEXT;
  v_tipo_veiculo TEXT;
  v_placa TEXT;
  v_cpf TEXT;
  v_stage TEXT;
  v_now TEXT;
  v_tags JSONB;
  v_historico JSONB;
BEGIN
  IF NEW.origem != 'app_prestador' AND NEW.origem_cadastro != 'app_motorista' THEN
    RETURN NEW;
  END IF;

  v_now := to_char(NOW(), 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"');
  v_nome := COALESCE(NEW.nome_completo, 'Sem nome');
  v_telefone := COALESCE(NEW.telefone, NEW.whatsapp, '');
  v_email := COALESCE(NEW.email, '');
  v_cidade := COALESCE(
    NEW.endereco->>'cidade',
    NEW.metadata->'endereco'->>'cidade',
    ''
  );
  v_uf := COALESCE(
    NEW.endereco->>'uf',
    NEW.endereco->>'estado',
    NEW.metadata->'endereco'->>'uf',
    ''
  );
  v_cpf := COALESCE(NEW.cpf_cnpj, '');

  v_tipo_veiculo := COALESCE(
    NEW.metadata->'veiculo'->>'tipo',
    NEW.metadata->>'tipo_veiculo',
    ''
  );
  v_placa := COALESCE(NEW.metadata->'veiculo'->>'placa', '');

  -- Etapa canônica do funil de 17 etapas enviada pelo App.
  v_stage := btrim(COALESCE(NEW.metadata->>'etapa_pipeline', 'cadastro_concluido'));
  IF v_stage NOT IN (
    'novo_candidato', 'cadastro_iniciado', 'cadastro_concluido',
    'em_triagem', 'em_analise_perfil', 'aguardando_documentacao',
    'em_verificacao_documental', 'em_avaliacao_situacional',
    'em_entrevista', 'em_homologacao', 'aprovado', 'reprovado',
    'cadastro_incompleto', 'banco_de_talentos', 'homologado_disponivel',
    'homologado_indisponivel', 'processo_encerrado'
  ) THEN
    v_stage := 'cadastro_concluido';
  END IF;

  -- Idempotência do recrutamento_prestadores por CPF.
  IF v_cpf != '' THEN
    SELECT id INTO v_rp_id
    FROM public.recrutamento_prestadores
    WHERE cpf_cnpj = v_cpf
    LIMIT 1;
  END IF;

  IF v_rp_id IS NULL THEN
    INSERT INTO public.recrutamento_prestadores (
      nome, cpf_cnpj, contatos, endereco, tipo_veiculo, placa_veiculo,
      status, origem_cadastro, data_cadastro, ultima_atividade,
      created_at, updated_at
    ) VALUES (
      v_nome, v_cpf,
      jsonb_build_array(
        jsonb_build_object('tipo', 'telefone', 'valor', v_telefone, 'principal', true),
        jsonb_build_object('tipo', 'email', 'valor', v_email, 'principal', false)
      ),
      jsonb_build_object('cidade', v_cidade, 'estado', v_uf),
      v_tipo_veiculo, v_placa,
      'novo', 'app_motorista', v_now, v_now,
      NOW(), NOW()
    )
    RETURNING id INTO v_rp_id;
  END IF;

  v_tags := jsonb_build_array(
    'app_motorista',
    'bridge_automatico',
    'etapa:' || v_stage
  );

  v_historico := jsonb_build_array(
    jsonb_build_object(
      'tipo', 'mudou_etapa',
      'descricao', 'Cadastro concluído no App Prestador → Cadastro Concluído (Etapa 3 de 17)',
      'data', v_now,
      'stageNovo', v_stage
    )
  );

  SELECT id INTO v_candidato_id
  FROM public.recrutamento_candidatos
  WHERE prestador_id = v_rp_id
  ORDER BY created_at
  LIMIT 1;

  IF v_candidato_id IS NOT NULL THEN
    UPDATE public.recrutamento_candidatos
       SET nome = COALESCE(NULLIF(v_nome, ''), nome),
           telefone = COALESCE(NULLIF(v_telefone, ''), telefone),
           email = COALESCE(NULLIF(v_email, ''), email),
           cidade = COALESCE(NULLIF(v_cidade, ''), cidade),
           uf = COALESCE(NULLIF(v_uf, ''), uf),
           veiculo = COALESCE(NULLIF(v_tipo_veiculo, ''), veiculo),
           placa = COALESCE(NULLIF(v_placa, ''), placa),
           stage = v_stage,
           tags = COALESCE(tags, '[]'::jsonb) || v_tags,
           observacoes_ia = '[REC-06.1] Candidato criado/atualizado via bridge prestador→recrutamento. Prestador ID: ' || NEW.id || '. Auth User ID: ' || COALESCE(NEW.auth_user_id::text, 'N/A'),
           data_atualizacao = v_now,
           updated_at = NOW(),
           historico = COALESCE(historico, '[]'::jsonb) || v_historico
     WHERE id = v_candidato_id;

    RETURN NEW;
  END IF;

  INSERT INTO public.recrutamento_candidatos (
    nome, telefone, email, cidade, uf, veiculo, placa,
    stage, status_documental, prioridade, validade_cnh, tags,
    observacoes_ia, data_entrada, data_atualizacao, prestador_id, historico
  ) VALUES (
    v_nome, v_telefone, v_email, v_cidade, v_uf, v_tipo_veiculo, v_placa,
    v_stage, 'pendente', 'media', 'valida', v_tags,
    '[REC-06.1] Candidato criado via bridge prestador→recrutamento. Prestador ID: ' || NEW.id || '. Auth User ID: ' || COALESCE(NEW.auth_user_id::text, 'N/A'),
    v_now, v_now, v_rp_id, v_historico
  )
  RETURNING id INTO v_candidato_id;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION "f_bridge_prestador_para_recrutamento"(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."f_bridge_prestador_para_recrutamento"() IS 'REC-06.1 Bridge canônico: prestadores → recrutamento_prestadores → recrutamento_candidatos. Respeita metadata.etapa_pipeline do App (17 etapas).';


--
-- Name: f_buscar_operacoes_motorista("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."f_buscar_operacoes_motorista"("p_auth_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_authenticated_uid UUID;
  v_prestador_id UUID;
  v_operacoes JSONB;
BEGIN
  v_authenticated_uid := auth.uid();
  IF v_authenticated_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'USUARIO_NAO_AUTENTICADO');
  END IF;
  IF p_auth_user_id IS NOT NULL AND p_auth_user_id <> v_authenticated_uid THEN
    RETURN jsonb_build_object('success', false, 'error', 'AUTH_USER_ID_INVALIDO');
  END IF;
  SELECT id INTO v_prestador_id
  FROM public.prestadores
  WHERE auth_user_id = v_authenticated_uid;
  IF v_prestador_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'PRESTADOR_NAO_ENCONTRADO');
  END IF;
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'id', ae.id,
      'prestador_id', ae.prestador_id,
      'status', ae.status,
      'rota', ae.rota,
      'origem', ae.origem,
      'destino', ae.destino,
      'data_escala', ae.data_escala,
      'turno', ae.turno,
      'tipo_veiculo', ae.tipo_veiculo,
      'placa', ae.placa,
      'quantidade_paradas', ae.quantidade_paradas,
      'valor_repasse', ae.valor_repasse,
      'km_previstos', ae.km_previstos,
      'valor_km', ae.valor_km,
      'observacoes', ae.observacoes,
      'operation_mode', ae.operation_mode,
      'coleta_reversa', ae.coleta_reversa,
      'tenant_id', ae.tenant_id,
      'metadata', ae.metadata,
      'endereco_origem', ae.endereco_origem,
      'endereco_destino', ae.endereco_destino,
      'horario_saida', ae.horario_saida,
      'horario_retorno_previsto', ae.horario_retorno_previsto,
      'aceite_prestador', ae.aceite_prestador,
      'data_aceite', ae.data_aceite,
      'horario_inicio_real', ae.horario_inicio_real,
      'horario_fim_real', ae.horario_fim_real,
      'finalizada', ae.finalizada,
      'data_finalizacao', ae.data_finalizacao,
      'created_at', ae.created_at,
      'updated_at', ae.updated_at,
      'os_id', ae.ordem_servico_id,
      'os_numero', os.numero,
      'romaneio', ae.metadata -> 'app_motorista' ->> 'romaneio',
      'cliente_id', ae.cliente_id,
      'cliente_nome', COALESCE(c.nome_fantasia, c.razao_social),
      'paradas', COALESCE(
        (
          SELECT jsonb_agg(
            jsonb_build_object(
              'parada_id', rp.id,
              'sequencia', rp.sequencia,
              'destinatario', COALESCE(rp.destinatario, rp.cliente_nome, ''),
              'endereco', COALESCE(rp.endereco, ''),
              'logradouro', rp.logradouro,
              'numero', rp.numero,
              'complemento', rp.complemento,
              'bairro', rp.bairro,
              'cidade', rp.cidade,
              'uf', rp.uf,
              'cep', rp.cep,
              'referencia', rp.referencia,
              'latitude', rp.latitude,
              'longitude', rp.longitude,
              'portaria', rp.portaria,
              'doca', rp.doca,
              'procedimento_entrada', rp.procedimento_entrada,
              'procedimento_saida', rp.procedimento_saida,
              'contato_nome', rp.contato_nome,
              'contato_telefone', rp.contato_telefone,
              'pedido', rp.pedido,
              'nota_fiscal', rp.nota_fiscal,
              'peso', rp.peso,
              'volumes', rp.volumes,
              'prioridade', rp.prioridade,
              'janela_inicio', rp.janela_entrega,
              'instrucoes', rp.instrucoes,
              'status', rp.status,
              'data_prevista', rp.data_prevista
            )
            ORDER BY rp.sequencia
          )
          FROM public.rota_paradas rp
          WHERE rp.alocacao_id = ae.id
        ),
        '[]'::JSONB
      )
    )
    ORDER BY ae.data_escala DESC NULLS LAST, ae.created_at DESC
  ), '[]'::JSONB) INTO v_operacoes
  FROM public.alocacoes_escala ae
  LEFT JOIN public.ordens_servico os ON os.id = ae.ordem_servico_id
  LEFT JOIN public.clientes c ON c.id = ae.cliente_id
  WHERE ae.prestador_id = v_prestador_id
    AND (ae.status IS DISTINCT FROM 'cancelada')
    AND (ae.status IS DISTINCT FROM 'recusada');
  RETURN jsonb_build_object(
    'success', true,
    'operacoes', v_operacoes,
    'total', jsonb_array_length(v_operacoes)
  );
END;
$$;


--
-- Name: FUNCTION "f_buscar_operacoes_motorista"("p_auth_user_id" "uuid"); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."f_buscar_operacoes_motorista"("p_auth_user_id" "uuid") IS 'APP-E2E-04 — Busca operações do motorista autenticado. Base M133-D.2 + campos de identificação: os_id, os_numero (número interno Conexão), romaneio (metadata.app_motorista), cliente_id, cliente_nome. valor_repasse preservado (valor do prestador).';


--
-- Name: f_buscar_oportunidades_para_prestador("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."f_buscar_oportunidades_para_prestador"("p_prestador_uuid" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_prestador public.prestadores%ROWTYPE;
  v_veiculos_tipos text[];
  v_max_capacidade numeric;
  v_oportunidades jsonb;
BEGIN
  -- Valida o prestador requisitante (cadastro real).
  SELECT * INTO v_prestador
  FROM public.prestadores
  WHERE id = p_prestador_uuid AND status = 'ativo';

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'PRESTADOR_NAO_ENCONTRADO',
      'oportunidades', '[]'::jsonb
    );
  END IF;

  -- Veículos ativos do prestador (compatibilidade de tipo e capacidade).
  SELECT
    COALESCE(
      array_agg(DISTINCT v.tipo_veiculo)
        FILTER (WHERE v.tipo_veiculo IS NOT NULL AND v.tipo_veiculo <> ''),
      '{}'::text[]
    ),
    COALESCE(MAX(v.capacidade_kg), 0)
  INTO v_veiculos_tipos, v_max_capacidade
  FROM public.veiculos v
  WHERE v.prestador_vinculado = p_prestador_uuid
    AND v.status = 'Ativo';

  -- Oportunidades abertas compatíveis + dados exibíveis da OS.
  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'id', ro.id,
        'os_id', ro.os_id,
        'status', ro.status,
        'valor_prestador', ro.valor_prestador,
        'veiculo_necessario', ro.veiculo_necessario,
        'tipo_veiculo', ro.tipo_veiculo,
        'regiao', ro.regiao,
        'requisitos', ro.requisitos,
        'prazo_expiracao', ro.prazo_expiracao,
        'aceite_em', ro.aceite_em,
        'created_at', ro.created_at,
        -- Dados da OS (somente exibíveis — NUNCA valor_cliente/margem/custos).
        'numero', os.numero,
        'tipo_operacao', os.tipo_operacao,
        'tipo_reversa', os.tipo_reversa,
        'data_programada', os.data_programada,
        'peso', os.peso,
        'volumes', os.volumes,
        'cubagem', os.cubagem,
        'carga_refrigerada', os.carga_refrigerada,
        'origem', os.origem,
        'destino', os.destino,
        'origem_endereco',
          CASE WHEN coleta.logradouro IS NOT NULL THEN
            CONCAT_WS(', ',
              NULLIF(coleta.logradouro, ''),
              NULLIF(coleta.numero, ''),
              NULLIF(coleta.bairro, ''),
              NULLIF(coleta.cidade, ''),
              NULLIF(coleta.uf, '')
            )
          ELSE NULL END,
        'cidade_coleta', coleta.cidade,
        'latitude_coleta', coleta.latitude,
        'longitude_coleta', coleta.longitude,
        'destino_endereco',
          CASE WHEN entrega.logradouro IS NOT NULL THEN
            CONCAT_WS(', ',
              NULLIF(entrega.logradouro, ''),
              NULLIF(entrega.numero, ''),
              NULLIF(entrega.bairro, ''),
              NULLIF(entrega.cidade, ''),
              NULLIF(entrega.uf, '')
            )
          ELSE NULL END,
        'cidade_destino', entrega.cidade,
        'observacoes', os.observacoes_gerais,
        'distancia_km', os.distancia_km
      )
      ORDER BY ro.created_at DESC
    ),
    '[]'::jsonb
  ) INTO v_oportunidades
  FROM public.rede_oportunidades ro
  JOIN public.ordens_servico os ON os.id = ro.os_id
  LEFT JOIN LATERAL (
    SELECT
      e->>'logradouro' AS logradouro,
      e->>'numero'    AS numero,
      e->>'bairro'    AS bairro,
      e->>'cidade'    AS cidade,
      e->>'uf'        AS uf,
      NULLIF(e->>'latitude', '')::numeric  AS latitude,
      NULLIF(e->>'longitude', '')::numeric AS longitude
    FROM jsonb_array_elements(COALESCE(os.enderecos, '[]'::jsonb)) AS e
    WHERE e->>'tipo' = 'coleta'
    ORDER BY COALESCE(NULLIF(e->>'sequencia', ''), '0')
    LIMIT 1
  ) coleta ON true
  LEFT JOIN LATERAL (
    SELECT
      e->>'logradouro' AS logradouro,
      e->>'numero'     AS numero,
      e->>'bairro'     AS bairro,
      e->>'cidade'     AS cidade,
      e->>'uf'         AS uf
    FROM jsonb_array_elements(COALESCE(os.enderecos, '[]'::jsonb)) AS e
    WHERE e->>'tipo' = 'entrega'
    ORDER BY COALESCE(NULLIF(e->>'sequencia', ''), '0')
    LIMIT 1
  ) entrega ON true
  WHERE ro.status IN ('publicada', 'visualizada', 'interessada')
    AND ro.prestador_aceite_id IS NULL
    AND (ro.prazo_expiracao IS NULL OR ro.prazo_expiracao >= now())
    -- Compatibilidade de região (quando a oportunidade define região).
    -- "Todas as capitais" no cadastro é tratado como curinga. Região do
    -- prestador ausente também não restringe (cadastro incompleto).
    AND (
      ro.regiao IS NULL OR ro.regiao = ''
      OR v_prestador.regiao_principal IS NULL
      OR v_prestador.regiao_principal ILIKE '%todas as capitais%'
      OR v_prestador.regiao_principal ILIKE '%' || ro.regiao || '%'
      OR EXISTS (
        SELECT 1 FROM unnest(v_prestador.regioes_secundarias) rs
        WHERE rs ILIKE '%' || ro.regiao || '%'
      )
    )
    -- Compatibilidade de veículo (tipo exigido pertence aos veículos do
    -- prestador). Taxonomia única compartilhada (TIPOS_VEICULO no TMS);
    -- comparação case-insensitive (dados reais têm "VUC"/"vuc"/"fiorino").
    AND (
      COALESCE((ro.veiculo_necessario->>'tipo'), '') = ''
      OR EXISTS (
        SELECT 1 FROM unnest(v_veiculos_tipos) vt
        WHERE LOWER(vt) = LOWER((ro.veiculo_necessario->>'tipo'))
      )
    )
    -- Capacidade suportada.
    AND (
      COALESCE((ro.veiculo_necessario->>'capacidade_kg')::numeric, 0) <= 0
      OR v_max_capacidade >= (ro.veiculo_necessario->>'capacidade_kg')::numeric
    )
    -- Carga refrigerada.
    AND (
      COALESCE((ro.veiculo_necessario->>'termica'), '') <> 'refrigerado'
      OR v_prestador.aceita_refrigerada = true
    );

  RETURN jsonb_build_object(
    'success', true,
    'oportunidades', v_oportunidades,
    'total', jsonb_array_length(v_oportunidades)
  );
END;
$$;


--
-- Name: f_buscar_prestadores_compativeis("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."f_buscar_prestadores_compativeis"("p_oportunidade_id" "uuid") RETURNS TABLE("prestador_id" "uuid", "nome_completo" "text", "telefone" "text", "whatsapp" "text", "score_interno" numeric, "tipo_veiculo" "text", "placa" "text", "capacidade_kg" numeric, "regiao_principal" "text", "aceita_refrigerada" boolean, "status" "text", "score_match" numeric)
    LANGUAGE "plpgsql" STABLE
    AS $$
DECLARE
  v_os_id UUID;
  v_veiculo JSONB;
  v_regiao TEXT;
  v_requisitos JSONB;
  v_regiao_like TEXT;
  v_regiao_cidade TEXT;
  v_regiao_estado TEXT;
BEGIN
  SELECT r.os_id, r.veiculo_necessario, r.regiao, r.requisitos
  INTO v_os_id, v_veiculo, v_regiao, v_requisitos
  FROM rede_oportunidades r
  WHERE r.id = p_oportunidade_id AND r.status = 'publicada';

  IF NOT FOUND THEN RETURN; END IF;

  -- Preparar variações de região para matching flexível
  v_regiao_like := '%' || COALESCE(v_regiao, '') || '%';
  v_regiao_cidade := split_part(COALESCE(v_regiao, ''), '/', 1);
  v_regiao_estado := split_part(COALESCE(v_regiao, ''), '/', 2);

  RETURN QUERY
  WITH prestadores_filtrados AS (
    SELECT
      p.id,
      p.nome_completo,
      p.telefone,
      p.whatsapp,
      COALESCE(p.score_interno, 0) as score_interno,
      v.tipo_veiculo,
      v.placa,
      v.capacidade_kg,
      p.regiao_principal,
      p.aceita_refrigerada,
      p.status
    FROM prestadores p
    LEFT JOIN LATERAL (
      SELECT v2.tipo_veiculo, v2.placa, v2.capacidade_kg
      FROM veiculos v2
      WHERE v2.prestador_vinculado::text = p.id::text AND v2.status = 'Ativo'
      LIMIT 1
    ) v ON true
    WHERE
      p.status = 'ativo'
      AND (
        v_regiao IS NULL OR v_regiao = '' OR
        p.regiao_principal ILIKE v_regiao_like OR
        EXISTS (SELECT 1 FROM unnest(p.regioes_secundarias) rs WHERE rs ILIKE v_regiao_like) OR
        (v_regiao_cidade <> '' AND (p.regiao_principal ILIKE '%' || v_regiao_cidade || '%' OR EXISTS (SELECT 1 FROM unnest(p.regioes_secundarias) rs WHERE rs ILIKE '%' || v_regiao_cidade || '%'))) OR
        (v_regiao_estado <> '' AND (p.regiao_principal ILIKE '%' || v_regiao_estado || '%' OR EXISTS (SELECT 1 FROM unnest(p.regioes_secundarias) rs WHERE rs ILIKE '%' || v_regiao_estado || '%')))
      )
  )
  SELECT
    pf.id, pf.nome_completo, pf.telefone, pf.whatsapp, pf.score_interno,
    pf.tipo_veiculo, pf.placa, pf.capacidade_kg, pf.regiao_principal,
    pf.aceita_refrigerada, pf.status,
    (
      CASE WHEN pf.tipo_veiculo IS NOT NULL AND (v_veiculo->>'tipo' IS NULL OR pf.tipo_veiculo ILIKE '%' || COALESCE(v_veiculo->>'tipo', '') || '%') THEN 35 ELSE 0 END +
      CASE WHEN pf.regiao_principal IS NOT NULL AND (v_regiao IS NULL OR v_regiao = '' OR pf.regiao_principal ILIKE v_regiao_like) THEN 25
           WHEN v_regiao IS NOT NULL AND v_regiao <> '' THEN 15 ELSE 0 END +
      CASE WHEN (v_veiculo->>'termica' IS NULL OR v_veiculo->>'termica' = 'seco') THEN 10 WHEN pf.aceita_refrigerada THEN 10 ELSE 0 END +
      CASE WHEN COALESCE(pf.score_interno, 0) >= 0.8 THEN 10 WHEN COALESCE(pf.score_interno, 0) >= 0.5 THEN 5 ELSE 0 END + 10 +
      CASE WHEN pf.tipo_veiculo IS NOT NULL THEN 10 ELSE 0 END
    )::NUMERIC AS score_match
  FROM prestadores_filtrados pf
  WHERE (v_veiculo IS NULL OR v_veiculo = '{}'::jsonb OR pf.tipo_veiculo IS NOT NULL)
  ORDER BY score_match DESC;
END;
$$;


--
-- Name: f_calcular_financeiro_operacao("uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."f_calcular_financeiro_operacao"("p_alocacao_id" "uuid", "p_modo" "text" DEFAULT 'completo'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_rec RECORD;
  v_valor_cliente NUMERIC := 0;
  v_valor_prestador NUMERIC := 0;
  v_pedagio NUMERIC := 0;
  v_ajudante NUMERIC := 0;
  v_adicional NUMERIC := 0;
  v_desconto NUMERIC := 0;
  v_reversa_cliente NUMERIC := 0;
  v_reversa_prestador NUMERIC := 0;
  v_base_prestador NUMERIC := 0;
  v_diaria NUMERIC := 0;
  v_km_adicional NUMERIC := 0;
  v_espera NUMERIC := 0;
  v_segunda_saida NUMERIC := 0;
  v_terceira_saida NUMERIC := 0;
  v_bonificacao NUMERIC := 0;
  v_total_cliente NUMERIC := 0;
  v_total_prestador NUMERIC := 0;
  v_margem NUMERIC := 0;
BEGIN
  SELECT * INTO v_rec FROM public.alocacoes_escala WHERE id = p_alocacao_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('sucesso', false, 'erro', 'Alocação não encontrada');
  END IF;

  v_valor_cliente := COALESCE(v_rec.valor_frete, 0);
  v_valor_prestador := COALESCE(v_rec.valor_repasse, 0);
  v_pedagio := COALESCE(v_rec.valor_pedagio, 0);
  v_ajudante := COALESCE(v_rec.valor_ajudante, 0);
  v_adicional := COALESCE(v_rec.valor_adicional, 0);
  v_desconto := COALESCE(v_rec.valor_desconto, 0);
  v_reversa_cliente := COALESCE(v_rec.reversa_valor_cliente, 0);
  v_reversa_prestador := COALESCE(v_rec.reversa_valor_prestador, 0);

  -- Calcular adicionais de diária, km extra, etc
  v_diaria := COALESCE(v_rec.diarias_adicionais, 0) * COALESCE(v_rec.valor_diaria, 0);
  IF v_rec.km_realizados > v_rec.km_previstos AND v_rec.km_previstos > 0 THEN
    v_km_adicional := (v_rec.km_realizados - v_rec.km_previstos) * COALESCE(v_rec.valor_km, 0);
  END IF;
  IF v_rec.segunda_saida THEN v_segunda_saida := COALESCE(v_rec.valor_segunda_saida, 0); END IF;
  IF v_rec.terceira_saida THEN v_terceira_saida := COALESCE(v_rec.valor_terceira_saida, 0); END IF;

  v_base_prestador := v_valor_prestador + v_pedagio + v_ajudante + v_adicional +
    v_diaria + v_km_adicional + v_espera + v_segunda_saida + v_terceira_saida +
    v_bonificacao + v_reversa_prestador;
  v_total_prestador := v_base_prestador - v_desconto;
  v_total_cliente := v_valor_cliente + v_reversa_cliente;

  IF v_total_cliente > 0 THEN
    v_margem := ROUND((v_total_cliente - v_total_prestador) / v_total_cliente * 100, 2);
  END IF;

  RETURN jsonb_build_object(
    'sucesso', true,
    'alocacao_id', p_alocacao_id,
    'valor_cliente', v_total_cliente,
    'valor_prestador', v_total_prestador,
    'valor_base_prestador', v_valor_prestador,
    'pedagio', v_pedagio,
    'ajudante', v_ajudante,
    'adicional', v_adicional,
    'desconto', v_desconto,
    'diaria', v_diaria,
    'km_adicional', v_km_adicional,
    'espera', v_espera,
    'segunda_saida', v_segunda_saida,
    'terceira_saida', v_terceira_saida,
    'bonificacao', v_bonificacao,
    'reversa_cliente', v_reversa_cliente,
    'reversa_prestador', v_reversa_prestador,
    'margem_percentual', v_margem,
    'km_previstos', v_rec.km_previstos,
    'km_realizados', v_rec.km_realizados
  );
END;
$$;


--
-- Name: FUNCTION "f_calcular_financeiro_operacao"("p_alocacao_id" "uuid", "p_modo" "text"); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."f_calcular_financeiro_operacao"("p_alocacao_id" "uuid", "p_modo" "text") IS 'M111 — Calcula financeiro completo de uma operação incluindo reversa, diárias, km adicional, saídas.';


--
-- Name: f_cancelar_fatura("uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."f_cancelar_fatura"("p_fatura_id" "uuid", "p_motivo" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_fatura public.faturas%ROWTYPE;
  v_perfil_ok boolean;
  v_tenant_ok boolean;
  v_ar_status text;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'USUARIO_NAO_AUTENTICADO');
  END IF;

  -- Perfil autorizado (financeiro/admin) — mesma autoridade das demais RPCs de fatura
  SELECT EXISTS (
    SELECT 1 FROM public.tenant_usuarios tu
     WHERE tu.user_id = auth.uid() AND tu.status = 'ativo'
       AND tu.papel IN ('super_admin','admin_tenant','financeiro')
  ) INTO v_perfil_ok;
  IF NOT v_perfil_ok THEN
    RETURN jsonb_build_object('success', false, 'error', 'SEM_PERMISSAO_PERFIL');
  END IF;

  SELECT * INTO v_fatura FROM public.faturas WHERE id = p_fatura_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'FATURA_NAO_ENCONTRADA');
  END IF;

  -- Isolamento por tenant
  SELECT EXISTS (
    SELECT 1 FROM public.tenant_usuarios tu
     WHERE tu.user_id = auth.uid() AND tu.status = 'ativo'
       AND tu.tenant_id = v_fatura.tenant_id
  ) INTO v_tenant_ok;
  IF NOT v_tenant_ok THEN
    RETURN jsonb_build_object('success', false, 'error', 'SEM_PERMISSAO_TENANT');
  END IF;

  IF v_fatura.status = 'cancelada' THEN
    RETURN jsonb_build_object('success', false, 'error', 'FATURA_JA_CANCELADA');
  END IF;

  -- Não cancelar fatura cujo AR já possui efeito financeiro (pago/parcial)
  IF v_fatura.conta_receber_id IS NOT NULL THEN
    SELECT status INTO v_ar_status FROM public.financeiro_receber WHERE id = v_fatura.conta_receber_id;
    IF v_ar_status IN ('pago','parcial','recebido') THEN
      RETURN jsonb_build_object('success', false, 'error', 'FATURA_AR_COM_EFEITO_FINANCEIRO', 'ar_status', v_ar_status);
    END IF;
  END IF;

  -- (1) Cancela ITENS antes de mudar o status da fatura (o guard autoriza esta transição)
  UPDATE public.fatura_itens
     SET status = 'cancelado', atualizado_em = now()
   WHERE fatura_id = p_fatura_id AND status = 'ativo';

  -- (2) Cancela a Conta a Receber vinculada (se existir e não paga)
  IF v_fatura.conta_receber_id IS NOT NULL THEN
    UPDATE public.financeiro_receber
       SET status = 'cancelado',
           observacoes = COALESCE(observacoes, '') || ' | Cancelada pela Fatura ' || COALESCE(v_fatura.numero, '')
     WHERE id = v_fatura.conta_receber_id AND status NOT IN ('pago', 'recebido');
  END IF;

  -- (3) Cancela a fatura
  UPDATE public.faturas
     SET status = 'cancelada',
         cancelado_em = now(),
         cancelado_por = auth.uid(),
         motivo_cancelamento = p_motivo,
         atualizado_em = now()
   WHERE id = p_fatura_id;

  RETURN jsonb_build_object(
    'success', true,
    'fatura_id', p_fatura_id,
    'status', 'cancelada',
    'servicos_liberados', true
  );
END;
$$;


--
-- Name: f_cancelar_pagamento_prestador("uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."f_cancelar_pagamento_prestador"("p_pagamento_id" "uuid", "p_motivo" "text" DEFAULT NULL::"text") RETURNS TABLE("sucesso" boolean, "mensagem" "text", "pagamento_id" "uuid", "titulo_id" "uuid", "status_pagamento" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_pag      RECORD;
    v_tenant   uuid;
    v_titulo   uuid;
    v_nbaixas  integer;
    v_obs      text;
BEGIN
    IF auth.uid() IS NULL THEN
        RETURN QUERY SELECT false, 'USUARIO_NAO_AUTENTICADO', p_pagamento_id, NULL::uuid, NULL::text;
        RETURN;
    END IF;

    SELECT tu.tenant_id INTO v_tenant
      FROM public.tenant_usuarios tu
     WHERE tu.user_id = auth.uid() AND tu.status = 'ativo'
     LIMIT 1;

    IF v_tenant IS NULL OR NOT EXISTS (
        SELECT 1 FROM public.tenant_usuarios tu
         WHERE tu.user_id = auth.uid() AND tu.status = 'ativo'
           AND tu.papel IN ('super_admin','admin_tenant','financeiro')) THEN
        RETURN QUERY SELECT false, 'NAO_AUTORIZADO', p_pagamento_id, NULL::uuid, NULL::text;
        RETURN;
    END IF;

    SELECT p.* INTO v_pag
      FROM public.pagamentos_prestadores p
     WHERE p.id = p_pagamento_id
       FOR UPDATE;

    IF NOT FOUND THEN
        RETURN QUERY SELECT false, 'PAGAMENTO_NAO_ENCONTRADO', p_pagamento_id, NULL::uuid, NULL::text;
        RETURN;
    END IF;

    IF v_pag.os_id IS NOT NULL
       AND public.f_pp_tenant_id(v_pag.os_id) IS DISTINCT FROM v_tenant THEN
        RETURN QUERY SELECT false, 'NAO_AUTORIZADO_TENANT', v_pag.id, NULL::uuid, v_pag.status_pagamento;
        RETURN;
    END IF;

    -- Idempotencia
    IF v_pag.status_pagamento = 'cancelado' OR v_pag.status = 'cancelado' THEN
        RETURN QUERY SELECT true, 'JA_CANCELADO', v_pag.id, NULL::uuid, v_pag.status_pagamento;
        RETURN;
    END IF;

    IF v_pag.status_pagamento = 'pago' OR v_pag.status = 'pago' THEN
        RETURN QUERY SELECT false, 'PAGAMENTO_JA_PAGO', v_pag.id, NULL::uuid, v_pag.status_pagamento;
        RETURN;
    END IF;

    IF v_pag.status_pagamento IS NULL
       OR v_pag.status_pagamento NOT IN ('pendente','nao_vencido','em_lote') THEN
        RETURN QUERY SELECT false, 'ESTADO_NAO_PERMITE_CANCELAR', v_pag.id, NULL::uuid, v_pag.status_pagamento;
        RETURN;
    END IF;

    -- Resolve titulo(s) FP pela OS e pre-condicao DURA: nenhuma baixa ativa
    IF v_pag.os_id IS NOT NULL THEN
        SELECT count(*) INTO v_nbaixas
          FROM public.financeiro_pagar fp
          JOIN public.financeiro_baixas b
            ON b.titulo_tabela = 'financeiro_pagar' AND b.titulo_id = fp.id
         WHERE fp.os_id = v_pag.os_id::text
           AND NOT COALESCE(b.estornada, false);

        IF v_nbaixas > 0 THEN
            RETURN QUERY SELECT false, 'NECESSARIO_ESTORNO', v_pag.id, NULL::uuid, v_pag.status_pagamento;
            RETURN;
        END IF;

        SELECT fp.id INTO v_titulo
          FROM public.financeiro_pagar fp
         WHERE fp.os_id = v_pag.os_id::text
         ORDER BY fp.created_at
         LIMIT 1;

        UPDATE public.financeiro_pagar fp
           SET status = 'cancelado'
         WHERE fp.os_id = v_pag.os_id::text
           AND COALESCE(fp.status,'') NOT IN ('pago','paga','cancelado','cancelada');
    END IF;

    -- Neutraliza lote (se houver)
    IF v_pag.lote_id IS NOT NULL THEN
        DELETE FROM public.lotes_pagamento_itens li WHERE li.pagamento_prestador_id = v_pag.id;
        UPDATE public.lotes_pagamento l
           SET quantidade_pagamentos = (SELECT count(*) FROM public.lotes_pagamento_itens i WHERE i.lote_id = l.id),
               valor_total = COALESCE((SELECT sum(i.valor) FROM public.lotes_pagamento_itens i WHERE i.lote_id = l.id), 0),
               updated_at = now()
         WHERE l.id = v_pag.lote_id;
    END IF;

    v_obs := CASE WHEN v_pag.observacao IS NULL OR v_pag.observacao = ''
                  THEN '[cancelar][' || to_char(now(),'YYYY-MM-DD HH24:MI') || '][' || left(auth.uid()::text,8) || '] ' || COALESCE(p_motivo,'sem motivo')
                  ELSE v_pag.observacao || E'\n[cancelar][' || to_char(now(),'YYYY-MM-DD HH24:MI') || '][' || left(auth.uid()::text,8) || '] ' || COALESCE(p_motivo,'sem motivo')
             END;

    UPDATE public.pagamentos_prestadores
       SET status            = 'cancelado',
           status_pagamento  = 'cancelado',
           elegivel_lote     = false,
           lote_id           = NULL,
           observacao        = v_obs
     WHERE id = v_pag.id;

    RETURN QUERY SELECT true, 'CANCELADO', v_pag.id, v_titulo, 'cancelado'::text;
END;
$$;


--
-- Name: FUNCTION "f_cancelar_pagamento_prestador"("p_pagamento_id" "uuid", "p_motivo" "text"); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."f_cancelar_pagamento_prestador"("p_pagamento_id" "uuid", "p_motivo" "text") IS 'TMS-FIN-PP-UX-02C1B: cancela obrigacao NAO paga; exige ausencia de baixa ativa; sincroniza FP e lote.';


--
-- Name: f_confirmar_pagamento_fechamento("uuid", "date"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."f_confirmar_pagamento_fechamento"("p_fechamento_id" "uuid", "p_data_pagamento" "date" DEFAULT CURRENT_DATE) RETURNS TABLE("sucesso" boolean, "mensagem" "text", "fechamento_id" "uuid", "itens_processados" integer, "itens_ignorados" integer, "total_baixas" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_fechamento       RECORD;
    v_item             RECORD;
    v_res              RECORD;
    v_data             DATE := COALESCE(p_data_pagamento, CURRENT_DATE);
    v_processados      INTEGER := 0;
    v_ignorados        INTEGER := 0;
    v_total_baixas     INTEGER := 0;
    v_total_itens      INTEGER := 0;
    v_total_valor      NUMERIC(18,2) := 0;
    v_tenant           uuid;
    v_tenant_ok        boolean := true;
BEGIN
    -- 0. Autorizacao (hardening)
    IF auth.uid() IS NULL THEN
        RETURN QUERY SELECT false, 'USUARIO_NAO_AUTENTICADO', p_fechamento_id, 0, 0, 0;
        RETURN;
    END IF;

    SELECT tu.tenant_id INTO v_tenant
      FROM public.tenant_usuarios tu
     WHERE tu.user_id = auth.uid() AND tu.status = 'ativo'
     LIMIT 1;

    IF v_tenant IS NULL OR NOT EXISTS (
        SELECT 1 FROM public.tenant_usuarios tu
         WHERE tu.user_id = auth.uid() AND tu.status = 'ativo'
           AND tu.papel IN ('super_admin','admin_tenant','financeiro')) THEN
        RETURN QUERY SELECT false, 'NAO_AUTORIZADO', p_fechamento_id, 0, 0, 0;
        RETURN;
    END IF;

    -- 1. Valida fechamento
    SELECT id, os_id, status_pagamento, status_aprovacao, status_conferencia, status, valor_liquido
      INTO v_fechamento
      FROM public.pagamentos_prestadores
     WHERE id = p_fechamento_id
       AND tipo_pagamento = 'fechamento'
       FOR UPDATE;

    IF NOT FOUND THEN
        RETURN QUERY SELECT false, 'Fechamento nao encontrado.', p_fechamento_id, 0, 0, 0;
        RETURN;
    END IF;

    IF v_fechamento.os_id IS NOT NULL
       AND public.f_pp_tenant_id(v_fechamento.os_id) IS DISTINCT FROM v_tenant THEN
        RETURN QUERY SELECT false, 'NAO_AUTORIZADO_TENANT', p_fechamento_id, 0, 0, 0;
        RETURN;
    END IF;

    IF v_fechamento.status_pagamento = 'pago' OR v_fechamento.status = 'pago' THEN
        RETURN QUERY SELECT false, 'Fechamento ja esta pago.', p_fechamento_id, 0, 0, 0;
        RETURN;
    END IF;

    IF v_fechamento.status_aprovacao <> 'aprovado' THEN
        RETURN QUERY SELECT false, 'Fechamento nao esta aprovado.', p_fechamento_id, 0, 0, 0;
        RETURN;
    END IF;

    -- 1.1 Reconciliacao: soma dos itens deve bater com o valor do fechamento + tenant dos itens
    SELECT COUNT(*), COALESCE(SUM(valor_liquido), 0),
           COALESCE(bool_and(CASE WHEN os_id IS NULL THEN true ELSE public.f_pp_tenant_id(os_id) IS NOT DISTINCT FROM v_tenant END), true)
      INTO v_total_itens, v_total_valor, v_tenant_ok
      FROM public.pagamentos_prestadores
     WHERE pagamentos_prestadores.fechamento_id = p_fechamento_id
       AND pagamentos_prestadores.id <> p_fechamento_id;

    IF v_total_itens = 0 THEN
        RETURN QUERY SELECT false, 'Fechamento nao possui itens vinculados.', p_fechamento_id, 0, 0, 0;
        RETURN;
    END IF;

    IF NOT v_tenant_ok THEN
        RETURN QUERY SELECT false, 'NAO_AUTORIZADO_TENANT', p_fechamento_id, 0, 0, 0;
        RETURN;
    END IF;

    IF ROUND(COALESCE(v_fechamento.valor_liquido, 0)::NUMERIC, 2) <> ROUND(v_total_valor, 2) THEN
        RETURN QUERY SELECT false,
                            'Divergencia de valores no fechamento: fechamento=' || COALESCE(v_fechamento.valor_liquido, 0) || ', itens=' || v_total_valor || '.',
                            p_fechamento_id, 0, 0, 0;
        RETURN;
    END IF;

    -- 2. Itera pelos itens vinculados
    FOR v_item IN
        SELECT id, status_pagamento, status
          FROM public.pagamentos_prestadores
         WHERE pagamentos_prestadores.fechamento_id = p_fechamento_id
           AND pagamentos_prestadores.id <> p_fechamento_id
         ORDER BY id
    LOOP
        IF v_item.status_pagamento = 'pago' OR v_item.status = 'pago' THEN
            v_ignorados := v_ignorados + 1;
            CONTINUE;
        END IF;

        IF v_item.status_pagamento = 'cancelado' OR v_item.status = 'cancelado' THEN
            RAISE EXCEPTION 'Item % do fechamento esta cancelado; pagamento nao pode prosseguir.', v_item.id;
        END IF;

        SELECT r.sucesso, r.mensagem, r.baixa_id
          INTO v_res
          FROM public.f_confirmar_pagamento_prestador(v_item.id, v_data) r;

        IF NOT v_res.sucesso THEN
            RAISE EXCEPTION 'Item % do fechamento falhou: %', v_item.id, COALESCE(v_res.mensagem, 'erro desconhecido');
        END IF;

        v_processados := v_processados + 1;
        IF v_res.baixa_id IS NOT NULL THEN
            v_total_baixas := v_total_baixas + 1;
        END IF;
    END LOOP;

    -- 3. Atualiza fechamento para pago
    UPDATE public.pagamentos_prestadores
       SET status = 'pago',
           status_pagamento = 'pago',
           status_conferencia = 'conferido',
           data_pagamento = v_data
     WHERE id = p_fechamento_id;

    RETURN QUERY SELECT true,
                        'Fechamento pago com sucesso. Itens processados: ' || v_processados || ', ignorados: ' || v_ignorados || ', baixas: ' || v_total_baixas || '.',
                        p_fechamento_id,
                        v_processados,
                        v_ignorados,
                        v_total_baixas;
END;
$$;


--
-- Name: FUNCTION "f_confirmar_pagamento_fechamento"("p_fechamento_id" "uuid", "p_data_pagamento" "date"); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."f_confirmar_pagamento_fechamento"("p_fechamento_id" "uuid", "p_data_pagamento" "date") IS 'TMS-FIN-PP-UX-02C1B: hardening auth/tenant/perfil; regra de pagamento preservada.';


--
-- Name: f_confirmar_pagamento_prestador("uuid", "date", numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."f_confirmar_pagamento_prestador"("p_pagamento_id" "uuid", "p_data_pagamento" "date" DEFAULT CURRENT_DATE, "p_valor_pago" numeric DEFAULT NULL::numeric) RETURNS TABLE("sucesso" boolean, "mensagem" "text", "pagamento_id" "uuid", "titulo_id" "uuid", "baixa_id" "uuid", "valor_pagamento" numeric, "valor_liquidado" numeric, "saldo_restante" numeric, "conta_financeira_id" "uuid", "conta_financeira" "text", "status_pagamento" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
    v_pagamento    RECORD;
    v_titulo       RECORD;
    v_conta        RECORD;
    v_total_baixado NUMERIC(18,2);
    v_saldo        NUMERIC(18,2);
    v_titulos      INTEGER;
    v_baixa_id     UUID;
    v_valor        NUMERIC(18,2);
    v_data         DATE := COALESCE(p_data_pagamento, CURRENT_DATE);
    v_eh_parcial   BOOLEAN := FALSE;
    v_tenant       uuid;
BEGIN
    -- Autorizacao: usuario TMS ativo com papel financeiro/admin
    IF auth.uid() IS NULL THEN
        RETURN QUERY SELECT false, 'USUARIO_NAO_AUTENTICADO', p_pagamento_id, NULL::UUID, NULL::UUID, NULL::NUMERIC, NULL::NUMERIC, NULL::NUMERIC, NULL::UUID, NULL::TEXT, NULL::TEXT;
        RETURN;
    END IF;
    SELECT tu.tenant_id INTO v_tenant FROM public.tenant_usuarios tu WHERE tu.user_id = auth.uid() AND tu.status = 'ativo' LIMIT 1;
    IF v_tenant IS NULL OR NOT EXISTS (
        SELECT 1 FROM public.tenant_usuarios tu
        WHERE tu.user_id = auth.uid() AND tu.status = 'ativo'
          AND tu.papel IN ('super_admin','admin_tenant','financeiro')) THEN
        RETURN QUERY SELECT false, 'NAO_AUTORIZADO', p_pagamento_id, NULL::UUID, NULL::UUID, NULL::NUMERIC, NULL::NUMERIC, NULL::NUMERIC, NULL::UUID, NULL::TEXT, NULL::TEXT;
        RETURN;
    END IF;

    SELECT p.*
      INTO v_pagamento
      FROM public.pagamentos_prestadores p
     WHERE p.id = p_pagamento_id
       FOR UPDATE;

    IF NOT FOUND THEN
        RETURN QUERY SELECT false, 'Pagamento de prestador nao encontrado.',
            p_pagamento_id, NULL::UUID, NULL::UUID, NULL::NUMERIC, NULL::NUMERIC,
            NULL::NUMERIC, NULL::UUID, NULL::TEXT, NULL::TEXT;
        RETURN;
    END IF;

    -- Isolamento por tenant quando o vinculo (os_id) e resolvivel
    IF v_pagamento.os_id IS NOT NULL THEN
        IF public.f_pp_tenant_id(v_pagamento.os_id) IS DISTINCT FROM v_tenant THEN
            RETURN QUERY SELECT false, 'NAO_AUTORIZADO_TENANT',
                v_pagamento.id, NULL::UUID, NULL::UUID, NULL::NUMERIC, NULL::NUMERIC,
                NULL::NUMERIC, NULL::UUID, NULL::TEXT, v_pagamento.status_pagamento;
            RETURN;
        END IF;
    END IF;

    IF p_valor_pago IS NOT NULL AND p_valor_pago > 0 THEN
        v_valor := ROUND(p_valor_pago::NUMERIC, 2);
        v_eh_parcial := TRUE;
    ELSIF p_valor_pago IS NOT NULL AND p_valor_pago <= 0 THEN
        RETURN QUERY SELECT false, 'Valor do pagamento parcial deve ser maior que zero.',
            p_pagamento_id, NULL::UUID, NULL::UUID, NULL::NUMERIC, NULL::NUMERIC,
            NULL::NUMERIC, NULL::UUID, NULL::TEXT, NULL::TEXT;
        RETURN;
    ELSE
        v_valor := ROUND(COALESCE(v_pagamento.valor_liquido, 0)::NUMERIC, 2);
        v_eh_parcial := FALSE;
    END IF;

    IF v_pagamento.status_pagamento = 'pago' OR v_pagamento.status = 'pago' THEN
        RETURN QUERY SELECT false, 'Pagamento ja esta marcado como pago.',
            v_pagamento.id, NULL::UUID, NULL::UUID, v_valor, NULL::NUMERIC,
            NULL::NUMERIC, NULL::UUID, NULL::TEXT, v_pagamento.status_pagamento;
        RETURN;
    END IF;

    IF v_pagamento.status_pagamento = 'cancelado' OR v_pagamento.status = 'cancelado' THEN
        RETURN QUERY SELECT false, 'Pagamento cancelado nao pode ser confirmado.',
            v_pagamento.id, NULL::UUID, NULL::UUID, v_valor, NULL::NUMERIC,
            NULL::NUMERIC, NULL::UUID, NULL::TEXT, v_pagamento.status_pagamento;
        RETURN;
    END IF;

    IF v_valor <= 0 THEN
        RETURN QUERY SELECT false, 'Valor do pagamento deve ser maior que zero.',
            v_pagamento.id, NULL::UUID, NULL::UUID, v_valor, NULL::NUMERIC,
            NULL::NUMERIC, NULL::UUID, NULL::TEXT, v_pagamento.status_pagamento;
        RETURN;
    END IF;

    SELECT c.id, c.nome
      INTO v_conta
      FROM public.contas_financeiras c
     WHERE c.ativa = true
     ORDER BY c.principal DESC, c.nome ASC
     LIMIT 1;

    IF NOT FOUND THEN
        RETURN QUERY SELECT false, 'Nenhuma conta financeira ativa esta configurada.',
            v_pagamento.id, NULL::UUID, NULL::UUID, v_valor, NULL::NUMERIC,
            NULL::NUMERIC, NULL::UUID, NULL::TEXT, v_pagamento.status_pagamento;
        RETURN;
    END IF;

    IF v_pagamento.os_id IS NOT NULL THEN
        SELECT count(*)::INTEGER INTO v_titulos
          FROM public.financeiro_pagar fp
         WHERE fp.os_id = v_pagamento.os_id::TEXT
           AND ROUND(COALESCE(fp.valor, 0)::NUMERIC, 2) = v_valor
           AND COALESCE(fp.status, '') NOT IN ('pago', 'paga', 'cancelado', 'cancelada', 'estornado')
           AND (
                TRIM(COALESCE(fp.prestador, '')) = TRIM(COALESCE(v_pagamento.prestador_id::TEXT, ''))
             OR LOWER(TRIM(COALESCE(fp.prestador, ''))) = LOWER(TRIM(COALESCE(v_pagamento.prestador_nome, '')))
             OR LOWER(TRIM(COALESCE(fp.fornecedor_nome, ''))) = LOWER(TRIM(COALESCE(v_pagamento.prestador_nome, '')))
           );
        IF v_titulos = 1 THEN
            SELECT fp.* INTO v_titulo
              FROM public.financeiro_pagar fp
             WHERE fp.os_id = v_pagamento.os_id::TEXT
               AND ROUND(COALESCE(fp.valor, 0)::NUMERIC, 2) = v_valor
               AND COALESCE(fp.status, '') NOT IN ('pago', 'paga', 'cancelado', 'cancelada', 'estornado')
               AND (
                    TRIM(COALESCE(fp.prestador, '')) = TRIM(COALESCE(v_pagamento.prestador_id::TEXT, ''))
                 OR LOWER(TRIM(COALESCE(fp.prestador, ''))) = LOWER(TRIM(COALESCE(v_pagamento.prestador_nome, '')))
                 OR LOWER(TRIM(COALESCE(fp.fornecedor_nome, ''))) = LOWER(TRIM(COALESCE(v_pagamento.prestador_nome, '')))
               )
             FOR UPDATE;
        ELSE
            SELECT count(*)::INTEGER INTO v_titulos
              FROM public.financeiro_pagar fp
             WHERE fp.os_id = v_pagamento.os_id::TEXT
               AND COALESCE(fp.status, '') NOT IN ('pago', 'paga', 'cancelado', 'cancelada', 'estornado')
               AND (
                    TRIM(COALESCE(fp.prestador, '')) = TRIM(COALESCE(v_pagamento.prestador_id::TEXT, ''))
                 OR LOWER(TRIM(COALESCE(fp.prestador, ''))) = LOWER(TRIM(COALESCE(v_pagamento.prestador_nome, '')))
                 OR LOWER(TRIM(COALESCE(fp.fornecedor_nome, ''))) = LOWER(TRIM(COALESCE(v_pagamento.prestador_nome, '')))
               );
            IF v_titulos <> 1 THEN
                RETURN QUERY SELECT false,
                    CASE WHEN v_titulos = 0
                         THEN 'Nao existe titulo financeiro aberto para esta OS e prestador.'
                         ELSE 'Existe mais de um titulo candidato para a mesma OS; conciliacao ambigua.'
                    END,
                    v_pagamento.id, NULL::UUID, NULL::UUID, v_valor, NULL::NUMERIC,
                    NULL::NUMERIC, v_conta.id, v_conta.nome, v_pagamento.status_pagamento;
                RETURN;
            END IF;
            SELECT fp.* INTO v_titulo
              FROM public.financeiro_pagar fp
             WHERE fp.os_id = v_pagamento.os_id::TEXT
               AND COALESCE(fp.status, '') NOT IN ('pago', 'paga', 'cancelado', 'cancelada', 'estornado')
               AND (
                    TRIM(COALESCE(fp.prestador, '')) = TRIM(COALESCE(v_pagamento.prestador_id::TEXT, ''))
                 OR LOWER(TRIM(COALESCE(fp.prestador, ''))) = LOWER(TRIM(COALESCE(v_pagamento.prestador_nome, '')))
                 OR LOWER(TRIM(COALESCE(fp.fornecedor_nome, ''))) = LOWER(TRIM(COALESCE(v_pagamento.prestador_nome, '')))
               )
             FOR UPDATE;
        END IF;
    ELSE
        SELECT count(*)::INTEGER INTO v_titulos
          FROM public.financeiro_pagar fp
         WHERE ROUND(COALESCE(fp.valor, 0)::NUMERIC, 2) = v_valor
           AND COALESCE(fp.status, '') NOT IN ('pago', 'paga', 'cancelado', 'cancelada', 'estornado')
           AND (
                TRIM(COALESCE(fp.prestador, '')) = TRIM(COALESCE(v_pagamento.prestador_id::TEXT, ''))
             OR LOWER(TRIM(COALESCE(fp.prestador, ''))) = LOWER(TRIM(COALESCE(v_pagamento.prestador_nome, '')))
             OR LOWER(TRIM(COALESCE(fp.fornecedor_nome, ''))) = LOWER(TRIM(COALESCE(v_pagamento.prestador_nome, '')))
           );
        IF v_titulos = 1 THEN
            SELECT fp.* INTO v_titulo
              FROM public.financeiro_pagar fp
             WHERE ROUND(COALESCE(fp.valor, 0)::NUMERIC, 2) = v_valor
               AND COALESCE(fp.status, '') NOT IN ('pago', 'paga', 'cancelado', 'cancelada', 'estornado')
               AND (
                    TRIM(COALESCE(fp.prestador, '')) = TRIM(COALESCE(v_pagamento.prestador_id::TEXT, ''))
                 OR LOWER(TRIM(COALESCE(fp.prestador, ''))) = LOWER(TRIM(COALESCE(v_pagamento.prestador_nome, '')))
                 OR LOWER(TRIM(COALESCE(fp.fornecedor_nome, ''))) = LOWER(TRIM(COALESCE(v_pagamento.prestador_nome, '')))
               )
             FOR UPDATE;
        ELSE
            SELECT count(*)::INTEGER INTO v_titulos
              FROM public.financeiro_pagar fp
             WHERE COALESCE(fp.status, '') NOT IN ('pago', 'paga', 'cancelado', 'cancelada', 'estornado')
               AND (
                    TRIM(COALESCE(fp.prestador, '')) = TRIM(COALESCE(v_pagamento.prestador_id::TEXT, ''))
                 OR LOWER(TRIM(COALESCE(fp.prestador, ''))) = LOWER(TRIM(COALESCE(v_pagamento.prestador_nome, '')))
                 OR LOWER(TRIM(COALESCE(fp.fornecedor_nome, ''))) = LOWER(TRIM(COALESCE(v_pagamento.prestador_nome, '')))
               );
            IF v_titulos <> 1 THEN
                RETURN QUERY SELECT false,
                    CASE WHEN v_titulos = 0
                         THEN 'Nao existe titulo financeiro aberto de mesma origem e prestador.'
                         ELSE 'Existem varios titulos de mesmo prestador; vinculo explicito e obrigatorio.'
                    END,
                    v_pagamento.id, NULL::UUID, NULL::UUID, v_valor, NULL::NUMERIC,
                    NULL::NUMERIC, v_conta.id, v_conta.nome, v_pagamento.status_pagamento;
                RETURN;
            END IF;
            SELECT fp.* INTO v_titulo
              FROM public.financeiro_pagar fp
             WHERE COALESCE(fp.status, '') NOT IN ('pago', 'paga', 'cancelado', 'cancelada', 'estornado')
               AND (
                    TRIM(COALESCE(fp.prestador, '')) = TRIM(COALESCE(v_pagamento.prestador_id::TEXT, ''))
                 OR LOWER(TRIM(COALESCE(fp.prestador, ''))) = LOWER(TRIM(COALESCE(v_pagamento.prestador_nome, '')))
                 OR LOWER(TRIM(COALESCE(fp.fornecedor_nome, ''))) = LOWER(TRIM(COALESCE(v_pagamento.prestador_nome, '')))
               )
             FOR UPDATE;
        END IF;
    END IF;

    SELECT COALESCE(SUM(fb.valor_baixado), 0)::NUMERIC(18,2)
      INTO v_total_baixado
      FROM public.financeiro_baixas fb
     WHERE fb.titulo_tabela = 'financeiro_pagar'
       AND fb.titulo_id = v_titulo.id
       AND NOT COALESCE(fb.estornada, false);

    v_saldo := ROUND(COALESCE(v_titulo.valor, 0)::NUMERIC, 2) - v_total_baixado;

    IF v_valor > v_saldo THEN
        RETURN QUERY SELECT false,
            'Valor do pagamento (R$ ' || v_valor || ') excede o saldo restante (R$ ' || v_saldo || ').',
            v_pagamento.id, v_titulo.id, NULL::UUID, v_valor, v_total_baixado,
            v_saldo, v_conta.id, v_conta.nome, v_pagamento.status_pagamento;
        RETURN;
    END IF;

    IF v_saldo <= 0 THEN
        RETURN QUERY SELECT false,
            'Titulo ja esta integralmente quitado.',
            v_pagamento.id, v_titulo.id, NULL::UUID, v_valor, v_total_baixado,
            v_saldo, v_conta.id, v_conta.nome, v_pagamento.status_pagamento;
        RETURN;
    END IF;

    INSERT INTO public.financeiro_baixas (
        titulo_tabela, titulo_id, valor_original, valor_baixado, saldo_restante,
        data_baixa, forma_pagamento, conta_financeira, conta_financeira_id,
        observacao, estornada
    ) VALUES (
        'financeiro_pagar', v_titulo.id, v_titulo.valor, v_valor,
        v_saldo - v_valor,
        v_data, 'Pagamento Prestador', v_conta.nome, v_conta.id,
        CASE WHEN v_eh_parcial
             THEN 'Baixa parcial - pagamento prestador ' || LEFT(v_pagamento.id::TEXT, 8)
             ELSE 'Baixa atomica - pagamento prestador ' || LEFT(v_pagamento.id::TEXT, 8)
        END,
        false
    ) RETURNING id INTO v_baixa_id;

    IF (v_saldo - v_valor) > 0 THEN
        UPDATE public.financeiro_pagar
           SET status = 'parcial', data_pagamento = v_data, data_efetiva_pgto = v_data, conta_pagadora = v_conta.nome,
               observacoes = CASE WHEN observacoes IS NULL OR observacoes = ''
                    THEN 'Baixa parcial R$ ' || v_valor || ' de R$ ' || v_titulo.valor
                    ELSE observacoes || E'\nBaixa parcial R$ ' || v_valor || ' de R$ ' || v_titulo.valor END
         WHERE id = v_titulo.id;
    ELSE
        UPDATE public.financeiro_pagar
           SET status = 'pago', data_pagamento = v_data, data_efetiva_pgto = v_data, conta_pagadora = v_conta.nome,
               observacoes = CASE WHEN observacoes IS NULL OR observacoes = ''
                    THEN 'Baixa integral de pagamento de prestador.'
                    ELSE observacoes || E'\nBaixa integral de pagamento de prestador.' END
         WHERE id = v_titulo.id;
    END IF;

    IF (v_saldo - v_valor) > 0 THEN
        UPDATE public.pagamentos_prestadores
           SET status_conferencia = 'conferido', data_pagamento = v_data
         WHERE id = v_pagamento.id;
    ELSE
        UPDATE public.pagamentos_prestadores
           SET status = 'pago', status_pagamento = 'pago', status_conferencia = 'conferido', data_pagamento = v_data
         WHERE id = v_pagamento.id;
    END IF;

    RETURN QUERY SELECT
        true,
        CASE WHEN v_eh_parcial
             THEN 'Pagamento parcial registrado. Saldo restante: R$ ' || (v_saldo - v_valor) || '.'
             ELSE 'Pagamento confirmado com baixa integral.' END,
        v_pagamento.id, v_titulo.id, v_baixa_id, v_valor, v_valor, v_saldo - v_valor,
        v_conta.id, v_conta.nome,
        CASE WHEN (v_saldo - v_valor) > 0 THEN 'pendente' ELSE 'pago' END;
END;
$_$;


--
-- Name: f_contar_mensagens_nao_lidas_torre(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."f_contar_mensagens_nao_lidas_torre"() RETURNS integer
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_total integer;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN 0;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.tenant_usuarios WHERE user_id = auth.uid()) THEN
    RETURN 0;
  END IF;
  SELECT count(*)::integer INTO v_total
  FROM public.operacao_mensagens
  WHERE sender_type = 'prestador' AND status = 'enviada';
  RETURN v_total;
END;
$$;


--
-- Name: FUNCTION "f_contar_mensagens_nao_lidas_torre"(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."f_contar_mensagens_nao_lidas_torre"() IS 'A22 — Total de mensagens do prestador ainda não lidas pela Torre (badge real).';


--
-- Name: f_cotacao_detalhes_para_os("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."f_cotacao_detalhes_para_os"("p_cotacao_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_cot              RECORD;
  v_cliente_id       uuid;
  v_cliente_nome     text;
  v_telefone         text;
  v_orcamento_id     uuid;
  v_orcamento_numero text;
  v_os_id            uuid;
  v_os_numero        text;
  v_enderecos        jsonb;
  v_carga            jsonb;
  v_valor            numeric;
  v_preco            jsonb;
  v_tipo_veiculo     text;
  v_rotulo           text;
  v_km               numeric;
  v_obs              text;
  v_hist_orc         jsonb;
  v_hist_os          jsonb;
  v_existente        RECORD;
  v_janela           text;
  v_janela_inicio    text;
  v_janela_fim       text;
  v_tem_agendamento  boolean;
BEGIN
  IF p_cotacao_id IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error_code', 'COTACAO_INVALIDA',
      'message', 'Cotação não informada.'
    );
  END IF;

  -- Serializa chamadas concorrentes da mesma cotação (evita duplicidade).
  PERFORM pg_advisory_xact_lock(hashtext('cotacao_express_os:' || p_cotacao_id::text)::bigint);

  SELECT * INTO v_cot
  FROM public.cotacoes_publicas
  WHERE id = p_cotacao_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false,
      'error_code', 'COTACAO_NAO_ENCONTRADA',
      'message', 'Cotação não encontrada.'
    );
  END IF;

  -- ----------------------------------------------------------
  -- IDEMPOTÊNCIA — vínculo já gravado na cotação
  -- ----------------------------------------------------------
  IF v_cot.orcamento_id IS NOT NULL THEN
    SELECT o.id, o.numero, o.cliente_id, o.os_vinculada_id, o.os_vinculada_numero
      INTO v_existente
      FROM public.orcamentos o
     WHERE o.id = v_cot.orcamento_id;

    IF FOUND THEN
      IF v_existente.os_vinculada_id IS NULL THEN
        SELECT id, numero INTO v_os_id, v_os_numero
          FROM public.ordens_servico
         WHERE orcamento_id = v_existente.id
         ORDER BY created_at
         LIMIT 1;

        IF v_os_id IS NOT NULL THEN
          UPDATE public.orcamentos
             SET os_vinculada_id = v_os_id,
                 os_vinculada_numero = v_os_numero,
                 status = 'convertido',
                 updated_at = now()
           WHERE id = v_existente.id;
          v_existente.os_vinculada_id := v_os_id;
          v_existente.os_vinculada_numero := v_os_numero;
        END IF;
      END IF;

      RETURN jsonb_build_object(
        'success', true,
        'created', false,
        'cotacao_id', v_cot.id,
        'cliente_id', v_existente.cliente_id,
        'orcamento_id', v_existente.id,
        'orcamento_numero', v_existente.numero,
        'os_id', v_existente.os_vinculada_id,
        'os_numero', v_existente.os_vinculada_numero
      );
    END IF;
  END IF;

  -- Fallback de idempotência: orçamento órfão com o mesmo pedido_interno.
  SELECT o.id, o.numero, o.cliente_id, o.os_vinculada_id, o.os_vinculada_numero
    INTO v_existente
    FROM public.orcamentos o
   WHERE o.pedido_interno = p_cotacao_id::text
   ORDER BY o.id
   LIMIT 1;

  IF FOUND THEN
    UPDATE public.cotacoes_publicas
       SET orcamento_id = v_existente.id,
           updated_at = now()
     WHERE id = p_cotacao_id;

    IF v_existente.os_vinculada_id IS NULL THEN
      SELECT id, numero INTO v_os_id, v_os_numero
        FROM public.ordens_servico
       WHERE orcamento_id = v_existente.id
       ORDER BY created_at
       LIMIT 1;

      IF v_os_id IS NOT NULL THEN
        UPDATE public.orcamentos
           SET os_vinculada_id = v_os_id,
               os_vinculada_numero = v_os_numero,
               status = 'convertido',
               updated_at = now()
         WHERE id = v_existente.id;
        v_existente.os_vinculada_id := v_os_id;
        v_existente.os_vinculada_numero := v_os_numero;
      END IF;
    END IF;

    RETURN jsonb_build_object(
      'success', true,
      'created', false,
      'cotacao_id', p_cotacao_id,
      'cliente_id', v_existente.cliente_id,
      'orcamento_id', v_existente.id,
      'orcamento_numero', v_existente.numero,
      'os_id', v_existente.os_vinculada_id,
      'os_numero', v_existente.os_vinculada_numero
    );
  END IF;

  -- Só permite gerar OS depois que o cliente concluiu os endereços.
  IF v_cot.status <> 'Pronto para OS' THEN
    RETURN jsonb_build_object(
      'success', false,
      'error_code', 'DETALHES_PENDENTES',
      'message', 'A cotação ainda não está pronta para gerar a OS.'
    );
  END IF;

  -- ----------------------------------------------------------
  -- DADOS BASE
  -- ----------------------------------------------------------
  v_cliente_nome := COALESCE(NULLIF(btrim(v_cot.nome_cliente), ''), 'Cliente Cotação Express');
  v_telefone     := NULLIF(btrim(COALESCE(v_cot.telefone, '')), '');
  v_preco        := COALESCE(v_cot.metadata -> 'precificacao', '{}'::jsonb);
  v_valor        := COALESCE(v_cot.valor_aprovado, NULLIF(v_preco ->> 'valor', '')::numeric, 0);
  v_tipo_veiculo := COALESCE(NULLIF(v_preco ->> 'tipo_veiculo', ''), '');
  v_rotulo       := COALESCE(NULLIF(v_preco ->> 'rotulo_veiculo', ''), '');
  v_km           := NULLIF(v_preco ->> 'distancia_km', '')::numeric;

  -- ----------------------------------------------------------
  -- JANELA DE HORÁRIO — "09:00 às 11:00" → início/fim
  -- ----------------------------------------------------------
  v_janela := btrim(COALESCE(v_cot.hora_desejada, ''));
  IF v_janela ~ '\d{1,2}:\d{2}' THEN
    v_janela_inicio := COALESCE((regexp_match(v_janela, '(\d{1,2}:\d{2})'))[1], '');
    v_janela_fim    := COALESCE((regexp_match(v_janela, '(\d{1,2}:\d{2})'))[2], '');
  ELSE
    v_janela_inicio := v_janela;
    v_janela_fim    := '';
  END IF;
  v_tem_agendamento := (v_cot.data_desejada IS NOT NULL) OR (v_janela <> '');

  -- ----------------------------------------------------------
  -- CLIENTE — dedup por nome/telefone; senão cria pré-cadastro
  -- ----------------------------------------------------------
  SELECT id INTO v_cliente_id
    FROM public.clientes
   WHERE lower(btrim(COALESCE(nome_fantasia, ''))) = lower(v_cliente_nome)
      OR lower(btrim(COALESCE(razao_social, ''))) = lower(v_cliente_nome)
   ORDER BY id
   LIMIT 1;

  IF v_cliente_id IS NULL AND v_telefone IS NOT NULL THEN
    SELECT id INTO v_cliente_id
      FROM public.clientes
     WHERE regexp_replace(COALESCE(telefone, ''), '\D', '', 'g') = regexp_replace(v_telefone, '\D', '', 'g')
        OR regexp_replace(COALESCE(whatsapp, ''), '\D', '', 'g') = regexp_replace(v_telefone, '\D', '', 'g')
     ORDER BY id
     LIMIT 1;
  END IF;

  IF v_cliente_id IS NULL THEN
    v_cliente_id := gen_random_uuid();

    INSERT INTO public.clientes (
      id, nome_fantasia, razao_social, telefone, whatsapp,
      status, origem_comercial, tenant_id
    ) VALUES (
      v_cliente_id,
      v_cliente_nome,
      v_cliente_nome,
      v_telefone,
      v_telefone,
      'pre-cadastro',
      'Cotação Express',
      COALESCE(public.current_tenant_id_safe(), '00000000-0000-0000-0000-000000000001'::uuid)
    );
  END IF;

  -- ----------------------------------------------------------
  -- ENDEREÇOS — paradas da Fase 1 + detalhes da Fase 2
  -- ----------------------------------------------------------
  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'sequencia', COALESCE(NULLIF(p ->> 'sequencia', '')::int, ord::int),
        'tipo', CASE WHEN ord = 1 THEN 'coleta' ELSE 'entrega' END,
        'endereco', CASE
          WHEN NULLIF(d ->> 'numero', '') IS NOT NULL
               AND position((d ->> 'numero') in COALESCE(p ->> 'endereco', '')) = 0
          THEN concat_ws(', ', NULLIF(p ->> 'endereco', ''), NULLIF(d ->> 'numero', ''))
          ELSE COALESCE(p ->> 'endereco', '')
        END,
        'logradouro', COALESCE(p ->> 'endereco', ''),
        'numero', COALESCE(d ->> 'numero', ''),
        'complemento', COALESCE(d ->> 'complemento', ''),
        'cep', '',
        'bairro', '',
        'cidade', '',
        'uf', '',
        'referencia', COALESCE(
          NULLIF(btrim(concat_ws(' · ',
            NULLIF(d ->> 'numero', ''),
            NULLIF(d ->> 'complemento', ''),
            NULLIF(d ->> 'observacoes', '')
          ), ' ·'), ''),
          ''
        ),
        'instrucoes', COALESCE(
          NULLIF(btrim(concat_ws(' · ',
            NULLIF(d ->> 'numero', ''),
            NULLIF(d ->> 'complemento', ''),
            NULLIF(d ->> 'observacoes', '')
          ), ' ·'), ''),
          ''
        ),
        'contato', COALESCE(d ->> 'contato', ''),
        'contatoNome', COALESCE(d ->> 'contato', ''),
        'contato_nome', COALESCE(d ->> 'contato', ''),
        'responsavel', COALESCE(d ->> 'contato', ''),
        'telefone', '',
        'janelaInicio', v_janela_inicio,
        'janela_inicio', v_janela_inicio,
        'janelaFim', v_janela_fim,
        'janela_fim', v_janela_fim,
        'janelaHorario', v_janela,
        'agendamento', v_tem_agendamento,
        'statusPonto', 'pendente',
        'status_ponto', 'pendente',
        'observacoes', COALESCE(d ->> 'observacoes', '')
      )
      ORDER BY ord
    ),
    '[]'::jsonb
  )
  INTO v_enderecos
  FROM jsonb_array_elements(COALESCE(v_cot.paradas, '[]'::jsonb)) WITH ORDINALITY AS t(p, ord)
  LEFT JOIN LATERAL (
    SELECT dd AS d
      FROM jsonb_array_elements(COALESCE(v_cot.detalhes, '[]'::jsonb)) WITH ORDINALITY AS dt(dd, dord)
     WHERE COALESCE(NULLIF(dd ->> 'sequencia', '')::int, dord::int)
           = COALESCE(NULLIF(p ->> 'sequencia', '')::int, ord::int)
     LIMIT 1
  ) det ON true;

  -- ----------------------------------------------------------
  -- CARGA / OBSERVAÇÕES
  -- ----------------------------------------------------------
  v_carga := jsonb_build_object(
    'tipo', 'Seca',
    'descricao', COALESCE(v_cot.carga_descricao, ''),
    'volumes', COALESCE(v_cot.carga_volumes, 0),
    'peso', COALESCE(v_cot.carga_peso, 0),
    'cubagem', 0,
    'pallets', 0,
    'valorDeclarado', 0,
    'qtdNotas', 0,
    'refrigerada', false,
    'ajudante', false,
    'fragil', false,
    'empilhavel', true,
    'risco', false,
    'perigosa', false,
    'controlada', false,
    'conferencia', false,
    'equipamento', '',
    'condicao', '',
    'comprimento', 0,
    'largura', 0,
    'altura', 0,
    'pesoPorVolume', 0,
    'temperaturaMinima', 0,
    'temperaturaMaxima', 0,
    'observacoesCarga', COALESCE(v_cot.carga_dimensoes, ''),
    'data_desejada', COALESCE(to_char(v_cot.data_desejada, 'YYYY-MM-DD'), ''),
    'hora_desejada', COALESCE(v_cot.hora_desejada, ''),
    'janela_inicio', v_janela_inicio,
    'janela_fim', v_janela_fim,
    'janela_horario', v_janela,
    'agendado', v_tem_agendamento,
    'origem_cotacao', v_cot.id::text
  );

  v_obs := concat_ws(' · ',
    'Cotação web (Fase 2) — cliente ' || v_cliente_nome,
    CASE WHEN v_telefone IS NOT NULL THEN 'WhatsApp: ' || v_telefone END,
    CASE WHEN v_valor > 0 THEN 'Valor aprovado: R$ ' || replace(to_char(v_valor, 'FM999999990D00'), '.', ',') END,
    CASE WHEN v_km IS NOT NULL THEN 'Distância estimada: ' || v_km || ' km' END,
    CASE WHEN v_rotulo <> '' THEN 'Veículo sugerido: ' || v_rotulo END,
    CASE WHEN v_cot.data_desejada IS NOT NULL THEN 'Data desejada: ' || to_char(v_cot.data_desejada, 'DD/MM/YYYY') END,
    CASE WHEN v_janela <> '' THEN 'Horário: ' || v_janela END,
    'ID da cotação: ' || v_cot.id::text
  );

  v_hist_orc := jsonb_build_array(
    jsonb_build_object(
      'data', to_char(now(), 'DD/MM/YYYY HH24:MI:SS'),
      'acao', 'Orçamento criado automaticamente pela Cotação Express (Fase 2)',
      'usuario', 'Site /cotacao-express'
    )
  );

  v_hist_os := jsonb_build_array(
    jsonb_build_object(
      'data', now(),
      'acao', 'OS criada automaticamente pela Cotação Express (Fase 2)',
      'status_novo', 'pendente',
      'usuario', 'Sistema'
    )
  );

  -- ----------------------------------------------------------
  -- NÚMERO DO ORÇAMENTO (ORC-AAAAMM-XXXX, único)
  -- ----------------------------------------------------------
  LOOP
    v_orcamento_numero := 'ORC-' || to_char(now(), 'YYYYMM') || '-' ||
      lpad((floor(random() * 9000) + 1000)::int::text, 4, '0');
    EXIT WHEN NOT EXISTS (
      SELECT 1 FROM public.orcamentos WHERE numero = v_orcamento_numero
    );
  END LOOP;

  INSERT INTO public.orcamentos (
    numero, cliente, cliente_id, unidade, data_emissao, validade,
    tipo_operacao, modalidade, prioridade, pedido_interno,
    observacoes_gerais, status,
    carga_descricao, carga_volumes, carga_peso, carga_cubagem,
    carga_pallets, carga_valor_declarado, carga_refrigerado, carga_ajudante,
    carga_fragil, carga_tipo, carga_refrigerada, carga_empilhavel,
    carga_risco, carga_perigosa, carga_controlada, veiculo_termica,
    veiculo_tipo,
    valor_base, pedagio, adicionais, descontos, valor_final, custo_estimado,
    historico, enderecos, carga, veiculo, valores,
    created_at, updated_at
  ) VALUES (
    v_orcamento_numero, v_cliente_nome, v_cliente_id, 'São Paulo - Matriz',
    (now() AT TIME ZONE 'America/Sao_Paulo')::date, NULL, 'Coleta e Entrega', 'esporadico', 'normal',
    p_cotacao_id::text, v_obs, 'em_analise',
    COALESCE(v_cot.carga_descricao, ''), COALESCE(v_cot.carga_volumes, 0),
    COALESCE(v_cot.carga_peso, 0), 0, 0, 0, false, false,
    false, 'Seca', false, true, false, false, false, 'seco',
    v_tipo_veiculo,
    v_valor, 0, 0, 0, v_valor, 0,
    v_hist_orc, v_enderecos, v_carga,
    jsonb_build_object('tipo', v_tipo_veiculo, 'subcategoria', v_rotulo, 'carroceria', ''),
    jsonb_build_object(
      'tabelaVinculada', COALESCE(v_preco ->> 'tabela', ''),
      'valorBase', v_valor,
      'adicionais', 0,
      'pedagio', 0,
      'kmExcedente', COALESCE((v_preco -> 'formula' ->> 'kmExcedente')::numeric, 0),
      'ajudante', 0,
      'devolucao', 0,
      'reentrega', 0,
      'descontos', 0,
      'valorFinal', v_valor,
      'custoEstimado', 0,
      'margemEstimada', 0,
      'lucroEstimado', 0
    ),
    now(), now()
  )
  RETURNING id INTO v_orcamento_id;

  -- ----------------------------------------------------------
  -- NÚMERO DA OS (OS-AAAAMM-NNNNNN, único)
  -- ----------------------------------------------------------
  LOOP
    v_os_numero := 'OS-' || to_char(now(), 'YYYYMM') || '-' ||
      lpad((floor(random() * 900000) + 100000)::int::text, 6, '0');
    EXIT WHEN NOT EXISTS (
      SELECT 1 FROM public.ordens_servico WHERE numero = v_os_numero
    );
  END LOOP;

  INSERT INTO public.ordens_servico (
    numero, data, cliente, cliente_id, unidade, status,
    tipo_operacao, modalidade, prioridade,
    carga_descricao, peso, volumes, valor_declarado, tipo_carga,
    observacoes_gerais, origem, destino,
    carga, enderecos, historico,
    valor_cliente, custo_prestador,
    tipo_veiculo, veiculo_subcategoria, veiculo_carroceria, veiculo_termica,
    orcamento_id, orcamento_origem,
    status_faturamento, status_pagamento,
    created_at, updated_at
  ) VALUES (
    v_os_numero, (now() AT TIME ZONE 'America/Sao_Paulo')::date, v_cliente_id, v_cliente_id::text,
    'São Paulo - Matriz', 'pendente',
    'Coleta e Entrega', 'esporadico', 'normal',
    COALESCE(v_cot.carga_descricao, ''), COALESCE(v_cot.carga_peso, 0),
    COALESCE(v_cot.carga_volumes, 0), 0, 'Seca',
    v_obs,
    COALESCE(v_enderecos -> 0 ->> 'endereco', ''),
    COALESCE(v_enderecos -> (jsonb_array_length(v_enderecos) - 1) ->> 'endereco', ''),
    v_carga, v_enderecos, v_hist_os,
    v_valor, 0,
    v_tipo_veiculo, v_rotulo, '', 'seco',
    v_orcamento_id, v_orcamento_numero,
    'a faturar', 'a pagar',
    now(), now()
  )
  RETURNING id INTO v_os_id;

  UPDATE public.orcamentos
     SET status = 'convertido',
         os_vinculada_id = v_os_id,
         os_vinculada_numero = v_os_numero,
         updated_at = now()
   WHERE id = v_orcamento_id;

  UPDATE public.cotacoes_publicas
     SET orcamento_id = v_orcamento_id,
         status = 'Pronto para OS',
         updated_at = now()
   WHERE id = p_cotacao_id;

  RETURN jsonb_build_object(
    'success', true,
    'created', true,
    'cotacao_id', p_cotacao_id,
    'cliente_id', v_cliente_id,
    'orcamento_id', v_orcamento_id,
    'orcamento_numero', v_orcamento_numero,
    'os_id', v_os_id,
    'os_numero', v_os_numero,
    'janela_inicio', v_janela_inicio,
    'janela_fim', v_janela_fim
  );
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING '[f_cotacao_detalhes_para_os] %', SQLERRM;
  RETURN jsonb_build_object(
    'success', false,
    'error_code', 'ERRO_CONVERSAO',
    'message', 'Não foi possível abrir a OS agora. Tente novamente em instantes.'
  );
END;
$_$;


--
-- Name: f_cotacao_status_cliente("uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."f_cotacao_status_cliente"("p_cotacao_id" "uuid", "p_acao" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_cot        public.cotacoes_publicas%ROWTYPE;
  v_acao       text;
  v_orc_id     uuid;
  v_os_id      uuid;
  v_os_status  text;
  v_now_text   text := to_char(now(), 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"');
BEGIN
  v_acao := lower(btrim(COALESCE(p_acao, '')));

  IF v_acao NOT IN ('aguardando', 'cancelada') THEN
    RETURN jsonb_build_object(
      'success', false,
      'error_code', 'ACAO_INVALIDA',
      'message', 'Ação inválida.'
    );
  END IF;

  IF p_cotacao_id IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error_code', 'COTACAO_INVALIDA',
      'message', 'Cotação não informada.'
    );
  END IF;

  SELECT * INTO v_cot FROM public.cotacoes_publicas WHERE id = p_cotacao_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false,
      'error_code', 'COTACAO_NAO_ENCONTRADA',
      'message', 'Cotação não encontrada.'
    );
  END IF;

  -- Orçamento/OS vinculados (a cotação pode ainda não ter OS gerada).
  v_orc_id := v_cot.orcamento_id;
  IF v_orc_id IS NULL THEN
    SELECT o.id
      INTO v_orc_id
      FROM public.orcamentos o
     WHERE o.pedido_interno = v_cot.id::text
     ORDER BY o.created_at
     LIMIT 1;
  END IF;

  IF v_orc_id IS NOT NULL THEN
    SELECT os.id, os.status
      INTO v_os_id, v_os_status
      FROM public.ordens_servico os
     WHERE os.orcamento_id = v_orc_id
     ORDER BY os.created_at
     LIMIT 1;

    IF v_os_id IS NULL THEN
      SELECT o.os_vinculada_id
        INTO v_os_id
        FROM public.orcamentos o
       WHERE o.id = v_orc_id;

      IF v_os_id IS NOT NULL THEN
        SELECT os.status INTO v_os_status
          FROM public.ordens_servico os
         WHERE os.id = v_os_id;
      END IF;
    END IF;
  END IF;

  -- ----------------------------------------------------------
  -- 'aguardando' — cliente chegou na tela final e ainda NÃO
  -- confirmou no WhatsApp → OS em 'rascunho' com marca explícita.
  -- ----------------------------------------------------------
  IF v_acao = 'aguardando' THEN
    IF v_os_id IS NOT NULL
       AND COALESCE(v_os_status, '') IN ('rascunho', 'em_analise', 'pendente')
    THEN
      UPDATE public.ordens_servico
         SET status = 'rascunho',
             historico = COALESCE(historico, '[]'::jsonb) || jsonb_build_array(
               jsonb_build_object(
                 'tipo', 'status',
                 'status_anterior', v_os_status,
                 'status_novo', 'rascunho',
                 'descricao', 'Aguardando confirmação do cliente via WhatsApp',
                 'data', v_now_text
               )
             ),
             observacoes_gerais = CASE
               WHEN COALESCE(observacoes_gerais, '') ILIKE '%aguardando confirma%'
                 THEN observacoes_gerais
               ELSE btrim(
                 COALESCE(observacoes_gerais, '') ||
                 ' | Aguardando confirmação do cliente via WhatsApp'
               )
             END,
             updated_at = now()
       WHERE id = v_os_id;
    END IF;

    RETURN jsonb_build_object(
      'success', true,
      'acao', 'aguardando',
      'cotacao_id', p_cotacao_id,
      'os_id', v_os_id,
      'os_status', 'rascunho'
    );
  END IF;

  -- ----------------------------------------------------------
  -- 'cancelada' — cliente clicou em "Cancelar / Não preciso mais".
  -- ----------------------------------------------------------
  UPDATE public.cotacoes_publicas
     SET status = 'Cancelada pelo Cliente',
         metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object(
           'cancelado_pelo_cliente', true,
           'cancelado_em', v_now_text
         ),
         updated_at = now()
   WHERE id = p_cotacao_id;

  IF v_os_id IS NOT NULL
     AND COALESCE(v_os_status, '') IN ('rascunho', 'em_analise', 'pendente', 'agendada')
  THEN
    UPDATE public.ordens_servico
       SET status = 'cancelada',
           historico = COALESCE(historico, '[]'::jsonb) || jsonb_build_array(
             jsonb_build_object(
               'tipo', 'cancelamento',
               'status_anterior', v_os_status,
               'status_novo', 'cancelada',
               'descricao', 'Cancelada pelo Cliente (não confirmou via WhatsApp)',
               'data', v_now_text
             )
           ),
           observacoes_gerais = CASE
             WHEN COALESCE(observacoes_gerais, '') ILIKE '%cancelada pelo cliente%'
               THEN observacoes_gerais
             ELSE btrim(
               COALESCE(observacoes_gerais, '') ||
               ' | Cancelada pelo Cliente (não confirmou via WhatsApp)'
             )
           END,
           updated_at = now()
     WHERE id = v_os_id;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'acao', 'cancelada',
    'cotacao_id', p_cotacao_id,
    'status', 'Cancelada pelo Cliente',
    'os_id', v_os_id,
    'os_status_anterior', v_os_status
  );
END;
$$;


--
-- Name: f_criar_lancamento_manual_prestador("uuid", "text", "date", numeric, "text", "text", "text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."f_criar_lancamento_manual_prestador"("p_prestador_id" "uuid", "p_tipo_lancamento" "text", "p_data" "date", "p_valor" numeric, "p_descricao" "text", "p_forma_pagamento" "text" DEFAULT NULL::"text", "p_conta_pagamento" "text" DEFAULT NULL::"text", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS TABLE("sucesso" boolean, "mensagem" "text", "pagamento_prestador_id" "uuid", "financeiro_pagar_id" "uuid", "idempotente" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid        uuid := auth.uid();
  v_tenant     uuid;
  v_papel      text;
  v_prestador  RECORD;
  v_tipos_validos text[] := ARRAY['Serviço Avulso','Ajuste','Reembolso','Adiantamento'];
  v_tipo       text;
  v_valor      numeric(18,2);
  v_data       date;
  v_desc       text;
  v_forma      text;
  v_conta      text;
  v_key        text;
  v_obs        text;
  v_pp_id      uuid;
  v_fp_id      uuid;
  v_existente  uuid;
BEGIN
  -- 1. Autenticação
  IF v_uid IS NULL THEN
    RETURN QUERY SELECT false, 'USUARIO_NAO_AUTENTICADO', NULL::uuid, NULL::uuid, false;
    RETURN;
  END IF;

  -- 2. Tenant + perfil financeiro/admin
  SELECT tu.tenant_id, tu.papel INTO v_tenant, v_papel
    FROM public.tenant_usuarios tu
   WHERE tu.user_id = v_uid AND tu.status = 'ativo'
   LIMIT 1;
  IF v_tenant IS NULL THEN
    RETURN QUERY SELECT false, 'USUARIO_SEM_TENANT_ATIVO', NULL::uuid, NULL::uuid, false;
    RETURN;
  END IF;
  IF NOT (COALESCE(v_papel,'') = ANY(ARRAY['super_admin','admin_tenant','financeiro'])) THEN
    RETURN QUERY SELECT false, 'PAPEL_NAO_AUTORIZADO', NULL::uuid, NULL::uuid, false;
    RETURN;
  END IF;

  -- 3. Validação de prestador
  IF p_prestador_id IS NULL THEN
    RETURN QUERY SELECT false, 'PRESTADOR_OBRIGATORIO', NULL::uuid, NULL::uuid, false;
    RETURN;
  END IF;
  SELECT p.id, p.nome_completo, p.cpf_cnpj INTO v_prestador
    FROM public.prestadores p
   WHERE p.id = p_prestador_id AND p.status = 'ativo';
  IF NOT FOUND THEN
    RETURN QUERY SELECT false, 'PRESTADOR_NAO_ENCONTRADO_OU_INATIVO', NULL::uuid, NULL::uuid, false;
    RETURN;
  END IF;

  -- 4. Tipo / data / valor / descrição
  v_tipo := btrim(COALESCE(p_tipo_lancamento,''));
  IF NOT (v_tipo = ANY(v_tipos_validos)) THEN
    RETURN QUERY SELECT false, 'TIPO_INVALIDO', NULL::uuid, NULL::uuid, false;
    RETURN;
  END IF;

  IF p_data IS NULL THEN
    RETURN QUERY SELECT false, 'DATA_OBRIGATORIA', NULL::uuid, NULL::uuid, false;
    RETURN;
  END IF;
  v_data := p_data;

  v_valor := ROUND(COALESCE(p_valor,0)::numeric, 2);
  IF v_valor <= 0 THEN
    RETURN QUERY SELECT false, 'VALOR_INVALIDO', NULL::uuid, NULL::uuid, false;
    RETURN;
  END IF;

  v_desc := btrim(COALESCE(p_descricao,''));
  IF v_desc = '' THEN
    RETURN QUERY SELECT false, 'DESCRICAO_OBRIGATORIA', NULL::uuid, NULL::uuid, false;
    RETURN;
  END IF;

  v_forma := NULLIF(btrim(COALESCE(p_forma_pagamento,'')), '');
  v_conta := NULLIF(btrim(COALESCE(p_conta_pagamento,'')), '');
  v_key   := NULLIF(btrim(COALESCE(p_idempotency_key,'')), '');

  -- 5. Idempotência: retry da MESMA submissão retorna o lançamento existente
  IF v_key IS NOT NULL THEN
    SELECT pp.id INTO v_existente
      FROM public.pagamentos_prestadores pp
     WHERE pp.origem_lancamento = 'manual'
       AND pp.observacao LIKE '%[IDEMP:' || v_key || ']%'
     LIMIT 1;
    IF v_existente IS NOT NULL THEN
      SELECT fp.id INTO v_fp_id
        FROM public.financeiro_pagar fp
       WHERE fp.os_vinculada = v_existente::text
       LIMIT 1;
      RETURN QUERY SELECT true, 'LANCAMENTO_JA_EXISTENTE', v_existente, v_fp_id, true;
      RETURN;
    END IF;
  END IF;

  v_obs := v_desc
        || CASE WHEN v_conta IS NOT NULL THEN ' [Conta: ' || v_conta || ']' ELSE '' END
        || CASE WHEN v_key   IS NOT NULL THEN ' [IDEMP:' || v_key || ']'   ELSE '' END;

  -- 6. PP — workflow operacional (obrigação manual, sem OS)
  INSERT INTO public.pagamentos_prestadores (
    prestador_id, prestador_nome, prestador_documento,
    os_id, os_numero,
    valor_liquido, valor_servicos,
    status, status_conferencia, status_aprovacao, status_pagamento,
    origem_lancamento, tipo_lancamento, tipo_pagamento, natureza,
    quantidade_os, categoria_financeira,
    data_competencia, competencia, data_prevista_pagamento, periodo_inicio, periodo_fim,
    elegivel_lote, impacto_dre, impacto_fluxo_caixa, observacao, is_teste
  ) VALUES (
    v_prestador.id, v_prestador.nome_completo, v_prestador.cpf_cnpj,
    NULL, NULL,
    v_valor, v_valor,
    'pendente', 'em_aberto', 'aguardando_aprovacao', 'pendente',
    'manual', v_tipo, v_forma, 'credito',
    1, 'Custo Logístico',
    v_data, v_data, v_data, v_data, v_data,
    false, true, true, v_obs, false
  ) RETURNING id INTO v_pp_id;

  -- 7. FP — obrigação contábil (os_id NULL; vínculo via os_vinculada = pp.id)
  INSERT INTO public.financeiro_pagar (
    os_id, os_vinculada, descricao, valor, data_emissao, data_vencimento, status,
    prestador, fornecedor_id, fornecedor_nome, categoria, observacoes
  ) VALUES (
    NULL, v_pp_id::text, v_desc, v_valor, v_data, v_data, 'aberto',
    v_prestador.nome_completo, v_prestador.id, v_prestador.nome_completo,
    'Custo Logístico', v_obs
  ) RETURNING id INTO v_fp_id;

  RETURN QUERY SELECT true, 'LANCAMENTO_CRIADO', v_pp_id, v_fp_id, false;
END;
$$;


--
-- Name: FUNCTION "f_criar_lancamento_manual_prestador"("p_prestador_id" "uuid", "p_tipo_lancamento" "text", "p_data" "date", "p_valor" numeric, "p_descricao" "text", "p_forma_pagamento" "text", "p_conta_pagamento" "text", "p_idempotency_key" "text"); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."f_criar_lancamento_manual_prestador"("p_prestador_id" "uuid", "p_tipo_lancamento" "text", "p_data" "date", "p_valor" numeric, "p_descricao" "text", "p_forma_pagamento" "text", "p_conta_pagamento" "text", "p_idempotency_key" "text") IS 'FIN-PP-FUNC-01 — Cria obrigação manual de prestador (PP + FP) de forma atômica, autenticada e idempotente.';


--
-- Name: f_criar_recebivel_manual("jsonb", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."f_criar_recebivel_manual"("p_payload" "jsonb", "p_idempotency_key" "text") RETURNS TABLE("recebivel_id" "uuid", "criado" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid        uuid := auth.uid();
  v_tenant     uuid;
  v_papel      text;
  v_key        text;
  v_existing   uuid;
  v_id         uuid;
  v_cliente_id uuid;
  v_valor      numeric;
  v_valor_br   numeric;
  v_venc       date;
  v_status     text;
BEGIN
  -- (2) auth.uid() obrigatorio
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'NAO_AUTENTICADO' USING ERRCODE = '28000';
  END IF;

  -- (3) autorizacao: usuario TMS ativo com papel financeiro/admin
  SELECT tu.tenant_id, tu.papel
    INTO v_tenant, v_papel
    FROM public.tenant_usuarios tu
   WHERE tu.user_id = v_uid
   LIMIT 1;

  IF v_tenant IS NULL THEN
    RAISE EXCEPTION 'USUARIO_SEM_VINCULO_TENANT' USING ERRCODE = '28000';
  END IF;

  IF v_papel IS NULL OR lower(v_papel) NOT IN ('super_admin','admin','financeiro') THEN
    RAISE EXCEPTION 'SEM_PERMISSAO_FINANCEIRO' USING ERRCODE = '42501';
  END IF;

  -- (8/9) Idempotencia: chave obrigatoria
  v_key := NULLIF(btrim(coalesce(p_idempotency_key, '')), '');
  IF v_key IS NULL THEN
    RAISE EXCEPTION 'IDEMPOTENCY_KEY_OBRIGATORIA' USING ERRCODE = '22023';
  END IF;

  -- Retorno rapido se ja existir (retry/duplo clique)
  SELECT fr.id INTO v_existing
    FROM public.financeiro_receber fr
   WHERE fr.idempotency_key = v_key
   LIMIT 1;

  IF v_existing IS NOT NULL THEN
    RETURN QUERY SELECT v_existing, false;
    RETURN;
  END IF;

  -- (4) cliente obrigatorio + vinculo seguro de tenant via clientes.tenant_id
  v_cliente_id := NULLIF(p_payload->>'cliente_id', '')::uuid;
  IF v_cliente_id IS NULL THEN
    RAISE EXCEPTION 'CLIENTE_OBRIGATORIO' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.clientes c
     WHERE c.id = v_cliente_id
       AND c.tenant_id = v_tenant
  ) THEN
    RAISE EXCEPTION 'CLIENTE_INVALIDO_OU_OUTRO_TENANT' USING ERRCODE = '42501';
  END IF;

  -- (5) valor > 0
  v_valor_br := NULLIF(p_payload->>'valor_bruto', '')::numeric;
  v_valor    := COALESCE(NULLIF(p_payload->>'valor_liquido', '')::numeric, v_valor_br);
  IF v_valor IS NULL OR v_valor <= 0 THEN
    RAISE EXCEPTION 'VALOR_INVALIDO' USING ERRCODE = '22023';
  END IF;

  -- (6) vencimento obrigatorio
  v_venc := COALESCE(
              NULLIF(p_payload->>'data_vencimento', '')::date,
              NULLIF(p_payload->>'vencimento', '')::date
            );
  IF v_venc IS NULL THEN
    RAISE EXCEPTION 'VENCIMENTO_OBRIGATORIO' USING ERRCODE = '22023';
  END IF;

  -- (7) status inicial exclusivamente permitido na criacao
  v_status := lower(coalesce(NULLIF(p_payload->>'status', ''), 'aberto'));
  IF v_status NOT IN ('aberto','pendente','a vencer','a_vencer','previsto') THEN
    RAISE EXCEPTION 'STATUS_INICIAL_INVALIDO: %' , v_status USING ERRCODE = '22023';
  END IF;

  -- (10) INSERT transacional, idempotente por constraint unica
  INSERT INTO public.financeiro_receber (
    cliente_id, cliente, cliente_nome, cliente_documento, descricao,
    valor, valor_bruto, valor_liquido, desconto, juros, multa, abatimento,
    vencimento, data_vencimento, data_emissao, data_previsao_recebimento,
    status, fatura, fatura_id, serie, numero, os_id, os_vinculadas,
    contrato_vinculado, proposta_vinculada, categoria, centro_resultado,
    plano_conta, conta_entrada, recorrente, recorrencia, quantidade_parcelas,
    parcela_atual, observacoes, idempotency_key
  ) VALUES (
    v_cliente_id,
    COALESCE(NULLIF(p_payload->>'cliente',''), NULLIF(p_payload->>'cliente_nome','')),
    NULLIF(p_payload->>'cliente_nome',''),
    NULLIF(p_payload->>'cliente_documento',''),
    NULLIF(p_payload->>'descricao',''),
    v_valor,
    COALESCE(v_valor_br, v_valor),
    v_valor,
    COALESCE(NULLIF(p_payload->>'desconto','')::numeric, 0),
    COALESCE(NULLIF(p_payload->>'juros','')::numeric, 0),
    COALESCE(NULLIF(p_payload->>'multa','')::numeric, 0),
    COALESCE(NULLIF(p_payload->>'abatimento','')::numeric, 0),
    v_venc,
    v_venc,
    COALESCE(NULLIF(p_payload->>'data_emissao','')::date, CURRENT_DATE),
    NULLIF(p_payload->>'data_previsao_recebimento','')::date,
    v_status,
    NULLIF(p_payload->>'fatura',''),
    NULLIF(p_payload->>'fatura_id','')::uuid,
    NULLIF(p_payload->>'serie',''),
    NULLIF(p_payload->>'numero',''),
    NULLIF(p_payload->>'os_id',''),
    NULLIF(p_payload->>'os_vinculadas',''),
    NULLIF(p_payload->>'contrato_vinculado',''),
    NULLIF(p_payload->>'proposta_vinculada',''),
    NULLIF(p_payload->>'categoria',''),
    NULLIF(p_payload->>'centro_resultado',''),
    NULLIF(p_payload->>'plano_conta',''),
    NULLIF(p_payload->>'conta_entrada',''),
    COALESCE(NULLIF(p_payload->>'recorrente','')::boolean, false),
    COALESCE(NULLIF(p_payload->>'recorrencia',''), 'nenhuma'),
    COALESCE(NULLIF(p_payload->>'quantidade_parcelas','')::integer, 1),
    COALESCE(NULLIF(p_payload->>'parcela_atual','')::integer, 1),
    NULLIF(p_payload->>'observacoes',''),
    v_key
  )
  ON CONFLICT (idempotency_key) WHERE idempotency_key IS NOT NULL DO NOTHING
  RETURNING public.financeiro_receber.id INTO v_id;

  IF v_id IS NULL THEN
    SELECT fr.id INTO v_id
      FROM public.financeiro_receber fr
     WHERE fr.idempotency_key = v_key
     LIMIT 1;
    RETURN QUERY SELECT v_id, false;
    RETURN;
  END IF;

  RETURN QUERY SELECT v_id, true;
END;
$$;


--
-- Name: FUNCTION "f_criar_recebivel_manual"("p_payload" "jsonb", "p_idempotency_key" "text"); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."f_criar_recebivel_manual"("p_payload" "jsonb", "p_idempotency_key" "text") IS 'TMS-FIN-SEC-02-A6: criacao manual de financeiro_receber via contrato idempotente. Unica porta permitida.';


--
-- Name: f_documentos_prestadores_para_metadata(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."f_documentos_prestadores_para_metadata"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_url text;
BEGIN
  IF NEW.prestador_id IS NULL OR NEW.url IS NULL THEN
    RETURN NEW;
  END IF;

  v_url := CASE
    WHEN NEW.url ~ '^https?://' THEN NEW.url
    WHEN split_part(NEW.url, '/', 1) IN ('documentos_prestadores', 'documentos_operacionais') THEN NEW.url
    ELSE 'documentos_prestadores/' || NEW.url
  END;

  INSERT INTO public.documentos_metadata
    (url, nome, tipo, modulo_origem, entidade_id, status_ia, data_inclusao)
  VALUES
    (v_url, NEW.tipo, NEW.tipo, 'prestadores', NEW.prestador_id, 'pendente', COALESCE(NEW.created_at, now()))
  ON CONFLICT (modulo_origem, entidade_id, url) DO NOTHING;

  RETURN NEW;
END;
$$;


--
-- Name: f_emitir_fatura("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."f_emitir_fatura"("p_fatura_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_fatura public.faturas%ROWTYPE;
  v_numero text;
  v_numero_cliente integer;
  v_receber_id uuid;
  v_vencimento date;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'USUARIO_NAO_AUTENTICADO');
  END IF;

  -- Lock transacional na fatura (impede emissão concorrente)
  SELECT * INTO v_fatura FROM public.faturas WHERE id = p_fatura_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'FATURA_NAO_ENCONTRADA');
  END IF;

  IF v_fatura.status = 'cancelada' THEN
    RETURN jsonb_build_object('success', false, 'error', 'FATURA_CANCELADA');
  END IF;
  IF v_fatura.status = 'emitida' THEN
    RETURN jsonb_build_object('success', false, 'error', 'FATURA_JA_EMITIDA');
  END IF;

  -- TMS-FAT-URG-04 — SOMENTE fatura APROVADA pode ser emitida.
  -- Bloqueia rascunho -> emitida e aguardando_aprovacao -> emitida.
  IF v_fatura.status <> 'aprovada' THEN
    RETURN jsonb_build_object('success', false, 'error', 'FATURA_NAO_APROVADA');
  END IF;

  -- Cliente é obrigatório para gerar o Nº Cliente
  IF v_fatura.cliente_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'FATURA_SEM_CLIENTE');
  END IF;

  -- Deve haver itens
  IF NOT EXISTS (SELECT 1 FROM public.fatura_itens WHERE fatura_id = p_fatura_id AND status = 'ativo') THEN
    RETURN jsonb_build_object('success', false, 'error', 'FATURA_SEM_ITENS');
  END IF;

  -- Nº Conexão (sequencial global por ano — mecanismo existente)
  v_numero := public.f_gerar_numero_fatura(p_fatura_id);
  IF v_numero IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'FALHA_GERAR_NUMERO');
  END IF;

  -- Nº Cliente (sequencial histórico por tenant+cliente, atômico via UPSERT)
  INSERT INTO public.fatura_contadores_cliente (tenant_id, cliente_id, ultimo_numero, updated_at)
  VALUES (v_fatura.tenant_id, v_fatura.cliente_id, 1, now())
  ON CONFLICT (tenant_id, cliente_id)
  DO UPDATE SET ultimo_numero = public.fatura_contadores_cliente.ultimo_numero + 1,
                updated_at = now()
  RETURNING ultimo_numero INTO v_numero_cliente;

  -- Vencimento sugerido: vencimento da fatura, senão emissão + 30 dias
  v_vencimento := COALESCE(v_fatura.vencimento, v_fatura.data_emissao + 30);

  -- Cria Conta a Receber (1 por fatura; UNIQUE parcial em fatura_id)
  INSERT INTO public.financeiro_receber (
    cliente_id, descricao, valor, vencimento, data_vencimento, data_emissao,
    status, cliente, cliente_nome, fatura, numero, os_vinculadas,
    valor_bruto, valor_liquido, fatura_id
  ) VALUES (
    v_fatura.cliente_id,
    'Fatura ' || v_numero,
    v_fatura.valor_total,
    v_vencimento,
    v_vencimento,
    CURRENT_DATE,
    'aberto',
    (SELECT COALESCE(c.nome_fantasia, c.razao_social, '') FROM public.clientes c WHERE c.id = v_fatura.cliente_id),
    (SELECT COALESCE(c.nome_fantasia, c.razao_social, '') FROM public.clientes c WHERE c.id = v_fatura.cliente_id),
    v_numero,
    v_numero,
    NULL,
    v_fatura.valor_bruto,
    v_fatura.valor_total,
    p_fatura_id
  )
  RETURNING id INTO v_receber_id;

  -- Marca fatura emitida (conta_receber_id preenchido → passa pela guarda)
  UPDATE public.faturas
  SET status = 'emitida',
      numero = v_numero,
      numero_cliente = v_numero_cliente,
      conta_receber_id = v_receber_id,
      vencimento = v_vencimento,
      atualizado_por = auth.uid(),
      atualizado_em = now()
  WHERE id = p_fatura_id;

  RETURN jsonb_build_object(
    'success', true,
    'fatura_id', p_fatura_id,
    'numero', v_numero,
    'numero_cliente', v_numero_cliente,
    'conta_receber_id', v_receber_id,
    'valor_total', v_fatura.valor_total,
    'vencimento', v_vencimento
  );
END;
$$;


--
-- Name: f_enviar_mensagem_torre("uuid", "text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."f_enviar_mensagem_torre"("p_alocacao_id" "uuid", "p_mensagem" "text", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_authenticated_uid uuid;
  v_prestador_id uuid;
  v_alocacao record;
  v_mensagem_id uuid;
  v_existente uuid;
BEGIN
  v_authenticated_uid := auth.uid();
  IF v_authenticated_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'USUARIO_NAO_AUTENTICADO');
  END IF;

  -- Idempotência: mesma chave retorna a mensagem já criada
  IF p_idempotency_key IS NOT NULL AND btrim(p_idempotency_key) <> '' THEN
    SELECT id INTO v_existente FROM public.operacao_mensagens
    WHERE idempotency_key = p_idempotency_key AND sender_type = 'prestador'
    LIMIT 1;
    IF v_existente IS NOT NULL THEN
      RETURN jsonb_build_object('success', true, 'duplicada', true, 'mensagem_id', v_existente);
    END IF;
  END IF;

  -- Resolver prestador autenticado
  SELECT id INTO v_prestador_id
  FROM public.prestadores
  WHERE auth_user_id = v_authenticated_uid
    AND status = 'ativo'
    AND liberado_app = true;
  IF v_prestador_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'PRESTADOR_NAO_VINCULADO');
  END IF;

  -- Validar alocação pertence ao prestador
  SELECT id, ordem_servico_id, prestador_id, status
    INTO v_alocacao
  FROM public.alocacoes_escala
  WHERE id = p_alocacao_id;
  IF v_alocacao.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'ALOCACAO_NAO_ENCONTRADA');
  END IF;
  IF v_alocacao.prestador_id IS DISTINCT FROM v_prestador_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'ALOCACAO_OUTRO_PRESTADOR');
  END IF;
  IF v_alocacao.status IN ('cancelada', 'recusada') THEN
    RETURN jsonb_build_object('success', false, 'error', 'ALOCACAO_INATIVA');
  END IF;

  -- Validar mensagem
  IF p_mensagem IS NULL OR btrim(p_mensagem) = '' THEN
    RETURN jsonb_build_object('success', false, 'error', 'MENSAGEM_VAZIA');
  END IF;
  IF length(p_mensagem) > 2000 THEN
    RETURN jsonb_build_object('success', false, 'error', 'MENSAGEM_MUITO_LONGA');
  END IF;

  INSERT INTO public.operacao_mensagens (
    alocacao_id, os_id, prestador_id, sender_type, sender_user_id,
    mensagem, status, idempotency_key
  ) VALUES (
    p_alocacao_id,
    v_alocacao.ordem_servico_id,
    v_prestador_id,
    'prestador',
    v_authenticated_uid,
    btrim(p_mensagem),
    'enviada',
    NULLIF(p_idempotency_key, '')
  )
  RETURNING id INTO v_mensagem_id;

  RETURN jsonb_build_object('success', true, 'mensagem_id', v_mensagem_id, 'created_at', now());
END;
$$;


--
-- Name: FUNCTION "f_enviar_mensagem_torre"("p_alocacao_id" "uuid", "p_mensagem" "text", "p_idempotency_key" "text"); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."f_enviar_mensagem_torre"("p_alocacao_id" "uuid", "p_mensagem" "text", "p_idempotency_key" "text") IS 'A22 — App Prestador envia mensagem para a Torre. Resolve prestador via auth.uid(). Idempotente.';


--
-- Name: f_estornar_baixa_financeira("uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."f_estornar_baixa_financeira"("p_baixa_id" "uuid", "p_motivo_estorno" "text" DEFAULT NULL::"text") RETURNS TABLE("sucesso" boolean, "mensagem" "text", "saldo_restante" numeric, "status_titulo" "text")
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    v_baixa            RECORD;
    v_valor_original   NUMERIC(18,2);
    v_total_baixado    NUMERIC(18,2);
    v_saldo            NUMERIC(18,2);
    v_novo_status      TEXT;
BEGIN
    SELECT id, titulo_tabela, titulo_id, estornada
      INTO v_baixa
      FROM public.financeiro_baixas
     WHERE id = p_baixa_id
       FOR UPDATE;

    IF NOT FOUND THEN
        RETURN QUERY SELECT false, 'Baixa não encontrada.', NULL::NUMERIC, NULL::TEXT;
        RETURN;
    END IF;

    IF v_baixa.estornada THEN
        RETURN QUERY SELECT false, 'Baixa já estornada.', NULL::NUMERIC, NULL::TEXT;
        RETURN;
    END IF;

    IF v_baixa.titulo_tabela NOT IN ('financeiro_pagar','financeiro_receber') THEN
        RETURN QUERY SELECT false, 'Tabela de título não suportada.', NULL::NUMERIC, NULL::TEXT;
        RETURN;
    END IF;

    -- Marca como estornada — nunca apaga o registro
    UPDATE public.financeiro_baixas
       SET estornada      = true,
           data_estorno   = now(),
           motivo_estorno = p_motivo_estorno
     WHERE id = p_baixa_id;

    -- Recalcula total baixado (excluindo a baixa estornada) e saldo
    SELECT COALESCE(SUM(valor_baixado), 0)
      INTO v_total_baixado
      FROM public.financeiro_baixas
     WHERE titulo_tabela = v_baixa.titulo_tabela
       AND titulo_id = v_baixa.titulo_id
       AND NOT estornada;

    IF v_baixa.titulo_tabela = 'financeiro_pagar' THEN
        SELECT valor
          INTO v_valor_original
          FROM public.financeiro_pagar
         WHERE id = v_baixa.titulo_id;
    ELSE
        SELECT valor
          INTO v_valor_original
          FROM public.financeiro_receber
         WHERE id = v_baixa.titulo_id;
    END IF;

    IF NOT FOUND THEN
        RETURN QUERY SELECT false, 'Título de origem não encontrado.', NULL::NUMERIC, NULL::TEXT;
        RETURN;
    END IF;

    v_saldo := v_valor_original - v_total_baixado;
    IF v_saldo < 0 THEN
        v_saldo := 0;
    END IF;

    IF v_total_baixado <= 0 THEN
        -- Nenhuma baixa válida restante → título volta a aberto
        v_novo_status := 'aberto';
        IF v_baixa.titulo_tabela = 'financeiro_pagar' THEN
            UPDATE public.financeiro_pagar
               SET status            = v_novo_status,
                   data_pagamento    = NULL,
                   data_efetiva_pgto = NULL
             WHERE id = v_baixa.titulo_id;
        ELSE
            UPDATE public.financeiro_receber
               SET status         = v_novo_status,
                   data_pagamento = NULL
             WHERE id = v_baixa.titulo_id;
        END IF;
    ELSIF v_saldo > 0 THEN
        v_novo_status := 'parcial';
        IF v_baixa.titulo_tabela = 'financeiro_pagar' THEN
            UPDATE public.financeiro_pagar SET status = v_novo_status WHERE id = v_baixa.titulo_id;
        ELSE
            UPDATE public.financeiro_receber SET status = v_novo_status WHERE id = v_baixa.titulo_id;
        END IF;
    ELSE
        v_novo_status := 'pago';
        IF v_baixa.titulo_tabela = 'financeiro_pagar' THEN
            UPDATE public.financeiro_pagar SET status = v_novo_status WHERE id = v_baixa.titulo_id;
        ELSE
            UPDATE public.financeiro_receber SET status = v_novo_status WHERE id = v_baixa.titulo_id;
        END IF;
    END IF;

    RETURN QUERY SELECT true, 'Baixa estornada. Registro preservado.', v_saldo, v_novo_status;
END;
$$;


--
-- Name: f_estornar_pagamento_prestador("uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."f_estornar_pagamento_prestador"("p_pagamento_id" "uuid", "p_motivo" "text") RETURNS TABLE("sucesso" boolean, "mensagem" "text", "pagamento_id" "uuid", "baixa_id" "uuid", "status_pagamento" "text", "fp_status" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_pag       RECORD;
    v_tenant    uuid;
    v_titulo    RECORD;
    v_baixa     RECORD;
    v_nbaixas   integer;
    v_res       RECORD;
    v_obs       text;
BEGIN
    IF auth.uid() IS NULL THEN
        RETURN QUERY SELECT false, 'USUARIO_NAO_AUTENTICADO', p_pagamento_id, NULL::uuid, NULL::text, NULL::text;
        RETURN;
    END IF;

    IF p_motivo IS NULL OR btrim(p_motivo) = '' THEN
        RETURN QUERY SELECT false, 'MOTIVO_OBRIGATORIO', p_pagamento_id, NULL::uuid, NULL::text, NULL::text;
        RETURN;
    END IF;

    SELECT tu.tenant_id INTO v_tenant
      FROM public.tenant_usuarios tu
     WHERE tu.user_id = auth.uid() AND tu.status = 'ativo'
     LIMIT 1;

    IF v_tenant IS NULL OR NOT EXISTS (
        SELECT 1 FROM public.tenant_usuarios tu
         WHERE tu.user_id = auth.uid() AND tu.status = 'ativo'
           AND tu.papel IN ('super_admin','admin_tenant','financeiro')) THEN
        RETURN QUERY SELECT false, 'NAO_AUTORIZADO', p_pagamento_id, NULL::uuid, NULL::text, NULL::text;
        RETURN;
    END IF;

    SELECT p.* INTO v_pag
      FROM public.pagamentos_prestadores p
     WHERE p.id = p_pagamento_id
       FOR UPDATE;

    IF NOT FOUND THEN
        RETURN QUERY SELECT false, 'PAGAMENTO_NAO_ENCONTRADO', p_pagamento_id, NULL::uuid, NULL::text, NULL::text;
        RETURN;
    END IF;

    IF v_pag.os_id IS NOT NULL
       AND public.f_pp_tenant_id(v_pag.os_id) IS DISTINCT FROM v_tenant THEN
        RETURN QUERY SELECT false, 'NAO_AUTORIZADO_TENANT', v_pag.id, NULL::uuid, v_pag.status_pagamento, NULL::text;
        RETURN;
    END IF;

    IF v_pag.status_pagamento IS DISTINCT FROM 'pago' AND v_pag.status IS DISTINCT FROM 'pago' THEN
        RETURN QUERY SELECT false, 'PAGAMENTO_NAO_ESTA_PAGO', v_pag.id, NULL::uuid, v_pag.status_pagamento, NULL::text;
        RETURN;
    END IF;

    IF v_pag.os_id IS NULL THEN
        RETURN QUERY SELECT false, 'TITULO_FINANCEIRO_NAO_ENCONTRADO', v_pag.id, NULL::uuid, v_pag.status_pagamento, NULL::text;
        RETURN;
    END IF;

    SELECT fp.* INTO v_titulo
      FROM public.financeiro_pagar fp
     WHERE fp.os_id = v_pag.os_id::text
     ORDER BY fp.created_at
     LIMIT 1;

    IF NOT FOUND THEN
        RETURN QUERY SELECT false, 'TITULO_FINANCEIRO_NAO_ENCONTRADO', v_pag.id, NULL::uuid, v_pag.status_pagamento, NULL::text;
        RETURN;
    END IF;

    -- Somente INTEGRAL: exatamente 1 baixa ativa e ela deve quitar o titulo
    SELECT count(*) INTO v_nbaixas
      FROM public.financeiro_baixas b
     WHERE b.titulo_tabela = 'financeiro_pagar' AND b.titulo_id = v_titulo.id
       AND NOT COALESCE(b.estornada, false);

    IF v_nbaixas <> 1 THEN
        RETURN QUERY SELECT false, 'BLOCKED_PAGAMENTO_PARCIAL', v_pag.id, NULL::uuid, v_pag.status_pagamento, v_titulo.status;
        RETURN;
    END IF;

    SELECT b.* INTO v_baixa
      FROM public.financeiro_baixas b
     WHERE b.titulo_tabela = 'financeiro_pagar' AND b.titulo_id = v_titulo.id
       AND NOT COALESCE(b.estornada, false)
       FOR UPDATE;

    IF ROUND(COALESCE(v_baixa.valor_original,0)::numeric,2) <> ROUND(COALESCE(v_titulo.valor,0)::numeric,2)
       OR ROUND(COALESCE(v_baixa.saldo_restante,0)::numeric,2) <> 0 THEN
        RETURN QUERY SELECT false, 'BLOCKED_PAGAMENTO_PARCIAL', v_pag.id, v_baixa.id, v_pag.status_pagamento, v_titulo.status;
        RETURN;
    END IF;

    -- Reutiliza a RPC existente de estorno (nao reimplementar)
    SELECT r.sucesso, r.mensagem INTO v_res
      FROM public.f_estornar_baixa_financeira(v_baixa.id, p_motivo) r;

    IF NOT COALESCE(v_res.sucesso, false) THEN
        RETURN QUERY SELECT false, COALESCE(v_res.mensagem,'FALHA_ESTORNO'), v_pag.id, v_baixa.id, v_pag.status_pagamento, v_titulo.status;
        RETURN;
    END IF;

    v_obs := CASE WHEN v_pag.observacao IS NULL OR v_pag.observacao = ''
                  THEN '[estorno][' || to_char(now(),'YYYY-MM-DD HH24:MI') || '][' || left(auth.uid()::text,8) || '] ' || p_motivo
                  ELSE v_pag.observacao || E'\n[estorno][' || to_char(now(),'YYYY-MM-DD HH24:MI') || '][' || left(auth.uid()::text,8) || '] ' || p_motivo
             END;

    -- Sincroniza PP de volta a estado coerente (FP ja reaberto pela RPC de estorno)
    UPDATE public.pagamentos_prestadores
       SET status           = 'pendente',
           status_pagamento = 'pendente',
           data_pagamento   = NULL,
           observacao       = v_obs
     WHERE id = v_pag.id;

    RETURN QUERY SELECT true, 'ESTORNADO',
        v_pag.id, v_baixa.id, 'pendente'::text,
        (SELECT fp.status FROM public.financeiro_pagar fp WHERE fp.id = v_titulo.id);
END;
$$;


--
-- Name: FUNCTION "f_estornar_pagamento_prestador"("p_pagamento_id" "uuid", "p_motivo" "text"); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."f_estornar_pagamento_prestador"("p_pagamento_id" "uuid", "p_motivo" "text") IS 'TMS-FIN-PP-UX-02C1B: estorna pagamento INTEGRAL reutilizando f_estornar_baixa_financeira e reabrindo PP. Parcial bloqueado.';


--
-- Name: f_gerar_lote_pagamentos("uuid"[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."f_gerar_lote_pagamentos"("p_ids" "uuid"[]) RETURNS TABLE("lote_id" "uuid", "solicitados" integer, "incluidos" integer, "ja_em_lote" integer, "bloqueados" integer, "detalhes" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant uuid;
  v_papel text;
  v_ids uuid[];
  v_total int;
  v_aprovaveis int;
  v_ja int;
  v_lotes int;
  v_lote_existente uuid;
  v_bloqueados int;
  v_novo uuid;
  v_total_valor numeric;
  v_detalhes jsonb;
  v_papeis_autorizados text[] := ARRAY['super_admin','admin_tenant','financeiro'];
BEGIN
  v_ids := ARRAY(SELECT DISTINCT x FROM unnest(COALESCE(p_ids, ARRAY[]::uuid[])) AS x WHERE x IS NOT NULL);
  v_total := COALESCE(cardinality(v_ids), 0);

  IF v_uid IS NULL THEN
    RETURN QUERY SELECT NULL::uuid, v_total, 0, 0, v_total,
      jsonb_build_array(jsonb_build_object('resultado','BLOQUEADO','motivo','USUARIO_NAO_AUTENTICADO'));
    RETURN;
  END IF;

  SELECT tu.tenant_id, tu.papel INTO v_tenant, v_papel
    FROM public.tenant_usuarios tu WHERE tu.user_id = v_uid AND tu.status = 'ativo' LIMIT 1;
  IF v_tenant IS NULL THEN
    RETURN QUERY SELECT NULL::uuid, v_total, 0, 0, v_total,
      jsonb_build_array(jsonb_build_object('resultado','BLOQUEADO','motivo','USUARIO_SEM_TENANT_ATIVO'));
    RETURN;
  END IF;
  IF NOT (COALESCE(v_papel,'') = ANY(v_papeis_autorizados)) THEN
    RETURN QUERY SELECT NULL::uuid, v_total, 0, 0, v_total,
      jsonb_build_array(jsonb_build_object('resultado','BLOQUEADO','motivo','PAPEL_NAO_AUTORIZADO','papel',COALESCE(v_papel,'')));
    RETURN;
  END IF;
  IF v_total = 0 THEN
    RETURN QUERY SELECT NULL::uuid, 0, 0, 0, 0, '[]'::jsonb;
    RETURN;
  END IF;

  PERFORM 1 FROM public.pagamentos_prestadores WHERE id = ANY(v_ids) FOR UPDATE;

  DROP TABLE IF EXISTS tmp_lote_class;
  DROP TABLE IF EXISTS tmp_lote_missing;
  CREATE TEMP TABLE tmp_lote_class ON COMMIT DROP AS
  WITH base AS (
    SELECT p.id, p.lote_id AS lote_atual, p.prestador_id,
           p.origem_lancamento,
           COALESCE(p.valor_liquido,0) AS valor_liquido,
           p.status, p.status_pagamento, p.status_conferencia, p.status_aprovacao, p.elegivel_lote,
           p.is_teste, p.tipo_pagamento,
           public.f_pp_tenant_id(p.os_id) AS row_tenant,
           (SELECT o.status FROM public.ordens_servico o WHERE o.id=p.os_id) AS os_status,
           (SELECT a.status FROM public.alocacoes_escala a WHERE a.id=p.os_id) AS aloc_status,
           (COALESCE(btrim(pr.chave_pix),'')<>'' OR
            (COALESCE(btrim(pr.banco),'')<>'' AND COALESCE(btrim(pr.agencia),'')<>'' AND COALESCE(btrim(pr.conta),'')<>'')) AS destino_ok
      FROM public.pagamentos_prestadores p
      LEFT JOIN public.prestadores pr ON pr.id = p.prestador_id
     WHERE p.id = ANY(v_ids)
  )
  SELECT b.id, b.lote_atual, b.prestador_id, b.valor_liquido,
    CASE
      WHEN b.row_tenant IS NULL AND COALESCE(b.origem_lancamento,'') <> 'manual' THEN 'SEM_TENANT'
      WHEN b.row_tenant IS NOT NULL AND b.row_tenant <> v_tenant THEN 'CROSS_TENANT'
      WHEN COALESCE(b.os_status,'')='cancelada' OR COALESCE(b.aloc_status,'')='cancelada' THEN 'OPERACAO_CANCELADA'
      WHEN COALESCE(b.status_pagamento,'')='pago' OR COALESCE(b.status,'')='pago' THEN 'PAGO'
      WHEN COALESCE(b.status_pagamento,'')='cancelado' OR COALESCE(b.status_conferencia,'')='cancelado' OR COALESCE(b.status,'')='cancelado' THEN 'CANCELADO'
      WHEN b.is_teste IS TRUE THEN 'TESTE'
      WHEN b.prestador_id IS NULL THEN 'SEM_PRESTADOR'
      WHEN NOT b.destino_ok THEN 'DESTINO_INVALIDO'
      WHEN b.valor_liquido <= 0 THEN 'VALOR_INVALIDO'
      WHEN COALESCE(b.tipo_pagamento,'')='fechamento' THEN 'AGREGADO'
      WHEN b.lote_atual IS NOT NULL THEN 'JA_EM_LOTE'
      WHEN NOT (COALESCE(b.status_conferencia,'')='conferido' AND COALESCE(b.status_aprovacao,'')='aprovado' AND b.elegivel_lote IS TRUE) THEN 'NAO_ELEGIVEL'
      ELSE 'APROVAVEL'
    END AS resultado
  FROM base b;

  CREATE TEMP TABLE tmp_lote_missing ON COMMIT DROP AS
  SELECT x AS id, NULL::uuid AS lote_atual, 'NAO_ENCONTRADO'::text AS resultado
    FROM unnest(v_ids) x WHERE NOT EXISTS (SELECT 1 FROM tmp_lote_class c WHERE c.id = x);

  SELECT count(*)::int INTO v_aprovaveis FROM tmp_lote_class WHERE resultado='APROVAVEL';
  SELECT count(*)::int INTO v_ja FROM tmp_lote_class WHERE resultado='JA_EM_LOTE';
  SELECT count(DISTINCT lote_atual)::int INTO v_lotes FROM tmp_lote_class WHERE resultado='JA_EM_LOTE';
  SELECT lote_atual INTO v_lote_existente FROM tmp_lote_class WHERE resultado='JA_EM_LOTE' LIMIT 1;
  SELECT count(*)::int INTO v_bloqueados
    FROM (SELECT resultado FROM tmp_lote_class WHERE resultado NOT IN ('APROVAVEL','JA_EM_LOTE')
          UNION ALL SELECT resultado FROM tmp_lote_missing) z;

  v_detalhes := COALESCE((
    SELECT jsonb_agg(jsonb_build_object('id', id, 'resultado', resultado, 'motivo',
      CASE resultado
        WHEN 'SEM_TENANT' THEN 'Tenant do vinculo (os_id) nao resolvivel'
        WHEN 'CROSS_TENANT' THEN 'Registro pertence a outro tenant'
        WHEN 'OPERACAO_CANCELADA' THEN 'Operacao/OS vinculada cancelada'
        WHEN 'PAGO' THEN 'Pagamento ja efetuado'
        WHEN 'CANCELADO' THEN 'Pagamento cancelado'
        WHEN 'TESTE' THEN 'Registro de teste/HML'
        WHEN 'SEM_PRESTADOR' THEN 'Sem prestador vinculado'
        WHEN 'DESTINO_INVALIDO' THEN 'Prestador sem destino bancario valido (PIX ou conta)'
        WHEN 'VALOR_INVALIDO' THEN 'Valor liquido <= 0'
        WHEN 'AGREGADO' THEN 'Registro agregado (fechamento)'
        WHEN 'JA_EM_LOTE' THEN 'Ja pertence a um lote'
        WHEN 'NAO_ELEGIVEL' THEN 'Nao conferido/aprovado/elegivel'
        WHEN 'NAO_ENCONTRADO' THEN 'Registro nao encontrado'
        ELSE 'Erro desconhecido' END))
    FROM (SELECT id, resultado FROM tmp_lote_class UNION ALL SELECT id, resultado FROM tmp_lote_missing) d
  ), '[]'::jsonb);

  IF v_bloqueados > 0 THEN
    RETURN QUERY SELECT NULL::uuid, v_total, 0, v_ja, v_bloqueados, v_detalhes;
    RETURN;
  END IF;
  IF v_ja > 0 AND v_aprovaveis > 0 THEN
    RETURN QUERY SELECT NULL::uuid, v_total, 0, v_ja, v_total,
      jsonb_build_array(jsonb_build_object('resultado','BLOQUEADO','motivo','MISTURA_JA_EM_LOTE_E_SEM_LOTE'));
    RETURN;
  END IF;
  IF v_lotes > 1 THEN
    RETURN QUERY SELECT NULL::uuid, v_total, 0, v_ja, v_total,
      jsonb_build_array(jsonb_build_object('resultado','BLOQUEADO','motivo','LOTES_DIFERENTES'));
    RETURN;
  END IF;
  IF v_ja > 0 AND v_aprovaveis = 0 THEN
    RETURN QUERY SELECT v_lote_existente, v_total, 0, v_ja, 0, v_detalhes;
    RETURN;
  END IF;

  -- Cabecalho
  v_novo := gen_random_uuid();
  SELECT COALESCE(SUM(valor_liquido),0) INTO v_total_valor FROM tmp_lote_class WHERE resultado='APROVAVEL';

  INSERT INTO public.lotes_pagamento (id, tenant_id, status, quantidade_pagamentos, valor_total, criado_por)
  VALUES (v_novo, v_tenant, 'preparado', v_aprovaveis, v_total_valor, v_uid);

  -- Snapshots (dados do prestador congelados no momento da formacao)
  INSERT INTO public.lotes_pagamento_itens (
    lote_id, pagamento_prestador_id, prestador_id, valor, forma_destino,
    banco, agencia, conta, digito, tipo_conta, favorecido, documento_favorecido, chave_pix, tipo_chave_pix
  )
  SELECT v_novo, t.id, t.prestador_id, t.valor_liquido,
         CASE WHEN COALESCE(btrim(pr.chave_pix),'')<>'' THEN 'pix' ELSE 'conta' END,
         pr.banco, pr.agencia, pr.conta, pr.digito, pr.tipo_conta, pr.favorecido, pr.cpf_cnpj_favorecido, pr.chave_pix, pr.tipo_chave_pix
    FROM tmp_lote_class t
    JOIN public.prestadores pr ON pr.id = t.prestador_id
   WHERE t.resultado='APROVAVEL';

  -- Marca pagamentos
  UPDATE public.pagamentos_prestadores p
     SET lote_id = v_novo, status_pagamento = 'em_lote'
    FROM tmp_lote_class t
   WHERE p.id = t.id AND t.resultado='APROVAVEL'
     AND p.lote_id IS NULL
     AND COALESCE(p.status_pagamento,'') NOT IN ('pago','cancelado')
     AND COALESCE(p.status_conferencia,'') = 'conferido'
     AND COALESCE(p.status_aprovacao,'') = 'aprovado'
     AND p.elegivel_lote IS TRUE;

  RETURN QUERY SELECT v_novo, v_total, v_aprovaveis, 0, 0, v_detalhes;
END;
$$;


--
-- Name: FUNCTION "f_gerar_lote_pagamentos"("p_ids" "uuid"[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."f_gerar_lote_pagamentos"("p_ids" "uuid"[]) IS 'TMS-FIN-PROG-05D.7B.1: forma lote logico (lote_id + status_pagamento=em_lote) a partir de pagamentos conferidos/aprovados/elegiveis do proprio tenant. Atomica, idempotente, tenant-safe. NAO cria tabela, nao paga, nao baixa.';


--
-- Name: f_gerar_numero_fatura("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."f_gerar_numero_fatura"("p_fatura_id" "uuid" DEFAULT NULL::"uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_ano integer;
  v_seq_name text;
  v_numero text;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN NULL;
  END IF;

  v_ano := EXTRACT(YEAR FROM now())::integer;
  v_seq_name := 'seq_fatura_' || v_ano::text;

  -- Cria a sequência do ano se não existir (aditivo, on-demand)
  IF NOT EXISTS (
    SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public' AND c.relname = v_seq_name AND c.relkind = 'S'
  ) THEN
    EXECUTE format('CREATE SEQUENCE IF NOT EXISTS public.%I START 1', v_seq_name);
  END IF;

  -- nextval é atômico e serializa chamadas concorrentes → impede duplicidade
  EXECUTE format('SELECT nextval(''public.%I'')', v_seq_name) INTO v_numero;

  RETURN format('FAT-%s-%s', v_ano, LPAD(v_numero, 6, '0'));
END;
$$;


--
-- Name: f_km_evidencias_operacao("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."f_km_evidencias_operacao"("p_os_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid;
  v_os_numero text;
  v_alocacoes jsonb;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'USUARIO_NAO_AUTENTICADO');
  END IF;

  -- Guard via tenant_usuarios (usuário TMS ativo). Sem has_role/profiles/user_roles.
  IF NOT EXISTS (
    SELECT 1 FROM public.tenant_usuarios tu
    WHERE tu.user_id = v_uid AND tu.status = 'ativo'
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'SEM_PERMISSAO');
  END IF;

  IF p_os_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'OS_INVALIDA');
  END IF;

  SELECT numero INTO v_os_numero
  FROM public.ordens_servico
  WHERE id = p_os_id;

  -- OS → alocação (alocacoes_escala.ordem_servico_id). Cada alocação traz:
  --   km (operation_km por operation_id = alocação), tempos e timeline
  --   (operation_timeline_events.operation_id é TEXT → cast a.id::TEXT).
  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'alocacao_id', a.id,
        'status', a.status,
        'finalizada', a.finalizada,
        'placa', a.placa,
        'tipo_veiculo', a.tipo_veiculo,
        'tempos', jsonb_build_object(
          'data_escala', a.data_escala,
          'data_aceite', a.data_aceite,
          'horario_inicio_real', a.horario_inicio_real,
          'horario_fim_real', a.horario_fim_real,
          'data_finalizacao', a.data_finalizacao,
          'tempo_total_minutos', a.tempo_total_minutos,
          'updated_at', a.updated_at
        ),
        'km', (
          SELECT jsonb_build_object(
            'km_inicial', km.km_inicial,
            'km_final', km.km_final,
            'km_rodado', COALESCE(km.km_rodado,
              CASE WHEN km.km_inicial IS NOT NULL AND km.km_final IS NOT NULL
                   THEN km.km_final - km.km_inicial END),
            'km_adicional', km.km_adicional,
            'valor_adicional_estimado', km.valor_adicional_estimado,
            'foto_km_inicial_url', km.foto_km_inicial_url,
            'foto_km_final_url', km.foto_km_final_url,
            'updated_at', km.updated_at
          )
          FROM public.operation_km km
          WHERE km.operation_id = a.id
          LIMIT 1
        ),
        'timeline', COALESCE(
          (
            SELECT jsonb_agg(
              jsonb_build_object(
                'type', t.type,
                'title', t.title,
                'event_time', t.event_time,
                'metadata', t.metadata
              ) ORDER BY t.event_time ASC NULLS LAST, t.created_at ASC
            )
            FROM public.operation_timeline_events t
            WHERE t.operation_id = a.id::TEXT
          ),
          '[]'::jsonb
        )
      ) ORDER BY a.data_escala ASC, a.created_at ASC
    ),
    '[]'::jsonb
  ) INTO v_alocacoes
  FROM public.alocacoes_escala a
  WHERE a.ordem_servico_id = p_os_id;

  RETURN jsonb_build_object(
    'success', true,
    'os_id', p_os_id,
    'os_numero', v_os_numero,
    'total_alocacoes', COALESCE(jsonb_array_length(v_alocacoes), 0),
    'alocacoes', v_alocacoes
  );
END;
$$;


--
-- Name: FUNCTION "f_km_evidencias_operacao"("p_os_id" "uuid"); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."f_km_evidencias_operacao"("p_os_id" "uuid") IS 'A29-D — Evidências de KM (inicial/final/foto/percorrido) + horários/tempos de uma OS, agregadas pelas alocações. Guard via tenant_usuarios; OS→alocação via alocacoes_escala.ordem_servico_id; cast para operation_timeline_events.operation_id (TEXT). Somente leitura. Grants: authenticated + service_role.';


--
-- Name: f_log_tabela_alteracao(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."f_log_tabela_alteracao"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$ BEGIN NEW.versao := COALESCE(OLD.versao, 0) + 1; NEW.updated_at := NOW(); RETURN NEW; END; $$;


--
-- Name: f_marcar_mensagens_lidas_app("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."f_marcar_mensagens_lidas_app"("p_alocacao_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_authenticated_uid uuid;
  v_prestador_id uuid;
  v_count integer;
BEGIN
  v_authenticated_uid := auth.uid();
  IF v_authenticated_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'USUARIO_NAO_AUTENTICADO');
  END IF;

  SELECT id INTO v_prestador_id FROM public.prestadores
  WHERE auth_user_id = v_authenticated_uid;
  IF v_prestador_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'PRESTADOR_NAO_VINCULADO');
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.alocacoes_escala
    WHERE id = p_alocacao_id AND prestador_id = v_prestador_id
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'ALOCACAO_OUTRO_PRESTADOR');
  END IF;

  UPDATE public.operacao_mensagens
  SET status = 'lida', read_at = now()
  WHERE alocacao_id = p_alocacao_id
    AND sender_type = 'torre'
    AND status = 'enviada';

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN jsonb_build_object('success', true, 'atualizadas', v_count);
END;
$$;


--
-- Name: FUNCTION "f_marcar_mensagens_lidas_app"("p_alocacao_id" "uuid"); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."f_marcar_mensagens_lidas_app"("p_alocacao_id" "uuid") IS 'A22 — App marca como lidas as mensagens da Torre da operação.';


--
-- Name: f_marcar_mensagens_lidas_torre("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."f_marcar_mensagens_lidas_torre"("p_alocacao_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_authenticated_uid uuid;
  v_count integer;
BEGIN
  v_authenticated_uid := auth.uid();
  IF v_authenticated_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'USUARIO_NAO_AUTENTICADO');
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.tenant_usuarios WHERE user_id = v_authenticated_uid) THEN
    RETURN jsonb_build_object('success', false, 'error', 'USUARIO_NAO_AUTORIZADO_TORRE');
  END IF;

  UPDATE public.operacao_mensagens
  SET status = 'lida', read_at = now()
  WHERE alocacao_id = p_alocacao_id
    AND sender_type = 'prestador'
    AND status = 'enviada';

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN jsonb_build_object('success', true, 'atualizadas', v_count);
END;
$$;


