--
-- Name: f_pod_referencia_remota("text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."f_pod_referencia_remota"("p_valor" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT p_valor IS NOT NULL
     AND btrim(p_valor) <> ''
     AND p_valor NOT LIKE 'file://%'
     AND p_valor NOT LIKE 'data:%'
     AND left(btrim(p_valor), 1) <> '/'
     AND p_valor !~ '^[A-Za-z]:[\\/]'
$$;


