--
-- Name: f_recalcular_totais_fatura(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."f_recalcular_totais_fatura"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_fatura_id uuid;
BEGIN
  v_fatura_id := NEW.fatura_id;
  IF TG_OP = 'DELETE' THEN
    v_fatura_id := OLD.fatura_id;
  END IF;

  UPDATE public.faturas f
  SET
    valor_bruto = COALESCE((
      SELECT SUM(i.valor_base) FROM public.fatura_itens i
      WHERE i.fatura_id = v_fatura_id AND i.status = 'ativo'
    ), 0),
    valor_total = COALESCE((
      SELECT SUM(i.valor_total) FROM public.fatura_itens i
      WHERE i.fatura_id = v_fatura_id AND i.status = 'ativo'
    ), 0),
    descontos = COALESCE((
      SELECT SUM(i.valor_descontos) FROM public.fatura_itens i
      WHERE i.fatura_id = v_fatura_id AND i.status = 'ativo'
    ), 0),
    atualizado_em = now()
  WHERE f.id = v_fatura_id;

  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: f_registrar_baixa_financeira("text", "uuid", numeric, "date", "text", "text", "uuid", "text", "text", "uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."f_registrar_baixa_financeira"("p_titulo_tabela" "text", "p_titulo_id" "uuid", "p_valor_baixado" numeric, "p_data_baixa" "date" DEFAULT CURRENT_DATE, "p_forma_pagamento" "text" DEFAULT NULL::"text", "p_conta_financeira" "text" DEFAULT NULL::"text", "p_conta_financeira_id" "uuid" DEFAULT NULL::"uuid", "p_referencia_bancaria" "text" DEFAULT NULL::"text", "p_observacao" "text" DEFAULT NULL::"text", "p_usuario_id" "uuid" DEFAULT NULL::"uuid", "p_usuario_nome" "text" DEFAULT NULL::"text") RETURNS TABLE("sucesso" boolean, "mensagem" "text", "baixa_id" "uuid", "saldo_restante" numeric, "status_titulo" "text")
    LANGUAGE "plpgsql"
    AS $_$
DECLARE
    v_valor_original   NUMERIC(18,2);
    v_status_atual     TEXT;
    v_total_baixado    NUMERIC(18,2);
    v_saldo            NUMERIC(18,2);
    v_novo_saldo       NUMERIC(18,2);
    v_novo_status      TEXT;
    v_baixa_id         UUID;
    v_linha_historico  TEXT;
BEGIN
    IF p_valor_baixado IS NULL OR p_valor_baixado <= 0 THEN
        RETURN QUERY SELECT false, 'Valor da baixa deve ser maior que zero.', NULL::UUID, NULL::NUMERIC, NULL::TEXT;
        RETURN;
    END IF;

    IF p_titulo_tabela = 'financeiro_pagar' THEN
        SELECT valor, status INTO v_valor_original, v_status_atual
          FROM public.financeiro_pagar WHERE id = p_titulo_id FOR UPDATE;
    ELSIF p_titulo_tabela = 'financeiro_receber' THEN
        SELECT valor, status INTO v_valor_original, v_status_atual
          FROM public.financeiro_receber WHERE id = p_titulo_id FOR UPDATE;
    ELSE
        RETURN QUERY SELECT false, 'Tabela de título não suportada.', NULL::UUID, NULL::NUMERIC, NULL::TEXT;
        RETURN;
    END IF;

    IF NOT FOUND THEN
        RETURN QUERY SELECT false, 'Título não encontrado.', NULL::UUID, NULL::NUMERIC, NULL::TEXT;
        RETURN;
    END IF;

    IF v_status_atual IN ('cancelado','cancelada') THEN
        RETURN QUERY SELECT false, 'Não é permitido baixar título cancelado.', NULL::UUID, NULL::NUMERIC, NULL::TEXT;
        RETURN;
    END IF;

    IF v_status_atual IN ('pago','paga') THEN
        RETURN QUERY SELECT false, 'Título já quitado. Não é permitida nova baixa.', NULL::UUID, NULL::NUMERIC, NULL::TEXT;
        RETURN;
    END IF;

    SELECT COALESCE(SUM(valor_baixado), 0) INTO v_total_baixado
      FROM public.financeiro_baixas
     WHERE titulo_tabela = p_titulo_tabela AND titulo_id = p_titulo_id AND NOT estornada;

    v_saldo := v_valor_original - v_total_baixado;

    IF v_saldo <= 0 THEN
        RETURN QUERY SELECT false, 'Título já quitado. Não é permitida nova baixa.', NULL::UUID, NULL::NUMERIC, NULL::TEXT;
        RETURN;
    END IF;

    IF p_valor_baixado > v_saldo THEN
        RETURN QUERY SELECT false,
            'Valor da baixa excede o saldo restante (' || v_saldo || ').',
            NULL::UUID, NULL::NUMERIC, NULL::TEXT;
        RETURN;
    END IF;

    v_novo_saldo := v_saldo - p_valor_baixado;

    IF v_novo_saldo < 0 THEN
        RETURN QUERY SELECT false, 'Saldo não pode ficar negativo.', NULL::UUID, NULL::NUMERIC, NULL::TEXT;
        RETURN;
    END IF;

    IF v_novo_saldo > 0 THEN
        v_novo_status := 'parcial';
    ELSE
        v_novo_status := 'pago';
    END IF;

    INSERT INTO public.financeiro_baixas (
        titulo_tabela, titulo_id, valor_original, valor_baixado, saldo_restante,
        data_baixa, forma_pagamento, conta_financeira, conta_financeira_id,
        referencia_bancaria, observacao, usuario_id, usuario_nome
    ) VALUES (
        p_titulo_tabela, p_titulo_id, v_valor_original, p_valor_baixado, v_novo_saldo,
        p_data_baixa, p_forma_pagamento, p_conta_financeira, p_conta_financeira_id,
        p_referencia_bancaria, p_observacao, p_usuario_id, p_usuario_nome
    ) RETURNING id INTO v_baixa_id;

    v_linha_historico := 'Baixa R$ ' || p_valor_baixado || ' em ' || p_data_baixa
                         || '. Saldo restante: R$ ' || v_novo_saldo || '.';

    IF p_titulo_tabela = 'financeiro_pagar' THEN
        UPDATE public.financeiro_pagar
           SET status            = v_novo_status,
               data_pagamento    = p_data_baixa,
               data_efetiva_pgto = p_data_baixa,
               conta_pagadora    = COALESCE(p_conta_financeira, conta_pagadora),
               observacoes       = CASE
                                     WHEN observacoes IS NULL OR observacoes = '' THEN v_linha_historico
                                     ELSE observacoes || E'\n' || v_linha_historico
                                   END
         WHERE id = p_titulo_id;
    ELSE
        UPDATE public.financeiro_receber
           SET status            = v_novo_status,
               data_pagamento    = p_data_baixa,
               conta_entrada     = COALESCE(p_conta_financeira, conta_entrada),
               observacoes       = CASE
                                     WHEN observacoes IS NULL OR observacoes = '' THEN v_linha_historico
                                     ELSE observacoes || E'\n' || v_linha_historico
                                   END
         WHERE id = p_titulo_id;
    END IF;

    RETURN QUERY SELECT true, 'Baixa registrada com sucesso.', v_baixa_id, v_novo_saldo, v_novo_status;
END;
$_$;


--
-- Name: f_registrar_notificacao_app("uuid", "text", "text", "text", "uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."f_registrar_notificacao_app"("p_prestador_id" "uuid", "p_titulo" "text", "p_mensagem" "text", "p_tipo" "text" DEFAULT 'operacao'::"text", "p_origem_id" "uuid" DEFAULT NULL::"uuid", "p_origem_tipo" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_notificacao_id UUID;
BEGIN
  INSERT INTO public.portal_notificacoes (
    prestador_id, titulo, mensagem, tipo, origem_id, origem_tipo, lida, created_at
  ) VALUES (
    p_prestador_id, p_titulo, p_mensagem, p_tipo, p_origem_id, p_origem_tipo, false, NOW()
  ) RETURNING id INTO v_notificacao_id;

  RETURN v_notificacao_id;
END;
$$;


--
-- Name: FUNCTION "f_registrar_notificacao_app"("p_prestador_id" "uuid", "p_titulo" "text", "p_mensagem" "text", "p_tipo" "text", "p_origem_id" "uuid", "p_origem_tipo" "text"); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."f_registrar_notificacao_app"("p_prestador_id" "uuid", "p_titulo" "text", "p_mensagem" "text", "p_tipo" "text", "p_origem_id" "uuid", "p_origem_tipo" "text") IS 'M111 — Registra notificação persistente para o App Motorista. Retorna ID da notificação.';


--
-- Name: f_registrar_oportunidade_historico("uuid", "text", "text", "jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."f_registrar_oportunidade_historico"("p_prestador_id" "uuid", "p_oportunidade_id" "text", "p_acao" "text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    IF p_acao NOT IN ('visualizou', 'ignorado', 'aceite', 'recusa') THEN
        RETURN jsonb_build_object('success', false, 'error', 'ACAO_INVALIDA');
    END IF;

    INSERT INTO public.prestador_oportunidade_historico (
        prestador_id, oportunidade_id, acao, metadata, auth_user_id
    ) VALUES (
        p_prestador_id, p_oportunidade_id, p_acao,
        COALESCE(p_metadata, '{}'::jsonb), auth.uid()
    );

    RETURN jsonb_build_object('success', true);
EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$;


--
-- Name: f_regularizar_fatura_legada("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."f_regularizar_fatura_legada"("p_fatura_id" "uuid", "p_ar_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_fatura public.faturas%ROWTYPE;
  v_tenant uuid;
  v_numero text;
  v_numero_cliente integer;
  v_receber_id uuid;
  v_ar public.financeiro_receber%ROWTYPE;
  v_vencimento date;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'USUARIO_NAO_AUTENTICADO');
  END IF;

  SELECT tenant_id INTO v_tenant FROM public.tenant_usuarios WHERE user_id = auth.uid() LIMIT 1;
  IF v_tenant IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'USUARIO_SEM_TENANT');
  END IF;

  SELECT * INTO v_fatura FROM public.faturas WHERE id = p_fatura_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'FATURA_NAO_ENCONTRADA');
  END IF;
  IF v_fatura.tenant_id <> v_tenant THEN
    RETURN jsonb_build_object('success', false, 'error', 'TENANT_DIVERGENTE');
  END IF;
  IF v_fatura.cliente_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'FATURA_SEM_CLIENTE');
  END IF;
  IF v_fatura.status = 'cancelada' THEN
    RETURN jsonb_build_object('success', false, 'error', 'FATURA_CANCELADA');
  END IF;

  -- TMS-FAT-URG-05B — SOMENTE fatura JÁ 'emitida' (regularização de AR legado).
  -- Bloqueia rascunho / aguardando_aprovacao / aprovada: esta RPC NÃO é emissão.
  IF v_fatura.status <> 'emitida' THEN
    RETURN jsonb_build_object('success', false, 'error', 'REGULARIZAR_SO_FATURA_EMITIDA');
  END IF;

  -- Idempotência: já regularizada (número + AR) → não consome nada.
  IF v_fatura.numero IS NOT NULL AND v_fatura.conta_receber_id IS NOT NULL THEN
    RETURN jsonb_build_object('success', true, 'already', true,
      'fatura_id', v_fatura.id, 'numero', v_fatura.numero,
      'numero_cliente', v_fatura.numero_cliente,
      'conta_receber_id', v_fatura.conta_receber_id);
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.fatura_itens WHERE fatura_id = p_fatura_id AND status = 'ativo') THEN
    RETURN jsonb_build_object('success', false, 'error', 'FATURA_SEM_ITENS');
  END IF;

  -- Nº Conexão (somente se a fatura legada ainda não tem número)
  v_numero := COALESCE(v_fatura.numero, public.f_gerar_numero_fatura(p_fatura_id));
  IF v_numero IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'FALHA_GERAR_NUMERO');
  END IF;

  IF p_ar_id IS NOT NULL THEN
    SELECT * INTO v_ar FROM public.financeiro_receber WHERE id = p_ar_id FOR UPDATE;
    IF NOT FOUND THEN
      RETURN jsonb_build_object('success', false, 'error', 'AR_NAO_ENCONTRADO');
    END IF;
    IF v_ar.fatura_id IS NOT NULL AND v_ar.fatura_id <> p_fatura_id THEN
      RETURN jsonb_build_object('success', false, 'error', 'AR_JA_VINCULADO_OUTRA_FATURA');
    END IF;
    IF v_ar.cliente_id IS DISTINCT FROM v_fatura.cliente_id THEN
      RETURN jsonb_build_object('success', false, 'error', 'AR_CLIENTE_DIVERGENTE');
    END IF;
    IF ABS(COALESCE(v_ar.valor, 0) - COALESCE(v_fatura.valor_total, 0)) > 0.005 THEN
      RETURN jsonb_build_object('success', false, 'error', 'AR_VALOR_DIVERGENTE');
    END IF;
    UPDATE public.financeiro_receber
      SET fatura_id = p_fatura_id
      WHERE id = p_ar_id AND fatura_id IS DISTINCT FROM p_fatura_id;
    v_receber_id := p_ar_id;
  ELSE
    IF EXISTS (SELECT 1 FROM public.financeiro_receber WHERE fatura_id = p_fatura_id) THEN
      RETURN jsonb_build_object('success', false, 'error', 'AR_JA_EXISTE_PARA_FATURA');
    END IF;
    v_vencimento := COALESCE(v_fatura.vencimento, v_fatura.data_emissao + 30);
    INSERT INTO public.financeiro_receber (
      cliente_id, descricao, valor, vencimento, data_vencimento, data_emissao,
      status, cliente, cliente_nome, fatura, numero, os_vinculadas,
      valor_bruto, valor_liquido, fatura_id
    ) VALUES (
      v_fatura.cliente_id,
      'Fatura ' || v_numero || ' (regularizada)',
      v_fatura.valor_total,
      v_vencimento, v_vencimento, v_fatura.data_emissao,
      'aberto',
      (SELECT COALESCE(c.nome_fantasia, c.razao_social, '') FROM public.clientes c WHERE c.id = v_fatura.cliente_id),
      (SELECT COALESCE(c.nome_fantasia, c.razao_social, '') FROM public.clientes c WHERE c.id = v_fatura.cliente_id),
      v_numero, v_numero, NULL,
      v_fatura.valor_bruto, v_fatura.valor_total, p_fatura_id
    ) RETURNING id INTO v_receber_id;
  END IF;

  INSERT INTO public.fatura_contadores_cliente (tenant_id, cliente_id, ultimo_numero, updated_at)
  VALUES (v_fatura.tenant_id, v_fatura.cliente_id, 1, now())
  ON CONFLICT (tenant_id, cliente_id)
  DO UPDATE SET ultimo_numero = public.fatura_contadores_cliente.ultimo_numero + 1, updated_at = now()
  RETURNING ultimo_numero INTO v_numero_cliente;

  -- Mantém 'emitida' (já era); preenche número/AR que faltavam no legado.
  UPDATE public.faturas
    SET status = 'emitida',
        numero = v_numero,
        numero_cliente = COALESCE(v_fatura.numero_cliente, v_numero_cliente),
        conta_receber_id = v_receber_id,
        atualizado_em = now()
    WHERE id = p_fatura_id;

  RETURN jsonb_build_object('success', true,
    'fatura_id', p_fatura_id,
    'numero', v_numero,
    'numero_cliente', COALESCE(v_fatura.numero_cliente, v_numero_cliente),
    'conta_receber_id', v_receber_id);
END;
$$;


--
-- Name: FUNCTION "f_regularizar_fatura_legada"("p_fatura_id" "uuid", "p_ar_id" "uuid"); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."f_regularizar_fatura_legada"("p_fatura_id" "uuid", "p_ar_id" "uuid") IS 'TMS-FAT-URG-05B — saneamento de LEGADO (fatura JA emitida sem AR). NAO emite rascunho/aprovada. Restrito a service_role.';


--
-- Name: f_reprocessar_pedido_portal("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."f_reprocessar_pedido_portal"("p_pedido_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_pedido RECORD;
  v_os_count INTEGER;
BEGIN
  -- Buscar pedido
  SELECT * INTO v_pedido FROM public.portal_pedidos WHERE id = p_pedido_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('sucesso', false, 'erro', 'Pedido não encontrado');
  END IF;

  -- Verificar se já tem OS válida
  IF v_pedido.os_vinculada_id IS NOT NULL THEN
    SELECT COUNT(*) INTO v_os_count FROM public.ordens_servico WHERE id = v_pedido.os_vinculada_id;
    IF v_os_count > 0 THEN
      RETURN jsonb_build_object('sucesso', true, 'os_id', v_pedido.os_vinculada_id, 'mensagem', 'Pedido já possui OS vinculada');
    END IF;
  END IF;

  -- Atualizar tentativas
  UPDATE public.portal_pedidos SET
    tentativas_processamento = COALESCE(tentativas_processamento, 0) + 1,
    ultima_tentativa_em = NOW(),
    status = 'enviado'
  WHERE id = p_pedido_id;

  RETURN jsonb_build_object('sucesso', true, 'mensagem', 'Pedido reenviado para processamento. Tentativa #' || (v_pedido.tentativas_processamento + 1));
END;
$$;


--
-- Name: FUNCTION "f_reprocessar_pedido_portal"("p_pedido_id" "uuid"); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."f_reprocessar_pedido_portal"("p_pedido_id" "uuid") IS 'M114 — Reprocessa pedido do Portal. Incrementa tentativas.';


--
-- Name: f_reprovar_pagamento_prestador("uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."f_reprovar_pagamento_prestador"("p_pagamento_id" "uuid", "p_motivo" "text" DEFAULT NULL::"text") RETURNS TABLE("sucesso" boolean, "mensagem" "text", "pagamento_id" "uuid", "status_aprovacao" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_pag    RECORD;
    v_tenant uuid;
    v_obs    text;
BEGIN
    IF auth.uid() IS NULL THEN
        RETURN QUERY SELECT false, 'USUARIO_NAO_AUTENTICADO', p_pagamento_id, NULL::text;
        RETURN;
    END IF;

    SELECT tu.tenant_id INTO v_tenant
      FROM public.tenant_usuarios tu
     WHERE tu.user_id = auth.uid() AND tu.status = 'ativo'
     LIMIT 1;

    IF v_tenant IS NULL OR NOT EXISTS (
        SELECT 1 FROM public.tenant_usuarios tu
         WHERE tu.user_id = auth.uid() AND tu.status = 'ativo'
           AND tu.papel IN ('super_admin','admin_tenant','financeiro')) THEN
        RETURN QUERY SELECT false, 'NAO_AUTORIZADO', p_pagamento_id, NULL::text;
        RETURN;
    END IF;

    SELECT p.* INTO v_pag
      FROM public.pagamentos_prestadores p
     WHERE p.id = p_pagamento_id
       FOR UPDATE;

    IF NOT FOUND THEN
        RETURN QUERY SELECT false, 'PAGAMENTO_NAO_ENCONTRADO', p_pagamento_id, NULL::text;
        RETURN;
    END IF;

    IF v_pag.os_id IS NOT NULL
       AND public.f_pp_tenant_id(v_pag.os_id) IS DISTINCT FROM v_tenant THEN
        RETURN QUERY SELECT false, 'NAO_AUTORIZADO_TENANT', v_pag.id, v_pag.status_aprovacao;
        RETURN;
    END IF;

    -- Idempotencia por estado
    IF v_pag.status_aprovacao = 'reprovado' THEN
        RETURN QUERY SELECT true, 'JA_REPROVADO', v_pag.id, v_pag.status_aprovacao;
        RETURN;
    END IF;

    IF v_pag.status_aprovacao IS DISTINCT FROM 'aguardando_aprovacao' THEN
        RETURN QUERY SELECT false, 'ESTADO_NAO_PERMITE_REPROVAR', v_pag.id, v_pag.status_aprovacao;
        RETURN;
    END IF;

    -- Neutraliza lote (se houver) — reprovado nao pode ser pago
    IF v_pag.lote_id IS NOT NULL THEN
        DELETE FROM public.lotes_pagamento_itens li WHERE li.pagamento_prestador_id = v_pag.id;
        UPDATE public.lotes_pagamento l
           SET quantidade_pagamentos = (SELECT count(*) FROM public.lotes_pagamento_itens i WHERE i.lote_id = l.id),
               valor_total = COALESCE((SELECT sum(i.valor) FROM public.lotes_pagamento_itens i WHERE i.lote_id = l.id), 0),
               updated_at = now()
         WHERE l.id = v_pag.lote_id;
    END IF;

    v_obs := CASE WHEN v_pag.observacao IS NULL OR v_pag.observacao = ''
                  THEN '[reprovar][' || to_char(now(),'YYYY-MM-DD HH24:MI') || '][' || left(auth.uid()::text,8) || '] ' || COALESCE(p_motivo,'sem motivo')
                  ELSE v_pag.observacao || E'\n[reprovar][' || to_char(now(),'YYYY-MM-DD HH24:MI') || '][' || left(auth.uid()::text,8) || '] ' || COALESCE(p_motivo,'sem motivo')
             END;

    UPDATE public.pagamentos_prestadores
       SET status_aprovacao = 'reprovado',
           elegivel_lote    = false,
           lote_id          = NULL,
           observacao       = v_obs
     WHERE id = v_pag.id;

    RETURN QUERY SELECT true, 'REPROVADO', v_pag.id, 'reprovado'::text;
END;
$$;


--
-- Name: FUNCTION "f_reprovar_pagamento_prestador"("p_pagamento_id" "uuid", "p_motivo" "text"); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."f_reprovar_pagamento_prestador"("p_pagamento_id" "uuid", "p_motivo" "text") IS 'TMS-FIN-PP-UX-02C1B: reprova workflow de prestador (aguardando_aprovacao -> reprovado). Nao toca FP/baixa.';


--
-- Name: f_responder_mensagem_torre("uuid", "text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."f_responder_mensagem_torre"("p_alocacao_id" "uuid", "p_mensagem" "text", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_authenticated_uid uuid;
  v_alocacao record;
  v_mensagem_id uuid;
  v_existente uuid;
  v_notificacao_id uuid;
BEGIN
  v_authenticated_uid := auth.uid();
  IF v_authenticated_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'USUARIO_NAO_AUTENTICADO');
  END IF;

  -- Somente usuário TMS pode responder
  IF NOT EXISTS (SELECT 1 FROM public.tenant_usuarios WHERE user_id = v_authenticated_uid) THEN
    RETURN jsonb_build_object('success', false, 'error', 'USUARIO_NAO_AUTORIZADO_TORRE');
  END IF;

  -- Idempotência (resposta da torre)
  IF p_idempotency_key IS NOT NULL AND btrim(p_idempotency_key) <> '' THEN
    SELECT id INTO v_existente FROM public.operacao_mensagens
    WHERE idempotency_key = p_idempotency_key AND sender_type = 'torre'
    LIMIT 1;
    IF v_existente IS NOT NULL THEN
      RETURN jsonb_build_object('success', true, 'duplicada', true, 'mensagem_id', v_existente);
    END IF;
  END IF;

  -- Validar alocação (para identificar o prestador e o os_id)
  SELECT id, ordem_servico_id, prestador_id, status INTO v_alocacao
  FROM public.alocacoes_escala WHERE id = p_alocacao_id;
  IF v_alocacao.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'ALOCACAO_NAO_ENCONTRADA');
  END IF;
  IF v_alocacao.prestador_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'ALOCACAO_SEM_PRESTADOR');
  END IF;

  -- Validar mensagem
  IF p_mensagem IS NULL OR btrim(p_mensagem) = '' THEN
    RETURN jsonb_build_object('success', false, 'error', 'MENSAGEM_VAZIA');
  END IF;
  IF length(p_mensagem) > 2000 THEN
    RETURN jsonb_build_object('success', false, 'error', 'MENSAGEM_MUITO_LONGA');
  END IF;

  INSERT INTO public.operacao_mensagens (
    alocacao_id, os_id, prestador_id, sender_type, sender_user_id,
    mensagem, status, idempotency_key
  ) VALUES (
    p_alocacao_id,
    v_alocacao.ordem_servico_id,
    v_alocacao.prestador_id,
    'torre',
    v_authenticated_uid,
    btrim(p_mensagem),
    'enviada',
    NULLIF(p_idempotency_key, '')
  )
  RETURNING id INTO v_mensagem_id;

  -- Notificar o App (infra real existente)
  BEGIN
    v_notificacao_id := public.f_registrar_notificacao_app(
      v_alocacao.prestador_id,
      'Nova mensagem da Torre',
      left(btrim(p_mensagem), 120),
      'operacao_mensagem',
      p_alocacao_id,
      'alocacao'
    );
  EXCEPTION WHEN OTHERS THEN
    v_notificacao_id := NULL;
  END;

  RETURN jsonb_build_object(
    'success', true,
    'mensagem_id', v_mensagem_id,
    'notificacao_id', v_notificacao_id,
    'created_at', now()
  );
END;
$$;


--
-- Name: FUNCTION "f_responder_mensagem_torre"("p_alocacao_id" "uuid", "p_mensagem" "text", "p_idempotency_key" "text"); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."f_responder_mensagem_torre"("p_alocacao_id" "uuid", "p_mensagem" "text", "p_idempotency_key" "text") IS 'A22 — Torre/TMS responde mensagem do prestador. Somente tenant_usuarios. Gera notificação para o App. Idempotente.';


--
-- Name: f_scan_validade_documentos(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."f_scan_validade_documentos"() RETURNS TABLE("candidato_id" "uuid", "nome" "text", "tipo_documento" "text", "validade" "date", "dias_para_vencer" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    rc.id AS candidato_id,
    rc.nome,
    doc->>'nome' AS tipo_documento,
    (doc->>'dataValidade')::DATE AS validade,
    ((doc->>'dataValidade')::DATE - CURRENT_DATE) AS dias_para_vencer
  FROM public.recrutamento_candidatos rc,
       jsonb_array_elements(rc.documentos) AS doc
  WHERE rc.documentos IS NOT NULL
    AND jsonb_typeof(rc.documentos) = 'array'
    AND (doc->>'dataValidade') IS NOT NULL
    AND (doc->>'dataValidade') != ''
    AND ((doc->>'dataValidade')::DATE - CURRENT_DATE) <= 30
    AND ((doc->>'dataValidade')::DATE - CURRENT_DATE) >= -365;
END;
$$;


--
-- Name: FUNCTION "f_scan_validade_documentos"(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."f_scan_validade_documentos"() IS 'REC-06.2C.1: Scan periódico de documentos vencidos/próximos. Chamado pelo eventProcessorWorker a cada 5 minutos. Não bloqueia/libera prestador.';


--
-- Name: f_sync_delivery_proof_to_entregas(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."f_sync_delivery_proof_to_entregas"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_alocacao_id UUID;
  v_prestador_id UUID;
  v_tenant_id UUID;
  v_ordem_servico_id UUID;
BEGIN
  BEGIN
    v_alocacao_id := CAST(NEW.operation_id AS UUID);
  EXCEPTION WHEN OTHERS THEN
    RETURN NEW;
  END;

  IF v_alocacao_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT ae.prestador_id, COALESCE(ae.tenant_id, NULL::uuid), ae.ordem_servico_id
  INTO v_prestador_id, v_tenant_id, v_ordem_servico_id
  FROM public.alocacoes_escala ae
  WHERE ae.id = v_alocacao_id;

  IF EXISTS (
    SELECT 1 FROM public.entregas_protocolo
    WHERE alocacao_id = v_alocacao_id
  ) THEN
    UPDATE public.entregas_protocolo SET
      prestador_id = COALESCE(v_prestador_id, prestador_id),
      ordem_servico_id = COALESCE(v_ordem_servico_id, ordem_servico_id),
      nome_recebedor = COALESCE(NEW.receiver_name, 'Motorista'),
      documento_recebedor = NEW.receiver_document,
      receiver_relationship = NEW.receiver_relationship,
      observacao = NEW.observation,
      foto_entrega_url = NEW.photo_url,
      foto_canhoto_url = NEW.foto_canhoto_url,
      assinatura_url = NEW.signature_url,
      data_hora_entrega = COALESCE(NEW.delivered_at, data_hora_entrega, NOW()),
      latitude = NEW.latitude,
      longitude = NEW.longitude,
      gps_accuracy = NEW.gps_accuracy,
      status = CASE
        WHEN NEW.status = 'delivered' THEN 'entregue'
        WHEN NEW.status = 'delivered_with_note' THEN 'entregue_ressalva'
        WHEN NEW.status = 'not_delivered' THEN 'nao_entregue'
        ELSE COALESCE(NEW.status, status)
      END,
      tenant_id = COALESCE(tenant_id, v_tenant_id, NEW.tenant_id, public.current_tenant_id_safe()),
      updated_at = NOW()
    WHERE alocacao_id = v_alocacao_id;

    RETURN NEW;
  END IF;

  INSERT INTO public.entregas_protocolo (
    alocacao_id, prestador_id, ordem_servico_id,
    nome_recebedor, documento_recebedor, receiver_relationship,
    observacao, foto_entrega_url, foto_canhoto_url, assinatura_url,
    data_hora_entrega, latitude, longitude, gps_accuracy,
    status, tenant_id
  ) VALUES (
    v_alocacao_id, v_prestador_id, v_ordem_servico_id,
    COALESCE(NEW.receiver_name, 'Motorista'),
    NEW.receiver_document, NEW.receiver_relationship,
    NEW.observation, NEW.photo_url, NEW.foto_canhoto_url, NEW.signature_url,
    COALESCE(NEW.delivered_at, NOW()),
    NEW.latitude, NEW.longitude, NEW.gps_accuracy,
    CASE
      WHEN NEW.status = 'delivered' THEN 'entregue'
      WHEN NEW.status = 'delivered_with_note' THEN 'entregue_ressalva'
      WHEN NEW.status = 'not_delivered' THEN 'nao_entregue'
      ELSE COALESCE(NEW.status, 'entregue')
    END,
    COALESCE(v_tenant_id, NEW.tenant_id, public.current_tenant_id_safe())
  )
  ON CONFLICT DO NOTHING;

  RETURN NEW;
END;
$$;


--
-- Name: f_sync_tracking_to_oper_localizacao(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."f_sync_tracking_to_oper_localizacao"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
     DECLARE v_prestador_id UUID; v_os_id UUID;
     BEGIN
       SELECT ae.prestador_id, ae.ordem_servico_id INTO v_prestador_id, v_os_id
       FROM public.alocacoes_escala ae WHERE ae.id = NEW.alocacao_id;
       INSERT INTO public.operacao_localizacao (alocacao_id, os_id, prestador_id, latitude, longitude, velocidade, precisao, tenant_id, atualizado_em)
       VALUES (NEW.alocacao_id, v_os_id, v_prestador_id, NEW.latitude, NEW.longitude, NEW.velocidade, NEW.precisao,
         COALESCE(NEW.tenant_id, public.current_tenant_id_safe()), COALESCE(NEW.captured_at, NOW()))
       ON CONFLICT DO NOTHING;
       RETURN NEW;
     END;
     $$;


--
-- Name: f_transferir_entre_contas("uuid", "uuid", numeric, "date", numeric, "text", "uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."f_transferir_entre_contas"("p_conta_origem_id" "uuid", "p_conta_destino_id" "uuid", "p_valor" numeric, "p_data" "date" DEFAULT CURRENT_DATE, "p_taxa" numeric DEFAULT 0, "p_historico" "text" DEFAULT NULL::"text", "p_usuario_id" "uuid" DEFAULT NULL::"uuid", "p_usuario_nome" "text" DEFAULT NULL::"text") RETURNS TABLE("sucesso" boolean, "mensagem" "text", "transferencia_id" "uuid")
    LANGUAGE "plpgsql"
    AS $_$
DECLARE
    v_transferencia_id UUID;
    v_origem_saldo     NUMERIC(18,2);
    v_total_sair       NUMERIC(18,2);
BEGIN
    IF p_valor IS NULL OR p_valor <= 0 THEN
        RETURN QUERY SELECT false, 'Valor da transferência deve ser maior que zero.', NULL::UUID;
        RETURN;
    END IF;

    IF p_conta_origem_id = p_conta_destino_id THEN
        RETURN QUERY SELECT false, 'Conta de origem e destino devem ser diferentes.', NULL::UUID;
        RETURN;
    END IF;

    SELECT saldo INTO v_origem_saldo
      FROM public.contas_financeiras
     WHERE id = p_conta_origem_id AND ativa = true
       FOR UPDATE;

    IF NOT FOUND THEN
        RETURN QUERY SELECT false, 'Conta de origem não encontrada ou inativa.', NULL::UUID;
        RETURN;
    END IF;

    IF NOT EXISTS (SELECT 1 FROM public.contas_financeiras WHERE id = p_conta_destino_id AND ativa = true) THEN
        RETURN QUERY SELECT false, 'Conta de destino não encontrada ou inativa.', NULL::UUID;
        RETURN;
    END IF;

    v_total_sair := p_valor + COALESCE(p_taxa, 0);
    IF v_origem_saldo < v_total_sair THEN
        RETURN QUERY SELECT false,
            'Saldo insuficiente na conta de origem. Disponível: R$ ' || v_origem_saldo || '. Necessário: R$ ' || v_total_sair || '.',
            NULL::UUID;
        RETURN;
    END IF;

    INSERT INTO public.financeiro_transferencias (
        data, conta_origem_id, conta_destino_id, valor, taxa,
        historico, usuario_id, usuario_nome, tenant_id
    ) VALUES (
        p_data, p_conta_origem_id, p_conta_destino_id, p_valor, p_taxa,
        COALESCE(p_historico, 'Transferência entre contas'),
        p_usuario_id, p_usuario_nome, public.current_tenant_id_safe()
    ) RETURNING id INTO v_transferencia_id;

    UPDATE public.contas_financeiras SET saldo = saldo - v_total_sair WHERE id = p_conta_origem_id;
    UPDATE public.contas_financeiras SET saldo = saldo + p_valor WHERE id = p_conta_destino_id;

    RETURN QUERY SELECT true, 'Transferência realizada com sucesso.', v_transferencia_id;
END;
$_$;


--
-- Name: f_trg_atualizar_status_alocacao_tracking(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."f_trg_atualizar_status_alocacao_tracking"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  
  UPDATE alocacoes_escala SET
    metadata = COALESCE(metadata, '{}'::JSONB) || jsonb_build_object(
      'ultima_posicao', jsonb_build_object(
        'latitude', NEW.latitude,
        'longitude', NEW.longitude,
        'velocidade', NEW.velocidade,
        'captured_at', NEW.captured_at,
        'atualizado_em', NOW()
      ),
      'tracking_status', 'online'
    ),
    updated_at = NOW()
  WHERE id = NEW.alocacao_id;
  
  RETURN NEW;
END;
$$;


--
-- Name: f_trg_cancelar_financeiro_alocacao(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."f_trg_cancelar_financeiro_alocacao"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_os_id TEXT;
    v_os_id_uuid UUID;
    v_error_msg TEXT;
    v_updated_receber INT;
    v_updated_pagar INT;
    v_updated_pagamentos INT;
    v_updated_os INT;
BEGIN
    IF NEW.status != 'cancelada' THEN
        RETURN NEW;
    END IF;

    IF OLD.status = 'cancelada' THEN
        RETURN NEW;
    END IF;

    v_os_id := COALESCE(NEW.ordem_servico_id::TEXT, NEW.id::TEXT);
    v_os_id_uuid := COALESCE(NEW.ordem_servico_id, NEW.id);

    BEGIN
        UPDATE public.financeiro_receber
        SET status = 'cancelada'
        WHERE os_id = v_os_id
          AND status NOT IN ('pago', 'recebido', 'cancelada');
        GET DIAGNOSTICS v_updated_receber = ROW_COUNT;
    EXCEPTION WHEN OTHERS THEN
        v_updated_receber := -1;
    END;

    BEGIN
        UPDATE public.financeiro_pagar
        SET status = 'cancelada'
        WHERE os_id = v_os_id
          AND status NOT IN ('pago', 'cancelada');
        GET DIAGNOSTICS v_updated_pagar = ROW_COUNT;
    EXCEPTION WHEN OTHERS THEN
        v_updated_pagar := -1;
    END;

    BEGIN
        UPDATE public.pagamentos_prestadores
        SET status_pagamento = 'cancelado',
            status_conferencia = 'cancelado'
        WHERE os_id = v_os_id_uuid
          AND (status_pagamento IS DISTINCT FROM 'cancelado');
        GET DIAGNOSTICS v_updated_pagamentos = ROW_COUNT;
    EXCEPTION WHEN OTHERS THEN
        v_updated_pagamentos := -1;
    END;

    -- ESCALA-E2E-03: manter ALOCACAO + OS + FINANCEIRO coerentes.
    -- Cancela a MESMA OS vinculada (sem criar nova OS / sem duplicar financeiro).
    IF NEW.ordem_servico_id IS NOT NULL THEN
        BEGIN
            UPDATE public.ordens_servico
            SET status = 'cancelada',
                updated_at = NOW()
            WHERE id = NEW.ordem_servico_id
              AND status IS DISTINCT FROM 'cancelada';
            GET DIAGNOSTICS v_updated_os = ROW_COUNT;
        EXCEPTION WHEN OTHERS THEN
            v_updated_os := -1;
        END;
    ELSE
        v_updated_os := 0;
    END IF;

    IF v_updated_receber > 0 OR v_updated_pagar > 0 OR v_updated_pagamentos > 0 OR v_updated_os > 0 THEN
        RAISE WARNING '[CANCEL] Alocação % cancelada: receber=% pagar=% pagamentos=% os=%',
            NEW.id, v_updated_receber, v_updated_pagar, v_updated_pagamentos, v_updated_os;
    END IF;

    RETURN NEW;
EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_error_msg = MESSAGE_TEXT;
    RAISE WARNING '[CANCEL-ERR] Alocação %: %', NEW.id, v_error_msg;
    RETURN NEW;
END;
$$;


--
-- Name: f_trg_event_bus_consumer(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."f_trg_event_bus_consumer"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_notification JSONB;
  v_os_status TEXT;
  v_alerta_titulo TEXT;
  v_alerta_descricao TEXT;
BEGIN
  
  
  
  IF NEW.status != 'active' OR NEW.source NOT IN ('trigger', 'service') THEN
    RETURN NEW;
  END IF;

  
  
  
  
  
  IF NEW.event_type = 'os.ordem_servico.criada' THEN
    v_notification := jsonb_build_object(
      'titulo', 'Nova Ordem de Serviço',
      'mensagem', 'OS ' || COALESCE(NEW.payload->>'numero', NEW.payload->>'os_numero', '') || ' criada.',
      'tipo', 'os_criada',
      'referencia_id', NEW.entity_id,
      'event_type', NEW.event_type
    );

    INSERT INTO portal_notificacoes (
      cliente_id, titulo, mensagem, tipo, lida, created_at
    ) VALUES (
      (NEW.payload->>'cliente_id')::UUID,
      'Nova Ordem de Serviço',
      'OS ' || COALESCE(NEW.payload->>'numero', NEW.payload->>'os_numero', '') || ' criada com sucesso.',
      'os_criada',
      false,
      NOW()
    )
    ON CONFLICT DO NOTHING;

    
    INSERT INTO escalonamentos_humanos (
      origem, modulo, tipo, titulo, descricao, prioridade, status, created_at
    ) VALUES (
      'trigger',
      'operacao',
      'os_criada',
      'Nova OS: ' || COALESCE(NEW.payload->>'numero', NEW.payload->>'os_numero', ''),
      'OS criada para ' || COALESCE(NEW.payload->>'cliente_nome', 'cliente'),
      'baixa',
      'pendente',
      NOW()
    );
  END IF;

  
  
  
  
  IF NEW.event_type = 'os.ordem_servico.finalizada' THEN
    INSERT INTO portal_notificacoes (
      cliente_id, titulo, mensagem, tipo, lida, created_at
    ) VALUES (
      (NEW.payload->>'cliente_id')::UUID,
      'OS Finalizada',
      'OS ' || COALESCE(NEW.payload->>'numero', NEW.payload->>'os_numero', '') || ' foi finalizada.',
      'os_finalizada',
      false,
      NOW()
    )
    ON CONFLICT DO NOTHING;
  END IF;

  
  
  
  
  IF NEW.event_type = 'escala.alocacao.aceita' THEN
    INSERT INTO portal_notificacoes (
      cliente_id, titulo, mensagem, tipo, lida, created_at
    ) VALUES (
      (NEW.payload->>'cliente_id')::UUID,
      'Motorista a caminho',
      'O motorista aceitou a corrida e está a caminho da coleta.',
      'motorista_aceitou',
      false,
      NOW()
    )
    ON CONFLICT DO NOTHING;
  END IF;

  
  
  
  
  IF NEW.event_type = 'escala.alocacao.concluida' THEN
    INSERT INTO portal_notificacoes (
      cliente_id, titulo, mensagem, tipo, lida, created_at
    ) VALUES (
      (NEW.payload->>'cliente_id')::UUID,
      'Entrega Realizada',
      'A entrega foi concluída. Confira os detalhes no Portal.',
      'entrega_concluida',
      false,
      NOW()
    )
    ON CONFLICT DO NOTHING;
  END IF;

  
  
  
  
  IF NEW.event_type = 'entrega.comprovante.pod_enviado' THEN
    INSERT INTO portal_notificacoes (
      cliente_id, titulo, mensagem, tipo, lida, created_at
    ) VALUES (
      (NEW.payload->>'cliente_id')::UUID,
      'Comprovante de Entrega',
      'O comprovante de entrega já está disponível.',
      'comprovante_disponivel',
      false,
      NOW()
    )
    ON CONFLICT DO NOTHING;
  END IF;

  
  
  
  
  IF NEW.event_type = 'portal.ocorrencia.aberta' THEN
    v_alerta_titulo := 'Ocorrência no Portal: ' || COALESCE(NEW.payload->>'tipo', '');
    v_alerta_descricao := COALESCE(NEW.payload->>'descricao', 'Ocorrência registrada pelo cliente.');

    INSERT INTO escalonamentos_humanos (
      origem, modulo, tipo, titulo, descricao, prioridade, status, created_at
    ) VALUES (
      'portal',
      'operacao',
      'ocorrencia_cliente',
      v_alerta_titulo,
      v_alerta_descricao,
      'alta',
      'pendente',
      NOW()
    );
  END IF;

  
  
  
  
  IF NEW.event_type = 'portal.pedido.criado' THEN
    INSERT INTO escalonamentos_humanos (
      origem, modulo, tipo, titulo, descricao, prioridade, status, created_at
    ) VALUES (
      'portal',
      'comercial',
      'novo_pedido',
      'Novo Pedido: ' || COALESCE(NEW.payload->>'numero_pedido', ''),
      'Pedido criado no Portal. Aguarda processamento.',
      'media',
      'pendente',
      NOW()
    );
  END IF;

  
  
  
  
  IF NEW.event_type = 'financeiro.receber.pago' THEN
    INSERT INTO escalonamentos_humanos (
      origem, modulo, tipo, titulo, descricao, prioridade, status, created_at
    ) VALUES (
      'trigger',
      'financeiro',
      'recebimento',
      'Pagamento Recebido: R$ ' || COALESCE(ROUND((NEW.payload->>'valor')::NUMERIC, 2)::TEXT, '0,00'),
      'Cliente: ' || COALESCE(NEW.payload->>'cliente', ''),
      'baixa',
      'resolvido',
      NOW()
    );
  END IF;

  
  UPDATE public.eventos_oficiais
  SET processed_at = NOW(),
      metadata = COALESCE(metadata, '{}'::JSONB) || jsonb_build_object('consumed_by', 'f_trg_event_bus_consumer', 'consumed_at', NOW())
  WHERE id = NEW.id;

  RETURN NEW;
END;
$_$;


--
-- Name: FUNCTION "f_trg_event_bus_consumer"(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."f_trg_event_bus_consumer"() IS 'M104 — Consumidor do Event Bus. Dispara ações automáticas baseadas no tipo do evento: notificações no portal, alertas no NOC, sincronização entre módulos.';


--
-- Name: f_trg_expiracao_oportunidade(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."f_trg_expiracao_oportunidade"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF NEW.prazo_expiracao IS NOT NULL AND NEW.prazo_expiracao < NOW() AND NEW.status = 'publicada' THEN
    NEW.status = 'expirada';
    NEW.expirada_em = NOW();
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: f_trg_fatura_itens_anti_duplicidade(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."f_trg_fatura_itens_anti_duplicidade"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_dup_id uuid;
  v_status_fatura text;
BEGIN
  SELECT status INTO v_status_fatura FROM public.faturas WHERE id = NEW.fatura_id;

  IF v_status_fatura IS DISTINCT FROM 'cancelada' THEN
    IF NEW.os_id IS NOT NULL THEN
      -- Operacao identificada pela OS (dominio os_id)
      SELECT fi.id INTO v_dup_id
      FROM public.fatura_itens fi
      JOIN public.faturas f ON f.id = fi.fatura_id
      WHERE fi.os_id = NEW.os_id
        AND fi.status = 'ativo'
        AND f.status IS DISTINCT FROM 'cancelada'
        AND fi.fatura_id IS DISTINCT FROM NEW.fatura_id
      LIMIT 1;
      IF v_dup_id IS NOT NULL THEN
        RAISE EXCEPTION 'SERVIÇO_JA_FATURADO: A OS % já está vinculada a outra fatura ativa.', NEW.os_id;
      END IF;
    ELSIF NEW.alocacao_id IS NOT NULL THEN
      -- Operacao identificada pela ALOCACAO (dominio alocacao_id); so itens sem OS
      SELECT fi.id INTO v_dup_id
      FROM public.fatura_itens fi
      JOIN public.faturas f ON f.id = fi.fatura_id
      WHERE fi.alocacao_id = NEW.alocacao_id
        AND fi.os_id IS NULL
        AND fi.status = 'ativo'
        AND f.status IS DISTINCT FROM 'cancelada'
        AND fi.fatura_id IS DISTINCT FROM NEW.fatura_id
      LIMIT 1;
      IF v_dup_id IS NOT NULL THEN
        RAISE EXCEPTION 'SERVIÇO_JA_FATURADO: A alocação % já está vinculada a outra fatura ativa.', NEW.alocacao_id;
      END IF;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: f_trg_fatura_itens_bloqueio_emissao(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."f_trg_fatura_itens_bloqueio_emissao"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_status text;
BEGIN
  SELECT status INTO v_status FROM public.faturas WHERE id = COALESCE(NEW.fatura_id, OLD.fatura_id);
  IF v_status IN ('emitida','cancelada') THEN
    -- TMS-FAT-URG-07 — única exceção: cancelamento OFICIAL do item
    -- (ativo -> cancelado) por RPC SECURITY DEFINER (current_user=postgres) ou service_role.
    IF TG_OP = 'UPDATE'
       AND NEW.status = 'cancelado'
       AND OLD.status = 'ativo'
       AND current_user IN ('postgres', 'service_role') THEN
      RETURN NEW;
    END IF;
    RAISE EXCEPTION 'FATURA_BLOQUEADA: Não é permitido alterar itens de fatura % (status %). Use cancelamento/correção controlada.', v_status, v_status;
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: f_trg_faturas_bloqueio_emissao_sem_ar(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."f_trg_faturas_bloqueio_emissao_sem_ar"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.status = 'emitida' AND NEW.conta_receber_id IS NULL THEN
    IF TG_OP = 'INSERT' THEN
      RAISE EXCEPTION 'FATURA_EMITIDA_SEM_AR: emissão deve ocorrer via f_emitir_fatura (Nº + Conta a Receber).';
    ELSIF OLD.status IS DISTINCT FROM 'emitida' THEN
      RAISE EXCEPTION 'FATURA_EMITIDA_SEM_AR: transição para emitida exige Conta a Receber (use f_emitir_fatura).';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: f_trg_faturas_protege_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."f_trg_faturas_protege_status"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    -- Fatura nova deve NASCER como 'rascunho' (cliente). INSERT com 'aprovada'/
    -- 'emitida' por authenticated seria bypass da validação -> bloqueia.
    IF NEW.status IS DISTINCT FROM 'rascunho'
       AND current_user NOT IN ('postgres', 'service_role') THEN
      RAISE EXCEPTION 'FATURA_STATUS_INSERT_INVALIDO: fatura nova deve nascer como rascunho (use o fluxo Conferência/Criar Fatura).';
    END IF;
  ELSIF NEW.status IS DISTINCT FROM OLD.status
        AND current_user NOT IN ('postgres', 'service_role') THEN
    -- Só bloqueia MUDANÇA de status. Edições de outros campos (vencimento,
    -- observação, metadata, etc.) NÃO passam por aqui.
    RAISE EXCEPTION 'FATURA_STATUS_SOMENTE_VIA_RPC: alteracao direta de status nao permitida. Use f_mover_fatura_status / f_emitir_fatura / f_cancelar_fatura.';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: f_trg_impedir_duplicidade_pedido(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."f_trg_impedir_duplicidade_pedido"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.status = 'programado' AND OLD.status IN ('programado', 'processando') THEN
    RAISE EXCEPTION 'Pedido já foi processado (status %)', OLD.status;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: f_trg_notificar_oportunidade_rede(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."f_trg_notificar_oportunidade_rede"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.status = 'publicada' THEN
    INSERT INTO public.portal_notificacoes (
      prestador_id, titulo, mensagem, tipo, origem_id, origem_tipo, lida, created_at, metadata
    ) SELECT
      p.id,
      'Nova oportunidade na Rede',
      format('Nova oportunidade #%s disponível na sua região.', UPPER(SUBSTRING(NEW.os_id::TEXT, 1, 8))),
      'nova_oportunidade',
      NEW.id,
      'rede_oportunidades',
      false,
      NOW(),
      jsonb_build_object('regiao', NEW.regiao, 'valor', NEW.valor_prestador)
    FROM public.prestadores p
    WHERE p.status = 'ativo'
      AND (NEW.regiao IS NULL OR p.regiao_principal ILIKE '%' || COALESCE(NEW.regiao, '') || '%')
    LIMIT 50; -- Evitar explosão de notificações
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: f_trg_notificar_os_para_app(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."f_trg_notificar_os_para_app"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.prestador IS NOT NULL AND (OLD IS NULL OR OLD.prestador IS DISTINCT FROM NEW.prestador) THEN
    INSERT INTO public.portal_notificacoes (
      prestador_id, titulo, mensagem, tipo, origem_id, origem_tipo, lida, created_at
    ) VALUES (
      NEW.prestador,
      'Nova operação',
      format('Nova OS %s atribuída a você.', COALESCE(NEW.numero, SUBSTRING(NEW.id::TEXT, 1, 8))),
      'nova_os',
      NEW.id,
      'ordens_servico',
      false,
      NOW()
    );
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: f_trg_novo_candidato_evento(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."f_trg_novo_candidato_evento"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_automacao_id UUID;
BEGIN
  -- Verificar se existe automação ativa do tipo 'notifcacao' (novo candidato)
  SELECT id INTO v_automacao_id
  FROM public.recrutamento_automacoes
  WHERE tipo = 'notificacao' AND status = 'ativa'
  LIMIT 1;

  -- Se não há automação ativa, apenas retorna (sem bloquear INSERT)
  IF v_automacao_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- Inserir evento no Event Bus (best-effort — não bloqueia o cadastro)
  BEGIN
    INSERT INTO public.eventos_oficiais (
      event_type, entity_type, entity_id, payload, source, visibility
    ) VALUES (
      'recrutamento.candidato.criado',
      'recrutamento_candidatos',
      NEW.id,
      jsonb_build_object(
        'candidato_id', NEW.id,
        'nome', NEW.nome,
        'telefone', NEW.telefone,
        'cidade', NEW.cidade,
        'uf', NEW.uf,
        'stage', NEW.stage,
        'score', NEW.score,
        'automacao_id', v_automacao_id
      ),
      'trigger_db',
      'internal'
    );
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'REC-06.2C.1 [novo_candidato]: falha ao inserir evento: %', SQLERRM;
  END;

  -- NÃO atualizar contadores aqui — eventProcessorWorker atualiza após processamento
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION "f_trg_novo_candidato_evento"(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."f_trg_novo_candidato_evento"() IS 'REC-06.2C.1: Detecta novo candidato e cria evento em eventos_oficiais. Contadores são atualizados apenas pelo eventProcessorWorker após processamento bem-sucedido.';


--
-- Name: f_trg_propagar_financeiro_alocacao(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."f_trg_propagar_financeiro_alocacao"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_cliente_nome TEXT; v_prestador_nome TEXT; v_prestador_doc TEXT;
  v_os_id UUID; v_os_numero TEXT; v_data_venc_30 DATE;
  v_valor_cliente NUMERIC; v_valor_prestador NUMERIC;
  v_pedagio_valor NUMERIC; v_adicional_valor NUMERIC;
  v_ajudante_valor NUMERIC; v_desconto_valor NUMERIC;
  v_outros_custos NUMERIC; v_valor_liquido NUMERIC;
  v_is_concluida BOOLEAN; v_error_msg TEXT;
  v_fallback_cliente TEXT; v_fallback_prestador TEXT;
  v_status_financeiro TEXT;
  v_reversa_cliente NUMERIC; v_reversa_prestador NUMERIC;
  v_execucao_id UUID;
BEGIN
  v_execucao_id := gen_random_uuid();
  IF NEW.status = 'cancelada' THEN RETURN NEW; END IF;
  BEGIN
    v_valor_cliente := COALESCE(NEW.valor_frete, 0);
    v_valor_prestador := COALESCE(NEW.valor_repasse, 0);
    v_pedagio_valor := COALESCE(NEW.valor_pedagio, 0);
    v_adicional_valor := COALESCE(NEW.valor_adicional, 0);
    v_ajudante_valor := COALESCE(NEW.valor_ajudante, 0);
    v_desconto_valor := COALESCE(NEW.valor_desconto_prestador, 0);
    v_reversa_cliente := COALESCE(NEW.reversa_valor_cliente, 0);
    v_reversa_prestador := COALESCE(NEW.reversa_valor_prestador, 0);
    IF v_valor_cliente = 0 AND v_valor_prestador = 0 AND v_reversa_cliente = 0 AND v_reversa_prestador = 0 THEN RETURN NEW; END IF;
    v_valor_cliente := v_valor_cliente + v_reversa_cliente;
    v_valor_prestador := v_valor_prestador + v_reversa_prestador;
    v_fallback_cliente := COALESCE(NEW.cliente_id::TEXT, 'cliente_nao_informado');
    v_fallback_prestador := COALESCE(NEW.prestador_id::TEXT, 'prestador_nao_informado');
    BEGIN
      SELECT COALESCE(c.nome_fantasia, c.razao_social, 'Cliente #' || v_fallback_cliente) INTO STRICT v_cliente_nome FROM clientes c WHERE c.id = NEW.cliente_id;
    EXCEPTION WHEN OTHERS THEN v_cliente_nome := 'Cliente #' || v_fallback_cliente; END;
    BEGIN
      SELECT COALESCE(p.nome_completo, 'Prestador #' || v_fallback_prestador), COALESCE(p.cpf_cnpj, '') INTO STRICT v_prestador_nome, v_prestador_doc FROM prestadores p WHERE p.id = NEW.prestador_id;
    EXCEPTION WHEN OTHERS THEN v_prestador_nome := 'Prestador #' || v_fallback_prestador; v_prestador_doc := ''; END;
    v_data_venc_30 := CURRENT_DATE + 30;
    v_is_concluida := (NEW.status = 'concluida' AND NEW.finalizada = true);
    v_status_financeiro := CASE WHEN v_is_concluida THEN 'aberto' ELSE 'pendente' END;
    IF NEW.ordem_servico_id IS NOT NULL THEN
      v_os_id := NEW.ordem_servico_id;
      v_os_numero := 'OS-ALOC-' || TO_CHAR(COALESCE(NEW.data_escala, CURRENT_DATE), 'YYYYMMDD') || '-' || UPPER(SUBSTRING(NEW.id::TEXT, 1, 8));
    ELSE
      v_os_id := NEW.id;
      v_os_numero := 'ALOC-' || TO_CHAR(COALESCE(NEW.data_escala, CURRENT_DATE), 'YYYYMMDD') || '-' || UPPER(SUBSTRING(NEW.id::TEXT, 1, 8));
    END IF;
    v_outros_custos := v_adicional_valor + v_ajudante_valor - v_desconto_valor;
    v_valor_liquido := v_valor_prestador + v_pedagio_valor + v_outros_custos;
    -- OS (preservado do comportamento pre-02B; casts corrigidos para schema real)
    BEGIN
      INSERT INTO ordens_servico (id, numero, cliente, cliente_id, prestador, prestador_id, status, data, tipo_veiculo, origem, destino, valor_cliente, custo_prestador, pedagio, adicionais, ajudante, descontos, tipo_reversa, reversa_qtd_volumes, observacoes_gerais, created_at, updated_at)
      VALUES (v_os_id, v_os_numero, NEW.cliente_id, v_cliente_nome, NEW.prestador_id, v_prestador_nome, CASE WHEN v_is_concluida THEN 'finalizada' ELSE 'pendente' END, COALESCE(NEW.data_escala, CURRENT_DATE), NEW.tipo_veiculo, NEW.origem, NEW.destino, v_valor_cliente, v_valor_prestador, v_pedagio_valor, to_jsonb(v_adicional_valor), to_jsonb(v_ajudante_valor), v_desconto_valor, NEW.tipo_reversa, NEW.reversa_qtd_volumes, NEW.observacoes, NOW(), NOW())
      ON CONFLICT (id) DO UPDATE SET status = CASE WHEN v_is_concluida THEN 'finalizada' ELSE 'pendente' END, valor_cliente = v_valor_cliente, custo_prestador = v_valor_prestador, tipo_reversa = COALESCE(NEW.tipo_reversa, ordens_servico.tipo_reversa), updated_at = NOW();
    EXCEPTION WHEN OTHERS THEN RAISE; END;
    -- FIX-POD-00D + ESCALA-OS-03: vincular a aloca??o AP?S garantir a OS (FK imediata)
    IF NEW.ordem_servico_id IS NULL THEN
      UPDATE alocacoes_escala SET ordem_servico_id = v_os_id WHERE id = NEW.id;
    END IF;
    -- TMS-FIN-PROG-05B: AR do cliente REMOVIDO (fonte unica = f_emitir_fatura).

    -- Pagar (CORRECAO: valor = v_valor_liquido)
    IF v_valor_prestador > 0 AND NEW.prestador_id IS NOT NULL THEN
      BEGIN
        INSERT INTO financeiro_pagar (os_id, descricao, valor, data_vencimento, status, prestador, fornecedor_id, fornecedor_nome, desconto)
        VALUES (v_os_id::TEXT, 'Repasse ' || v_os_numero || CASE WHEN v_reversa_prestador > 0 THEN ' (c/ reversa)' ELSE '' END, v_valor_liquido, v_data_venc_30, v_status_financeiro, v_prestador_nome, NEW.prestador_id, v_prestador_nome, v_desconto_valor)
        ON CONFLICT (os_id) DO UPDATE SET valor = v_valor_liquido, status = CASE WHEN v_is_concluida THEN 'aberto' WHEN financeiro_pagar.status = 'aberto' THEN 'aberto' ELSE 'pendente' END, data_vencimento = v_data_venc_30, fornecedor_id = NEW.prestador_id, fornecedor_nome = v_prestador_nome, desconto = v_desconto_valor, prestador = v_prestador_nome WHERE financeiro_pagar.status NOT IN ('pago','parcial','cancelado','cancelada');
      EXCEPTION WHEN OTHERS THEN RAISE; END;
    END IF;
    -- Pagamentos prestadores
    IF v_valor_prestador > 0 AND NEW.prestador_id IS NOT NULL THEN
      BEGIN
        INSERT INTO pagamentos_prestadores (prestador_id, prestador_nome, prestador_documento, os_id, valor_liquido, valor_servicos, pedagio, adicionais, status_conferencia, status_pagamento, origem_lancamento, quantidade_os, periodo_inicio, periodo_fim, categoria_financeira, data_prevista_pagamento, competencia, impacto_dre, impacto_fluxo_caixa)
        VALUES (NEW.prestador_id, v_prestador_nome, v_prestador_doc, v_os_id, v_valor_liquido, v_valor_prestador, v_pedagio_valor, v_outros_custos, CASE WHEN v_is_concluida THEN 'em_aberto' ELSE 'pendente' END, CASE WHEN v_is_concluida THEN 'pendente' ELSE 'nao_vencido' END, 'escala_direta', 1, COALESCE(NEW.data_escala, CURRENT_DATE), COALESCE(NEW.data_escala, CURRENT_DATE), 'Custo Logistico', v_data_venc_30, COALESCE(NEW.data_escala, CURRENT_DATE), true, true)
        ON CONFLICT (os_id) DO UPDATE SET valor_liquido = v_valor_liquido, valor_servicos = v_valor_prestador, status_conferencia = CASE WHEN v_is_concluida THEN 'em_aberto' ELSE 'pendente' END, prestador_id = NEW.prestador_id, prestador_nome = v_prestador_nome, prestador_documento = COALESCE(v_prestador_doc, '') WHERE pagamentos_prestadores.status_pagamento NOT IN ('pago','cancelado');
      EXCEPTION WHEN OTHERS THEN RAISE; END;
    END IF;
    -- Composicao
    IF v_is_concluida AND v_valor_cliente > 0 THEN
      DECLARE v_imp NUMERIC; v_seg NUMERIC; v_mb NUMERIC; v_ml NUMERIC; BEGIN
        v_imp := ROUND(v_valor_cliente * 4.5 / 100, 2);
        v_seg := ROUND(v_valor_cliente * 0.01, 2);
        v_mb := v_valor_cliente - v_valor_prestador - v_pedagio_valor - v_outros_custos;
        v_ml := v_mb - v_imp - v_seg;
        INSERT INTO composicao_financeira_os (os_id, cliente_id, prestador_id, valor_cliente, valor_prestador, imposto_percentual, imposto_valor, seguro_valor, pedagio_valor, outros_custos, combustivel_valor, ajudante_valor, adicional_valor, desconto_valor, margem_bruta, margem_liquida, percentual_margem_bruta, percentual_margem_liquida, origem_calculo)
        VALUES (v_os_id, NEW.cliente_id, NEW.prestador_id, v_valor_cliente, v_valor_prestador, 4.5, v_imp, v_seg, v_pedagio_valor, v_outros_custos, 0, v_ajudante_valor, v_adicional_valor, v_desconto_valor, v_mb, v_ml, CASE WHEN v_valor_cliente > 0 THEN ROUND(v_mb / v_valor_cliente * 100, 2) ELSE 0 END, CASE WHEN v_valor_cliente > 0 THEN ROUND(v_ml / v_valor_cliente * 100, 2) ELSE 0 END, 'escala_direta')
        ON CONFLICT (os_id) DO UPDATE SET valor_cliente = v_valor_cliente, valor_prestador = v_valor_prestador, margem_bruta = v_mb, margem_liquida = v_ml;
      EXCEPTION WHEN OTHERS THEN RAISE; END;
    END IF;
    RETURN NEW;
  EXCEPTION WHEN OTHERS THEN
    RAISE;
  END;
END;
$$;


--
-- Name: FUNCTION "f_trg_propagar_financeiro_alocacao"(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."f_trg_propagar_financeiro_alocacao"() IS 'FIN-SANE-02B — Propagacao financeira de alocacoes_escala. financeiro_pagar.valor = valor_liquido total do prestador.';


--
-- Name: f_trg_propagar_financeiro_os(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."f_trg_propagar_financeiro_os"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_cliente_nome       TEXT;
  v_prestador_nome     TEXT;
  v_prestador_doc      TEXT;
  v_data_venc_30       DATE;
  v_valor_cliente      NUMERIC;
  v_valor_prestador    NUMERIC;
  v_outros_custos      NUMERIC;
  v_valor_liquido      NUMERIC;
  v_margem_bruta       NUMERIC;
  v_margem_liquida     NUMERIC;
  v_imposto_valor      NUMERIC;
  v_seguro_valor       NUMERIC;
  v_is_finalizada      BOOLEAN;
  v_data_servico       DATE;   -- 05D.6C: data canonica do servico
BEGIN
  IF NEW.status = 'cancelada' THEN
    RETURN NEW;
  END IF;

  v_valor_cliente   := COALESCE(NEW.valor_cliente, 0);
  v_valor_prestador := COALESCE(NEW.custo_prestador, 0);

  IF v_valor_cliente = 0 AND v_valor_prestador = 0 THEN
    RETURN NEW;
  END IF;

  BEGIN
    SELECT COALESCE(c.nome_fantasia, c.razao_social, 'Cliente #' || NEW.cliente_id)
      INTO STRICT v_cliente_nome
      FROM clientes c WHERE c.id = NEW.cliente;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      v_cliente_nome := COALESCE(NEW.cliente::TEXT, 'Cliente #' || NEW.cliente_id);
    WHEN OTHERS THEN
      v_cliente_nome := COALESCE(NEW.cliente::TEXT, NEW.cliente_id, 'Cliente');
  END;

  BEGIN
    SELECT COALESCE(p.nome_completo, 'Prestador #' || NEW.prestador_id),
           COALESCE(p.cpf_cnpj, '')
      INTO STRICT v_prestador_nome, v_prestador_doc
      FROM prestadores p WHERE p.id = NEW.prestador;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      v_prestador_nome := COALESCE(NEW.prestador::TEXT, 'Prestador #' || NEW.prestador_id);
      v_prestador_doc := '';
    WHEN OTHERS THEN
      v_prestador_nome := COALESCE(NEW.prestador::TEXT, NEW.prestador_id, 'Prestador');
      v_prestador_doc := '';
  END;

  v_data_venc_30  := CURRENT_DATE + 30;
  v_is_finalizada := (NEW.status = 'finalizada');
  v_data_servico  := NEW.data;   -- 05D.6C: data canonica (operacional)

  v_outros_custos := COALESCE(
      (CASE
        WHEN NEW.adicionais IS NULL THEN 0
        WHEN jsonb_typeof(NEW.adicionais) = 'number' THEN (NEW.adicionais #>> '{}')::NUMERIC
        ELSE COALESCE((NEW.adicionais->>'valor')::NUMERIC, 0)
      END), 0
    )
    + COALESCE(
      (CASE
        WHEN NEW.ajudante IS NULL THEN 0
        WHEN jsonb_typeof(NEW.ajudante) = 'number' THEN (NEW.ajudante #>> '{}')::NUMERIC
        ELSE COALESCE((NEW.ajudante->>'valor')::NUMERIC, 0)
      END), 0
    )
    - COALESCE(NEW.descontos, 0);

  v_valor_liquido := v_valor_prestador
                   + COALESCE(NEW.pedagio, 0)
                   + v_outros_custos;

  -- TMS-FIN-PROG-05B: AR do cliente REMOVIDO (fonte unica = f_emitir_fatura).

  -- 2. financeiro_pagar (INALTERADO)
  IF v_valor_prestador > 0 AND NEW.prestador_id IS NOT NULL THEN
    PERFORM 1 FROM financeiro_pagar WHERE os_id = NEW.id::TEXT LIMIT 1;
    IF NOT FOUND THEN
      INSERT INTO financeiro_pagar (
        os_id, descricao, valor, data_vencimento, status,
        prestador, fornecedor_id, fornecedor_nome
      ) VALUES (
        NEW.id::TEXT,
        'Repasse ' || COALESCE(NEW.numero, 'OS#' || SUBSTRING(NEW.id::TEXT, 1, 8)),
        v_valor_liquido,
        v_data_venc_30,
        CASE WHEN v_is_finalizada THEN 'aberto' ELSE 'pendente' END,
        v_prestador_nome,
        NEW.prestador,
        v_prestador_nome
      );
    ELSE
      UPDATE financeiro_pagar SET
        valor          = v_valor_liquido,
        prestador      = v_prestador_nome,
        fornecedor_id  = NEW.prestador,
        fornecedor_nome = v_prestador_nome,
        status         = CASE WHEN v_is_finalizada THEN 'aberto'
                              WHEN financeiro_pagar.status = 'aberto' THEN 'aberto'
                              ELSE 'pendente' END,
        data_vencimento = v_data_venc_30,
        updated_at     = NOW()
      WHERE os_id = NEW.id::TEXT AND status NOT IN ('pago','parcial','cancelado','cancelada');
    END IF;
  END IF;

  -- 3. pagamentos_prestadores (05D.6C: periodo/competencia = data canonica)
  IF v_valor_prestador > 0 AND NEW.prestador_id IS NOT NULL THEN
    IF v_data_servico IS NULL THEN
      -- Pendencia explicita: NAO inventar data (nao usa CURRENT_DATE).
      RAISE WARNING '[PAGAMENTO_PRESTADOR_SEM_DATA] OS % sem data operacional; provisao em pagamentos_prestadores NAO criada.', NEW.id;
    ELSE
      PERFORM 1 FROM pagamentos_prestadores WHERE os_id = NEW.id LIMIT 1;
      IF NOT FOUND THEN
        INSERT INTO pagamentos_prestadores (
          prestador_id, prestador_nome, prestador_documento,
          os_id, qtd_os,
          valor_liquido, valor_servicos, pedagio, adicionais,
          status_conferencia, status_pagamento,
          origem_lancamento, quantidade_os,
          categoria_financeira, data_prevista_pagamento,
          competencia, impacto_dre, impacto_fluxo_caixa,
          periodo_inicio, periodo_fim
        ) VALUES (
          NEW.prestador,
          v_prestador_nome,
          COALESCE(v_prestador_doc, ''),
          NEW.id,
          1,
          v_valor_liquido,
          v_valor_prestador,
          COALESCE(NEW.pedagio, 0),
          v_outros_custos,
          'em_aberto',
          'pendente',
          'os_direta',
          1,
          'Custo Logístico',
          v_data_venc_30,
          v_data_servico,
          true, true,
          v_data_servico, v_data_servico
        );
      ELSE
        UPDATE pagamentos_prestadores SET
          prestador_id        = NEW.prestador,
          prestador_nome      = v_prestador_nome,
          prestador_documento = COALESCE(v_prestador_doc, ''),
          valor_liquido       = v_valor_liquido,
          valor_servicos      = v_valor_prestador,
          pedagio             = COALESCE(NEW.pedagio, 0),
          adicionais          = v_outros_custos,
          status_conferencia  = 'em_aberto',
          competencia         = v_data_servico,
          periodo_inicio      = v_data_servico,
          periodo_fim         = v_data_servico,
          updated_at          = NOW()
        WHERE os_id = NEW.id AND status_pagamento NOT IN ('pago','cancelado');
      END IF;
    END IF;
  END IF;

  -- 4. composicao_financeira_os (INALTERADO)
  IF v_is_finalizada AND v_valor_cliente > 0 THEN
    v_imposto_valor  := ROUND(v_valor_cliente * 4.5 / 100, 2);
    v_seguro_valor   := ROUND(v_valor_cliente * 0.01, 2);
    v_margem_bruta   := v_valor_cliente
                      - v_valor_prestador
                      - COALESCE(NEW.pedagio, 0)
                      - v_outros_custos;
    v_margem_liquida := v_margem_bruta - v_imposto_valor - v_seguro_valor;

    PERFORM 1 FROM composicao_financeira_os WHERE os_id = NEW.id LIMIT 1;
    IF NOT FOUND THEN
      INSERT INTO composicao_financeira_os (
        os_id, cliente_id, prestador_id,
        valor_cliente, valor_prestador,
        imposto_percentual, imposto_valor, seguro_valor,
        pedagio_valor, outros_custos,
        margem_bruta, margem_liquida,
        percentual_margem_bruta, percentual_margem_liquida,
        origem_calculo
      ) VALUES (
        NEW.id,
        NEW.cliente,
        NEW.prestador,
        v_valor_cliente,
        v_valor_prestador,
        4.5,
        v_imposto_valor,
        v_seguro_valor,
        COALESCE(NEW.pedagio, 0),
        v_outros_custos,
        v_margem_bruta,
        v_margem_liquida,
        CASE WHEN v_valor_cliente > 0
             THEN ROUND(v_margem_bruta / v_valor_cliente * 100, 2)
             ELSE 0 END,
        CASE WHEN v_valor_cliente > 0
             THEN ROUND(v_margem_liquida / v_valor_cliente * 100, 2)
             ELSE 0 END,
        'os_direta'
      );
    ELSE
      UPDATE composicao_financeira_os SET
        valor_cliente              = v_valor_cliente,
        valor_prestador            = v_valor_prestador,
        imposto_percentual         = 4.5,
        imposto_valor              = v_imposto_valor,
        seguro_valor               = v_seguro_valor,
        pedagio_valor              = COALESCE(NEW.pedagio, 0),
        outros_custos              = v_outros_custos,
        margem_bruta               = v_margem_bruta,
        margem_liquida             = v_margem_liquida,
        percentual_margem_bruta    = CASE WHEN v_valor_cliente > 0
                                          THEN ROUND(v_margem_bruta / v_valor_cliente * 100, 2)
                                          ELSE 0 END,
        percentual_margem_liquida  = CASE WHEN v_valor_cliente > 0
                                          THEN ROUND(v_margem_liquida / v_valor_cliente * 100, 2)
                                          ELSE 0 END,
        origem_calculo             = 'os_direta'
      WHERE os_id = NEW.id;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION "f_trg_propagar_financeiro_os"(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."f_trg_propagar_financeiro_os"() IS 'FIN-SANE-02B — Propagacao financeira de ordens_servico. financeiro_pagar.valor = valor_liquido total do prestador.';


--
-- Name: f_trg_rede_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."f_trg_rede_updated_at"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$$;


--
-- Name: f_trg_score_limiar_evento(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."f_trg_score_limiar_evento"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_automacao RECORD;
  v_limiar INT;
  v_eventos_inseridos INT := 0;
BEGIN
  -- Só processa se score mudou
  IF OLD.score IS NOT DISTINCT FROM NEW.score THEN
    RETURN NEW;
  END IF;

  -- Para cada automação ativa do tipo 'score'
  FOR v_automacao IN
    SELECT id, trigger
    FROM public.recrutamento_automacoes
    WHERE tipo = 'score' AND status = 'ativa'
  LOOP
    -- Extrair limiar do JSONB trigger
    v_limiar := (v_automacao.trigger->>'score_min')::INT;

    -- Se limiar não configurado ou inválido, skip
    IF v_limiar IS NULL OR v_limiar < 0 OR v_limiar > 100 THEN
      CONTINUE;
    END IF;

    -- Condição de cruzamento: OLD < limiar AND NEW >= limiar
    IF COALESCE(OLD.score, 0) < v_limiar AND NEW.score >= v_limiar THEN
      BEGIN
        INSERT INTO public.eventos_oficiais (
          event_type, entity_type, entity_id, payload, source, visibility
        ) VALUES (
          'recrutamento.score.limiar_cruzado',
          'recrutamento_candidatos',
          NEW.id,
          jsonb_build_object(
            'candidato_id', NEW.id,
            'nome', NEW.nome,
            'score_anterior', OLD.score,
            'score_novo', NEW.score,
            'limiar_configurado', v_limiar,
            'classificacao', NEW.classificacao_comprometimento,
            'automacao_id', v_automacao.id
          ),
          'trigger_db',
          'internal'
        );
        v_eventos_inseridos := v_eventos_inseridos + 1;
      EXCEPTION WHEN OTHERS THEN
        RAISE WARNING 'REC-06.2C.1 [score_limiar]: falha ao inserir evento: %', SQLERRM;
      END;
    END IF;
  END LOOP;

  -- NÃO atualizar contadores aqui — eventProcessorWorker atualiza após processamento
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION "f_trg_score_limiar_evento"(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."f_trg_score_limiar_evento"() IS 'REC-06.2C.1: Detecta cruzamento de limiar de score (OLD < limite AND NEW >= limite). Cria evento por cada automação ativa do tipo score. Contadores atualizados pelo worker.';


--
-- Name: f_trg_tracking_iniciado(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."f_trg_tracking_iniciado"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
    DECLARE
      v_count INT;
    BEGIN
      SELECT COUNT(*) INTO v_count 
        FROM portal_tracking_realtime 
        WHERE alocacao_id = NEW.alocacao_id;
      
      IF v_count = 1 THEN
        INSERT INTO eventos_oficiais (
          tenant_id, event_type, entity_type, entity_id,
          status, source, visibility, payload, metadata
        ) VALUES (
          COALESCE(NEW.tenant_id, current_tenant_id_safe()),
          'tracking.iniciado',
          'alocacao',
          NEW.alocacao_id,
          'pendente',
          'sistema',
          'public',
          jsonb_build_object(
            'title', 'Rastreamento iniciado',
            'description', 'Motorista começou a transmitir localização'
          ),
          jsonb_build_object(
            'alocacao_id', NEW.alocacao_id,
            'prestador_id', NEW.prestador_id,
            'os_id', NEW.os_id,
            'latitude', NEW.latitude,
            'longitude', NEW.longitude
          )
        );
      END IF;
      RETURN NEW;
    END;
    $$;


--
-- Name: f_trg_validade_documento_evento(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."f_trg_validade_documento_evento"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_automacao_id UUID;
  v_doc JSONB;
  v_nome TEXT;
  v_validade DATE;
  v_dias INTEGER;
  v_documento_status TEXT;
BEGIN
  -- Verificar se existe automação ativa do tipo 'validade_documento'
  SELECT id INTO v_automacao_id
  FROM public.recrutamento_automacoes
  WHERE tipo = 'validade_documento' AND status = 'ativa'
  LIMIT 1;

  -- Se não há automação ativa, retorna
  IF v_automacao_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- Iterar documentos do array JSONB
  IF NEW.documentos IS NOT NULL AND jsonb_typeof(NEW.documentos) = 'array' THEN
    FOR v_doc IN SELECT jsonb_array_elements(NEW.documentos)
    LOOP
      v_nome := v_doc->>'nome';
      v_documento_status := v_doc->>'status';

      -- Pular se não tem data de validade
      BEGIN
        v_validade := (v_doc->>'dataValidade')::DATE;
      EXCEPTION WHEN OTHERS THEN
        CONTINUE;
      END;

      IF v_validade IS NULL THEN
        CONTINUE;
      END IF;

      v_dias := v_validade - CURRENT_DATE;

      -- Documento vencido (dias < 0) ou próximo do vencimento (≤30 dias)
      IF v_dias <= 30 THEN
        BEGIN
          INSERT INTO public.eventos_oficiais (
            event_type, entity_type, entity_id, payload, source, visibility
          ) VALUES (
            'recrutamento.documento.vencimento_proximo',
            'recrutamento_candidatos',
            NEW.id,
            jsonb_build_object(
              'candidato_id', NEW.id,
              'nome_candidato', NEW.nome,
              'tipo_documento', v_nome,
              'validade', v_validade::TEXT,
              'dias_para_vencer', v_dias,
              'status_documento', v_documento_status,
              'ja_vencido', v_dias < 0,
              'automacao_id', v_automacao_id
            ),
            'trigger_db',
            'internal'
          );
        EXCEPTION WHEN OTHERS THEN
          RAISE WARNING 'REC-06.2C.1 [validade_doc]: falha ao inserir evento: %', SQLERRM;
        END;
      END IF;
    END LOOP;
  END IF;

  -- NÃO atualizar contadores aqui — eventProcessorWorker atualiza após processamento
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION "f_trg_validade_documento_evento"(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."f_trg_validade_documento_evento"() IS 'REC-06.2C.1: Detecta documentos com validade ≤30 dias no JSONB documentos. Cria evento por documento vencido/próximo. Contadores atualizados pelo worker. NÃO bloqueia/libera prestador — apenas gera alerta.';


--
-- Name: f_usuario_pode_acessar_cliente("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."f_usuario_pode_acessar_cliente"("p_cliente_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
        DECLARE v_tenant_id uuid; v_papel text;
        BEGIN
          SELECT tu.tenant_id, COALESCE(tu.papel, '') INTO v_tenant_id, v_papel
          FROM public.tenant_usuarios tu WHERE tu.user_id = auth.uid();
          IF v_tenant_id IS NULL THEN RETURN false; END IF;
          IF v_papel IN ('super_admin', 'admin') THEN RETURN true; END IF;
          IF EXISTS (SELECT 1 FROM public.clientes c WHERE c.id = p_cliente_id AND c.tenant_id = v_tenant_id)
          THEN RETURN true; END IF;
          RETURN false;
        END; $$;


--
-- Name: FUNCTION "f_usuario_pode_acessar_cliente"("p_cliente_id" "uuid"); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."f_usuario_pode_acessar_cliente"("p_cliente_id" "uuid") IS 'M113 — Verifica se o usuário autenticado tem permissão para acessar dados de um cliente específico.';


--
-- Name: f_usuario_pode_acessar_tenant("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."f_usuario_pode_acessar_tenant"("p_tenant_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_tenant_id uuid;
  v_papel text;
BEGIN
  SELECT tu.tenant_id, COALESCE(tu.papel, '') INTO v_tenant_id, v_papel
  FROM public.tenant_usuarios tu
  WHERE tu.user_id = auth.uid()
  LIMIT 1;

  IF v_tenant_id IS NULL THEN
    RETURN false;
  END IF;

  -- super_admin/admin liberados (padrão atual do projeto)
  IF v_papel IN ('super_admin', 'admin') THEN
    RETURN true;
  END IF;

  -- demais usuários: somente no próprio tenant; tenant nulo vira o próprio
  RETURN COALESCE(p_tenant_id, v_tenant_id) = v_tenant_id;
END;
$$;


--
-- Name: FUNCTION "f_usuario_pode_acessar_tenant"("p_tenant_id" "uuid"); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."f_usuario_pode_acessar_tenant"("p_tenant_id" "uuid") IS 'HOTFIX CLIENTES RLS — valida acesso por tenant (NEW.tenant_id) via tenant_usuarios. SECURITY DEFINER, search_path vazio. super_admin/admin liberados; demais apenas no próprio tenant. Grants: authenticated + service_role.';


--
-- Name: f_validar_pod_operacao("uuid", "uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."f_validar_pod_operacao"("p_alocacao_id" "uuid", "p_auth_uid" "uuid", "p_prestador_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_is_express boolean;
  v_ok boolean;
BEGIN
  SELECT (
      lower(coalesce(ae.operation_mode,'')) = 'express'
      OR lower(coalesce(ae.metadata->>'tipo','')) IN ('express','motoboy','avulso','avulsa')
      OR lower(coalesce(ae.metadata->'app_motorista'->>'tipo_jornada','')) = 'express'
    )
  INTO v_is_express
  FROM public.alocacoes_escala ae
  WHERE ae.id = p_alocacao_id;

  IF v_is_express IS NULL THEN
    RETURN false;
  END IF;

  IF v_is_express THEN
    SELECT EXISTS (
      SELECT 1 FROM public.delivery_proofs dp
      WHERE dp.operation_id = p_alocacao_id::text
        AND (dp.driver_id = p_auth_uid::text OR dp.driver_id = p_prestador_id::text)
        AND coalesce(dp.status,'') <> 'not_delivered'
        AND public.f_pod_referencia_remota(dp.photo_url)
        AND public.f_pod_referencia_remota(dp.foto_canhoto_url)
    ) INTO v_ok;
  ELSE
    SELECT EXISTS (
      SELECT 1 FROM public.delivery_proofs dp
      WHERE dp.operation_id = p_alocacao_id::text
        AND (dp.driver_id = p_auth_uid::text OR dp.driver_id = p_prestador_id::text)
        AND coalesce(dp.status,'') <> 'not_delivered'
        AND public.f_pod_referencia_remota(dp.signature_url)
        AND btrim(coalesce(dp.receiver_name,'')) <> ''
    ) INTO v_ok;
  END IF;

  RETURN coalesce(v_ok, false);
END;
$$;


--
-- Name: fn_audit_liberado_app(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."fn_audit_liberado_app"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  c_priv constant text[] := ARRAY[
    'liberado_app','status','status_operacional','data_aprovacao','auth_user_id',
    'origem_cadastro','score_interno','ultimo_usuario','cpf_cnpj','rg','rg_ie',
    'data_nascimento','observacoes','observacoes_torre','avaliacao_operacional',
    'indice_comparecimento','indice_entrega_prazo','indice_aceite','qtd_operacoes',
    'banco','agencia','conta','digito','tipo_conta','favorecido','cpf_cnpj_favorecido',
    'chave_pix','tipo_chave_pix','retencoes','retencoes_descontos',
    'conta_contabil','centro_custo',
    'valor_diaria','valor_km','valor_saida','fixo_mensal','valor_ajudante',
    'valor_espera','valor_reentrega','valor_devolucao',
    'periodicidade_pagamento','prazo_pagamento','forma_preferencial',
    'forma_preferencial_pagamento'];
  c_meta_allow constant text[] := ARRAY['disponivel_app','status_operacional_app'];
  v_uid    uuid := auth.uid();
  v_role   text := coalesce(auth.role(), current_setting('role', true), 'anon');
  v_tipo   text;
  v_motivo text;
  v_col    text;
  v_meta_changed text[];
BEGIN
  v_tipo := CASE
              WHEN v_role = 'service_role' THEN 'service_role'
              WHEN v_uid IS NULL           THEN 'anon'
              WHEN EXISTS (SELECT 1 FROM tenant_usuarios tu WHERE tu.user_id = v_uid)
                                           THEN 'tms'
              ELSE 'prestador'
            END;
  v_motivo := nullif(current_setting('app.audit_motivo', true), '');

  BEGIN
    FOR v_col IN SELECT unnest(c_priv) LOOP
      IF to_jsonb(NEW) -> v_col IS DISTINCT FROM to_jsonb(OLD) -> v_col THEN
        INSERT INTO public.liberado_app_audit
          (prestador_id, campo, valor_anterior, valor_novo,
           actor_user_id, actor_role, actor_tipo, acao, motivo, tenant_snapshot)
        VALUES
          (NEW.id, v_col,
           left(coalesce(to_jsonb(OLD) ->> v_col, ''), 4000),
           left(coalesce(to_jsonb(NEW) ->> v_col, ''), 4000),
           v_uid, v_role, v_tipo, 'update', v_motivo, public.current_tenant_id_safe());
      END IF;
    END LOOP;

    IF NEW.metadata IS DISTINCT FROM OLD.metadata THEN
      SELECT array_agg(k) INTO v_meta_changed
        FROM (SELECT coalesce(a.key, b.key) AS k
                FROM jsonb_each(coalesce(OLD.metadata, '{}'::jsonb)) a
                FULL JOIN jsonb_each(coalesce(NEW.metadata, '{}'::jsonb)) b
                  ON a.key = b.key
               WHERE coalesce(a.value::text, ' ')
                     IS DISTINCT FROM coalesce(b.value::text, ' ')) s;

      IF cardinality(coalesce(v_meta_changed, ARRAY[]::text[])) > 0
         AND NOT EXISTS (SELECT 1 FROM unnest(v_meta_changed) k
                          WHERE NOT (k = ANY (c_meta_allow))) THEN
        INSERT INTO public.liberado_app_audit
          (prestador_id, campo, valor_anterior, valor_novo,
           actor_user_id, actor_role, actor_tipo, acao, motivo, tenant_snapshot)
        VALUES
          (NEW.id, 'metadata',
           left(coalesce(OLD.metadata::text, ''), 4000),
           left(coalesce(NEW.metadata::text, ''), 4000),
           v_uid, v_role, v_tipo, 'update', v_motivo, public.current_tenant_id_safe());
      END IF;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    RAISE LOG 'ADM-APP-02C.2 auditoria ignorada (nao bloqueia): %', SQLERRM;
  END;

  RETURN NEW;
END;
$$;


--
-- Name: fn_guardar_privilegio_prestador(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."fn_guardar_privilegio_prestador"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  c_priv constant text[] := ARRAY[
    'liberado_app','status','status_operacional','data_aprovacao','auth_user_id',
    'origem_cadastro','score_interno','ultimo_usuario','cpf_cnpj','rg','rg_ie',
    'data_nascimento','observacoes','observacoes_torre','avaliacao_operacional',
    'indice_comparecimento','indice_entrega_prazo','indice_aceite','qtd_operacoes',
    'banco','agencia','conta','digito','tipo_conta','favorecido','cpf_cnpj_favorecido',
    'chave_pix','tipo_chave_pix','retencoes','retencoes_descontos',
    'conta_contabil','centro_custo',
    'valor_diaria','valor_km','valor_saida','fixo_mensal','valor_ajudante',
    'valor_espera','valor_reentrega','valor_devolucao',
    'periodicidade_pagamento','prazo_pagamento','forma_preferencial',
    'forma_preferencial_pagamento'];
  -- chaves de metadata que o APP tem contrato real para escrever
  -- (driver_profile_repository.dart: setDisponivel / updateStatusOperacional)
  c_meta_allow constant text[] := ARRAY['disponivel_app','status_operacional_app'];

  v_uid          uuid;
  v_role         text;
  v_authorized   boolean := false;
  v_changed      text[]  := ARRAY[]::text[];
  v_meta_changed text[]  := ARRAY[]::text[];
  v_meta_extra   text[]  := ARRAY[]::text[];
  v_col          text;
BEGIN
  v_uid  := auth.uid();
  v_role := coalesce(auth.role(), current_setting('role', true), 'anon');

  IF v_role = 'service_role' THEN
    v_authorized := true;
  ELSIF current_user IN ('postgres','supabase_admin')
        OR current_setting('is_superuser')::boolean THEN
    v_authorized := true;
  ELSIF v_uid IS NOT NULL AND EXISTS (
          SELECT 1 FROM tenant_usuarios tu WHERE tu.user_id = v_uid) THEN
    v_authorized := true;
  END IF;

  IF v_authorized THEN
    RETURN NEW;
  END IF;

  FOR v_col IN SELECT unnest(c_priv) LOOP
    IF to_jsonb(NEW) -> v_col IS DISTINCT FROM to_jsonb(OLD) -> v_col THEN
      v_changed := v_changed || v_col;
    END IF;
  END LOOP;

  IF cardinality(v_changed) > 0 THEN
    RAISE LOG 'ADM-APP-02C.2 BLOQUEADO (A-9): role=% uid=% campos=%',
              v_role, v_uid, array_to_string(v_changed, ',');
    RAISE EXCEPTION
      'ADM-APP-02C.2: alteracao de campo privilegiado de prestador negada (campos: %)',
      array_to_string(v_changed, ',')
      USING ERRCODE = '42501',
            HINT   = 'Somente TMS (tenant_usuarios), service_role ou o owner do banco alteram estes campos.';
  END IF;

  IF NEW.metadata IS DISTINCT FROM OLD.metadata THEN
    SELECT array_agg(k) INTO v_meta_changed
      FROM (SELECT coalesce(a.key, b.key) AS k
              FROM jsonb_each(coalesce(OLD.metadata, '{}'::jsonb)) a
              FULL JOIN jsonb_each(coalesce(NEW.metadata, '{}'::jsonb)) b
                ON a.key = b.key
             WHERE coalesce(a.value::text, ' ')
                   IS DISTINCT FROM coalesce(b.value::text, ' ')) s;

    IF cardinality(coalesce(v_meta_changed, ARRAY[]::text[])) > 0 THEN
      SELECT array_agg(k) INTO v_meta_extra
        FROM unnest(v_meta_changed) k WHERE NOT (k = ANY (c_meta_allow));

      IF cardinality(coalesce(v_meta_extra, ARRAY[]::text[])) > 0 THEN
        RAISE LOG 'ADM-APP-02C.2 BLOQUEADO (A-9 metadata): role=% uid=% chaves=%',
                  v_role, v_uid, array_to_string(v_meta_extra, ',');
        RAISE EXCEPTION
          'ADM-APP-02C.2: alteracao de metadata com chaves privilegiadas negada (chaves: %)',
          array_to_string(v_meta_extra, ',')
          USING ERRCODE = '42501',
                HINT   = 'O APP so pode alterar metadata.disponivel_app e metadata.status_operacional_app.';
      END IF;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


