-- Name: ocorrencias_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."ocorrencias_updated_at"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    NEW.updated_at = now();
    RETURN NEW;
END;
$$;


SET default_tablespace = '';

SET default_table_access_method = "heap";

--
-- Name: automacoes_fila; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."automacoes_fila" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "regra_id" "uuid",
    "tipo" "text" NOT NULL,
    "canal" "text" NOT NULL,
    "destino" "text" NOT NULL,
    "assunto" "text",
    "mensagem" "text" NOT NULL,
    "payload" "jsonb" DEFAULT '{}'::"jsonb",
    "status" "text" DEFAULT 'pendente'::"text",
    "tentativas" integer DEFAULT 0,
    "max_tentativas" integer DEFAULT 3,
    "agendado_para" timestamp with time zone DEFAULT "now"(),
    "processado_em" timestamp with time zone,
    "erro" "text",
    "created_at" timestamp with time zone DEFAULT "now"(),
    "executar_em" timestamp with time zone DEFAULT "now"(),
    "prioridade" character varying(20) DEFAULT 'normal'::character varying,
    "ultimo_erro" "text"
);


--
-- Name: pull_automacoes_pendentes(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."pull_automacoes_pendentes"("limit_num" integer DEFAULT 20) RETURNS SETOF "public"."automacoes_fila"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY
  WITH selecionados AS (
    SELECT id
    FROM public.automacoes_fila
    WHERE status = 'pendente'
      AND executar_em <= now()
      AND tentativas < max_tentativas
    ORDER BY 
      CASE prioridade 
        WHEN 'critica' THEN 1 
        WHEN 'alta' THEN 2 
        WHEN 'normal' THEN 3 
        WHEN 'baixa' THEN 4 
        ELSE 5 
      END ASC,
      executar_em ASC
    LIMIT limit_num
    FOR UPDATE SKIP LOCKED
  )
  UPDATE public.automacoes_fila f
  SET status = 'processando'
  FROM selecionados s
  WHERE f.id = s.id
  RETURNING f.*;
END;
$$;


--
-- Name: recuperar_rotinas_travadas(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."recuperar_rotinas_travadas"() RETURNS TABLE("rotina_id" "uuid", "execucao_id" "uuid", "minutos_travado" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
    BEGIN
      RETURN QUERY
      WITH travadas AS (
        SELECT re.rotina_id, re.id AS execucao_id,
               EXTRACT(EPOCH FROM (now() - re.started_at)) / 60 AS minutos
        FROM rotinas_execucoes_ia re
        WHERE re.status = 'running'
          AND re.started_at < now() - interval '5 minutes'
      )
      UPDATE rotinas_execucoes_ia re
      SET status = 'error',
          erro = 'Timeout automático: execução travada por mais de 5 minutos',
          logs = COALESCE(re.logs, '') || E'
[' || now()::text || '] TIMEOUT: execução travada',
          finished_at = now()
      FROM travadas t
      WHERE re.id = t.execucao_id;

      RETURN QUERY
      UPDATE rotinas_ia r
      SET status = 'error'::text::status_rotina_ia
      FROM travadas t
      WHERE r.id = t.rotina_id
        AND r.status = 'running'::text::status_rotina_ia;

      RETURN QUERY
      SELECT t.rotina_id, t.execucao_id, t.minutos
      FROM travadas t;
    END;
    $$;


--
-- Name: recusar_viagem("text", "uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."recusar_viagem"("token_acesso" "text", "escala_id" "uuid", "motivo" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    motorista_id UUID;
BEGIN
    SELECT motorista_id INTO motorista_id FROM motorista_app_sessoes WHERE token = token_acesso AND ativo = TRUE;
    IF motorista_id IS NULL THEN
        RAISE EXCEPTION 'Token inválido ou sessão expirada';
    END IF;
    UPDATE escala_operacional
    SET status = 'recusado', observacoes = motivo, atualizado_em = now()
    WHERE id = escala_id AND prestador_id = motorista_id;
END;
$$;


