CREATE FUNCTION "public"."registrar_checkin_motorista"("token_acesso" "text", "escala_id" "uuid", "tipo" "text", "latitude" numeric, "longitude" numeric, "observacao" "text" DEFAULT NULL::"text") RETURNS "void"
