        ),
        jsonb_build_object(
          'trigger_name', 'trg_evento_os_status_changed',
          'source_table', 'ordens_servico'
        )
      )
      ON CONFLICT (event_type, entity_type, entity_id)
      WHERE event_type NOT LIKE 'auth.%'
      DO NOTHING;
      RETURN NEW;
    END;
    $$;


