--
-- Name: user_has_tenant_access("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."user_has_tenant_access"("p_tenant_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
    RETURN EXISTS (
        SELECT 1 FROM tenant_usuarios
        WHERE tenant_id = p_tenant_id
          AND user_id = auth.uid()
          AND status = 'ativo'
    );
END;
$$;


--
-- Name: FUNCTION "user_has_tenant_access"("p_tenant_id" "uuid"); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."user_has_tenant_access"("p_tenant_id" "uuid") IS 'Verifica se o usuario atual (auth.uid()) tem acesso ativo ao tenant informado.';


--
-- Name: user_tenant_role("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."user_tenant_role"("p_tenant_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
    v_papel TEXT;
BEGIN
    SELECT papel INTO v_papel FROM tenant_usuarios
    WHERE tenant_id = p_tenant_id AND user_id = auth.uid() AND status = 'ativo';
    RETURN v_papel;
END;
$$;


--
-- Name: FUNCTION "user_tenant_role"("p_tenant_id" "uuid"); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."user_tenant_role"("p_tenant_id" "uuid") IS 'Retorna o papel (papel) do usuario atual no tenant informado, ou NULL se nao tiver vinculo.';


