    CONSTRAINT "_hml_seed_checkpoint_duracao_ms_check" CHECK ((("duracao_ms" IS NULL) OR ("duracao_ms" >= 0))),
    CONSTRAINT "_hml_seed_checkpoint_status_check" CHECK (("status" = ANY (ARRAY['pendente'::"text", 'concluido'::"text", 'falhou'::"text"]))),
