-- Name: portal_tracking_realtime; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."portal_tracking_realtime" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "cliente_id" "uuid",
    "os_id" "uuid",
    "prestador_id" "uuid",
    "veiculo_id" "uuid",
    "status" "text" DEFAULT 'offline'::"text",
    "latitude" numeric,
    "longitude" numeric,
    "eta_min" integer,
    "velocidade" numeric,
    "bateria" numeric,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb",
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "alocacao_id" "uuid",
    "captured_at" timestamp with time zone,
    "precisao" numeric,
    "direcao" numeric,
    "tenant_id" "uuid" DEFAULT "public"."current_tenant_id_safe"(),
    "created_at" timestamp with time zone DEFAULT "now"(),
    "origem" "text" DEFAULT 'app_motorista'::"text",
    CONSTRAINT "chk_tracking_coords_validas" CHECK (((("latitude" IS NULL) AND ("longitude" IS NULL)) OR ((("latitude" >= ('-90'::integer)::numeric) AND ("latitude" <= (90)::numeric)) AND ("latitude" <> (0)::numeric)) OR ((("longitude" >= ('-180'::integer)::numeric) AND ("longitude" <= (180)::numeric)) AND ("longitude" <> (0)::numeric))))
);

ALTER TABLE ONLY "public"."portal_tracking_realtime" REPLICA IDENTITY FULL;


--
-- Name: TABLE "portal_tracking_realtime"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE "public"."portal_tracking_realtime" IS 'M106 — FONTE ÚNICA DE VERDADE para rastreamento em tempo real. Populada pelo App Motorista via RPC registrar_posicao_motorista(). Consumida por: Portal Cliente (PortalTrackingMap), NOC (TorreControle), Event Bus (tracking.iniciado). Realtime habilitado.';


