    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "recrutamento_whatsapp_config_status_check" CHECK (("status" = ANY (ARRAY['desconectado'::"text", 'aguardando_qr'::"text", 'conectado'::"text"])))
);


--
-- Name: recrutamento_whatsapp_conversas; Type: TABLE; Schema: public; Owner: -
--

