--
-- Name: vw_hierarquia_tabelas; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."vw_hierarquia_tabelas" AS
 SELECT 'tabelas_valores'::"text" AS "tipo",
    "id",
    "nome",
    "cliente",
    "tipo_veiculo",
    "valor_base",
    "franquia_km",
    "valor_km_excedente",
    "percentual_prestador",
    "universal",
    "data_inicio",
    "data_fim",
    "versao",
    "prioridade",
    "ativo",
    "created_at",
    "updated_at",
        CASE
            WHEN "universal" THEN 3
            WHEN (("cliente" IS NOT NULL) AND ("data_inicio" IS NOT NULL)) THEN 1
            WHEN ("cliente" IS NOT NULL) THEN 2
            ELSE 4
        END AS "nivel_hierarquia"
   FROM "public"."tabelas_valores" "t"
  WHERE ("ativo" = true);


