    "created_at",
    "escala_id"
   FROM "public"."motorista_checkins" "c"
  WHERE ("prestador_id" = "auth"."uid"());


--
-- Name: vw_motorista_dashboard; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."vw_motorista_dashboard" AS
 SELECT "m"."id" AS "motorista_id",
    "m"."nome_completo" AS "motorista_nome",
    "os"."id" AS "escala_id",
    "os"."status",
    "os"."inicio_previsto",
    "os"."fim_previsto",
    "v"."placa",
    "v"."modelo",
    "os"."prioridade",
    "os"."observacoes"
   FROM (("public"."escala_operacional" "os"
     JOIN "public"."prestadores" "m" ON (("os"."prestador_id" = "m"."id")))
     LEFT JOIN "public"."veiculos" "v" ON (("os"."veiculo_id" = "v"."id")))
  WHERE ("os"."prestador_id" = "auth"."uid"());


