CREATE VIEW "public"."vw_motorista_financeiro" AS
 SELECT "f"."id" AS "financeiro_id",
    "f"."valor",
    "f"."status",
    "f"."vencimento",
    "os"."id" AS "escala_id",
    "os"."status" AS "operacao_status"
   FROM ("public"."financeiro_pagar" "f"
     LEFT JOIN "public"."ordens_servico" "os" ON ((("f"."os_id")::"uuid" = "os"."id")))
  WHERE ("f"."fornecedor_id" = "auth"."uid"());


