  WHERE (("l"."id" = "lotes_pagamento_itens"."lote_id") AND ("tu"."user_id" = "auth"."uid"()) AND ("tu"."status" = 'ativo'::"text") AND ("tu"."papel" = ANY (ARRAY['super_admin'::"text", 'admin_tenant'::"text", 'financeiro'::"text"]))))));


